import type { Structure } from './structures'

export const GENRE_STRUCTURES: Structure[] = [{"id":"g0-whodunit-fairplay","category":"미스터리·추리","name":"후던잇 (공정한 게임 본격 추리)","desc":"애거사 크리스티·엘러리 퀸 계열의 정통 본격. 닫힌 사건 현장, 한정된 용의자, 독자에게 단서를 공평하게 제시하고 탐정이 논리로 진범을 지목하는 '범인 맞히기' 구조. 핵심은 단서의 은닉과 공개, 그리고 마지막 역전이다.","beats":[{"title":"제1막 · 무대 설치와 살인","synopsis":"폐쇄된 공간과 인물군을 세우고 첫 시신으로 게임을 개시한다.","folder":true,"children":[{"title":"닫힌 무대와 인물 소개","synopsis":"고립된 저택·섬·열차 등 외부와 차단된 공간을 설정하고, 각 용의자에게 직업·관계·표면적 알리바이를 부여한다. 독자가 인물표를 머릿속에 그릴 수 있도록 6~8명 이내로 압축하라."},{"title":"긴장의 복선 깔기","synopsis":"피해자가 될 인물이 누군가에게 미움받고 있음을, 협박·말다툼·유산 다툼 등으로 자연스럽게 흘린다. 동시에 진짜 단서를 무해해 보이는 디테일에 섞어 한 번 노출한다(나중에 회수할 것)."},{"title":"첫 번째 살인","synopsis":"충격적이되 불가해한 방식으로 시신이 발견된다. 시신의 위치·시각·잠긴 문 같은 '풀어야 할 수수께끼'를 명확히 던지고, 사망 추정 시각으로 알리바이 게임의 룰을 확정한다."}]},{"title":"제2막 · 수사와 거짓 알리바이","synopsis":"탐정이 진술을 수집하고 모든 용의자가 동시에 의심스러워지게 만든다.","folder":true,"children":[{"title":"탐정의 등장과 심문","synopsis":"외부의 명탐정 혹은 아마추어 탐정이 사건에 개입해 용의자들을 차례로 심문한다. 각 진술에 미세한 모순(시각·소지품·동선)을 하나씩 심어 독자가 메모하게 만든다."},{"title":"두 번째 살인 / 알리바이 붕괴","synopsis":"유력 용의자가 다음 피해자가 되거나, 누군가의 알리바이가 무너진다. 용의 구도를 뒤엎어 '가장 의심스러운 자가 곧 범인은 아니다'라는 본격의 룰을 작동시킨다."},{"title":"물리적 단서의 검증","synopsis":"발자국·시계·재떨이·필적 등 물증을 탐정이 재검토한다. 독자에게 공정하게 보여주되, 결정적 의미는 아직 해석하지 않은 채 남겨 둔다."}]},{"title":"제3막 · 오도와 도전","synopsis":"그럴듯한 가짜 해답으로 독자를 한 번 속이고 추리 도전을 건다.","folder":true,"children":[{"title":"잘못된 해답(레드 헤링)","synopsis":"탐정 또는 경찰이 논리적으로 보이는 1차 결론을 내리고 특정 인물을 체포 직전까지 몬다. 독자가 '이게 답이구나' 믿게 만든 뒤 결정적 반증 하나를 남겨 둔다."},{"title":"독자에의 도전 / 결정적 깨달음","synopsis":"엘러리 퀸식으로 '단서는 모두 제시됐다'를 암시하는 순간. 탐정이 사소한 위화감(앞서 흘린 디테일)에서 진실을 역산하는 유레카 비트를 배치한다."}]},{"title":"제4막 · 응접실의 해명","synopsis":"전원을 모아 단서를 재배열하고 진범을 지목한다.","folder":true,"children":[{"title":"전원 소집","synopsis":"탐정이 모든 용의자를 한자리에 모은다. 긴장을 끌어올리며 한 사람씩 혐의를 논리로 제거하는 소거법 연출을 시작한다."},{"title":"단서의 재배열과 진범 지목","synopsis":"앞서 흩뿌린 단서들을 시간 순·논리 순으로 꿰어 단 하나의 결론으로 수렴시킨다. 트릭의 정체와 동기를 함께 밝혀 '왜 이 사람만 가능했는가'를 증명한다."},{"title":"범인의 자백과 여운","synopsis":"진범이 무너지며 동기를 토로한다. 정의 회복과 함께, 풀린 뒤에야 보이는 첫 장면의 복선을 짧게 회수하며 닫는다."}]}]},{"id":"g0-howdunit-inverted","category":"미스터리·추리","name":"하우던잇 (도서倒敍·불가능 범죄)","desc":"콜롬보·후지코 F 계열의 도서추리와 존 딕슨 카의 밀실/불가능 범죄. 범인은 처음부터 공개되고, 독자의 관심은 '어떻게 저질렀나'와 '어떻게 들통나나'에 집중된다. 트릭의 정교함과 단 하나의 실수가 생명이다.","beats":[{"title":"제1부 · 완전범죄의 설계","synopsis":"범인 시점에서 살인 계획과 실행을 보여준다.","folder":true,"children":[{"title":"범인과 동기 공개","synopsis":"지적이고 유능한 범인을 주인공급으로 그린다. 살인을 결심하게 된 절박한 동기(배신·협박·자기방어)를 설득력 있게 깔아 독자가 묘하게 응원하게 만든다."},{"title":"트릭의 정밀 설계","synopsis":"밀실·원격 알리바이·시간차 같은 핵심 트릭을 범인이 준비하는 과정을 보여준다. 단, 나중에 약점이 될 '단 하나의 미세한 흠'을 독자 몰래 심어 둔다."},{"title":"실행과 위장","synopsis":"살인을 실행하고 현장을 위장한다. 완벽해 보이는 마무리를 강조하되, 범인이 미처 통제하지 못한 우연 변수(목격·물건 위치·날씨)를 슬쩍 노출한다."}]},{"title":"제2부 · 불가능의 벽","synopsis":"수사관이 도저히 풀 수 없어 보이는 현장과 마주한다.","folder":true,"children":[{"title":"수사관의 등장과 직감","synopsis":"허술해 보이지만 집요한 형사가 등장한다. 물증은 범인을 가리키지 않지만, 형사는 사소한 위화감 하나에 꽂혀 범인 주위를 맴돌기 시작한다."},{"title":"표면상 완벽한 알리바이","synopsis":"범인이 철벽 알리바이로 수사를 막아낸다. '범행이 물리적으로 불가능하다'는 벽을 세워 독자에게도 트릭의 견고함을 각인시킨다."},{"title":"심리전의 시작","synopsis":"형사와 범인이 정중한 대화 속에서 신경전을 벌인다. 형사가 던지는 무심한 질문이 범인의 약점을 정확히 건드려 범인이 내심 동요하게 만든다."}]},{"title":"제3부 · 균열","synopsis":"완전범죄에 첫 금이 가고 범인이 무리수를 둔다.","folder":true,"children":[{"title":"결정적 모순의 발견","synopsis":"형사가 1부에서 심어둔 '단 하나의 흠'을 포착한다. 사망 시각, 물건의 미세한 위치, 범인만 알 수 있었던 정보 등 트릭의 급소를 짚는다."},{"title":"범인의 추가 은폐와 자충수","synopsis":"궁지에 몰린 범인이 증거 인멸이나 2차 범행을 시도하다 오히려 결정적 꼬리를 잡힌다. 영리한 자가 무너지는 아이러니를 강조한다."}]},{"title":"제4부 · 함정과 자백","synopsis":"수사관이 트릭을 역재현해 범인을 몰아넣는다.","folder":true,"children":[{"title":"트릭의 재현과 입증","synopsis":"형사가 범인 앞에서 트릭의 작동 원리를 그대로 시연하거나 재구성해 '당신만이 이렇게 할 수 있었다'를 증명한다. 독자에게 트릭의 전모를 공개하는 카타르시스 비트."},{"title":"마지막 한 마디와 붕괴","synopsis":"콜롬보식으로 형사가 '한 가지만 더…'라며 결정적 증거를 들이민다. 범인이 체념하며 동기를 토로하고, 인간적 연민과 정의가 교차하는 여운으로 닫는다."}]}]},{"id":"g0-cozy-amateur","category":"미스터리·추리","name":"코지 미스터리 (생활밀착 아마추어 탐정)","desc":"미스 마플·제시카 플레처 계열의 코지. 작은 마을·서점·찻집 같은 따뜻한 배경에서 비전문가 탐정이 일상 관찰력으로 사건을 푼다. 폭력은 절제되고, 공동체·인물관계·생활 디테일이 단서가 된다.","beats":[{"title":"제1장 · 정겨운 일상","synopsis":"공동체의 평화로운 풍경과 주인공의 생활을 세운다.","folder":true,"children":[{"title":"마을과 단골들의 소개","synopsis":"베이커리·헌책방·민박 같은 거점과 그곳을 드나드는 이웃들을 정감 있게 그린다. 각 인물의 버릇·소문·관계를 일상 대화로 자연스럽게 깐다(훗날의 단서)."},{"title":"주인공의 매력과 특기","synopsis":"참견 좋아하는 점주·은퇴 교사·요리사 등 비전문가 주인공의 관찰벽과 인맥을 보여준다. 직업적 지식(요리·원예·뜨개)이 추리 도구가 될 것임을 암시한다."},{"title":"불협화음의 씨앗","synopsis":"마을 행사·축제·개업을 앞두고 묵은 갈등이나 외지인의 등장으로 잔잔한 긴장을 만든다. 곧 피해자가 될 인물의 미움받는 면모를 가볍게 노출한다."}]},{"title":"제2장 · 평화를 깨는 죽음","synopsis":"비폭력적·우연한 발견으로 사건이 시작되고 엉뚱한 사람이 의심받는다.","folder":true,"children":[{"title":"시신의 발견","synopsis":"잔혹 묘사 없이 시신이 발견된다(축제장·정원·가게 뒤편 등). 충격보다 '믿기지 않는다'는 공동체의 반응에 초점을 둔다."},{"title":"엉뚱한 용의자 지목","synopsis":"경찰이 주인공의 친구나 주인공 본인을 성급히 의심한다. 주인공이 '직접 진실을 밝혀야 할' 개인적 동기를 부여하는 비트."},{"title":"수사 결심","synopsis":"주인공이 단골·친구의 정보망을 동원해 비공식 조사를 시작한다. 경찰과의 가벼운 마찰과 협력 관계를 설정한다."}]},{"title":"제3장 · 동네 한 바퀴 탐문","synopsis":"생활 속 관찰과 수다로 단서를 모은다.","folder":true,"children":[{"title":"수다와 소문 속의 단서","synopsis":"이웃과의 대화·뒷담화에서 알리바이의 균열과 숨은 관계가 드러난다. 시시한 잡담 속에 진짜 단서를 묻어 두는 코지 특유의 기법을 쓴다."},{"title":"생활 지식의 활용","synopsis":"주인공의 특기(레시피·꽃말·계절감)가 시각·동기·위장 트릭의 허점을 짚는 열쇠가 된다. '전문가가 못 본 것을 생활인이 본다'를 보여준다."},{"title":"위험의 접근","synopsis":"주인공이 핵심에 다가가자 경고·미행·작은 사고가 발생한다. 살벌하지 않게, 그러나 범인이 가까이 있음을 독자에게 알린다."}]},{"title":"제4장 · 따뜻한 결말","synopsis":"공동체 자리에서 진실을 밝히고 일상을 회복한다.","folder":true,"children":[{"title":"진범과의 대면","synopsis":"주인공이 의외의 인물을 진범으로 지목한다. 격렬한 액션 대신 대화·심리로 자백을 끌어내고, 동기에 인간적 슬픔을 담는다."},{"title":"공동체의 회복","synopsis":"사건이 마무리되고 마을이 일상으로 돌아온다. 주인공의 관계 변화(우정·로맨스)와 다음 사건의 씨앗을 살짝 남기며 따뜻하게 닫는다."}]}]},{"id":"g0-hardboiled-noir","category":"미스터리·추리","name":"하드보일드·느와르 (거리의 사립탐정)","desc":"챈들러·해밋 계열. 냉소적인 1인칭 사립탐정이 부패한 도시를 헤매며 의뢰를 좇다 거대한 비리에 휘말린다. 사건 해결보다 도덕적 회색지대, 팜파탈, 폭력과 환멸의 분위기가 본질이다.","beats":[{"title":"제1부 · 의뢰","synopsis":"냉소적 탐정에게 수상한 의뢰가 들어온다.","folder":true,"children":[{"title":"탐정의 세계 소개","synopsis":"낡은 사무실, 위스키, 1인칭 냉소적 내레이션으로 주인공과 부패한 도시를 각인시킨다. 돈도 명예도 없지만 자기 원칙만은 지키는 인물상을 세운다."},{"title":"의뢰인의 등장(팜파탈/거물)","synopsis":"매혹적이거나 권력 있는 의뢰인이 단순해 보이는 일(실종자 찾기·협박 처리)을 맡긴다. 그 진술에 명백한 거짓이 섞여 있음을 탐정이 직감하게 한다."},{"title":"사건 수임과 첫 미행","synopsis":"탐정이 의심을 품은 채 일을 받아들이고 첫 조사에 나선다. 도시의 밑바닥을 훑으며 사건이 보기보다 크다는 첫 신호를 깐다."}]},{"title":"제2부 · 도시의 진창","synopsis":"단순한 사건이 부패의 그물로 확장되고 폭력이 닥친다.","folder":true,"children":[{"title":"확장되는 사건","synopsis":"의뢰를 좇다 살인·뇌물·조직범죄가 얽힌 더 큰 음모와 마주친다. 경찰·정치인·갱이 모두 한통속일 수 있음을 암시한다."},{"title":"구타와 경고","synopsis":"탐정이 폭력배에게 두들겨 맞거나 협박당한다. 물러서지 않는 고집을 통해 캐릭터를 입증하고, 위험의 규모를 독자에게 체감시킨다."},{"title":"팜파탈과의 위험한 거래","synopsis":"여성 인물과의 긴장·유혹·배신 가능성을 전면화한다. 탐정이 그녀를 믿어야 할지 의심해야 할지 끝까지 흔들리게 만든다."}]},{"title":"제3부 · 배신과 시체","synopsis":"신뢰가 무너지고 진짜 적이 드러나기 시작한다.","folder":true,"children":[{"title":"믿었던 인물의 배신","synopsis":"조력자·의뢰인·연인 중 하나가 탐정을 속였음이 드러난다. 모두가 거짓말쟁이인 세계의 환멸을 정점으로 끌어올린다."},{"title":"또 다른 죽음과 누명","synopsis":"새 시신이 나오고 탐정이 용의자로 몰리거나 누명을 쓴다. 경찰과 범죄조직 양쪽에 쫓기는 막다른 상황을 만든다."}]},{"title":"제4부 · 씁쓸한 진실","synopsis":"탐정이 진상을 밝히지만 정의는 온전히 회복되지 않는다.","folder":true,"children":[{"title":"진상 폭로","synopsis":"탐정이 음모의 핵심과 진범을 밝힌다. 권력 상층부가 연루돼 법으로 다 단죄할 수 없는 회색의 진실을 드러낸다."},{"title":"대가와 환멸","synopsis":"탐정이 진실을 위해 연인·돈·동료를 잃는다. 사건은 끝났지만 도시는 그대로인, 씁쓸한 1인칭 독백으로 닫는다."}]}]},{"id":"g0-unreliable-twist","category":"미스터리·추리","name":"서술 트릭·신뢰할 수 없는 화자","desc":"애크로이드 살인사건·여섯 번째 감각·길리언 플린 계열. 화자나 서술 자체가 독자를 속이는 구조. 마지막 한 장에서 지금까지의 모든 장면이 재해석되는 '인식의 역전'이 핵심이며, 재독 시 모든 단서가 들어맞아야 한다.","beats":[{"title":"제1막 · 믿음직한 화자","synopsis":"독자가 화자를 전적으로 신뢰하도록 만든다.","folder":true,"children":[{"title":"공감 가는 화자 구축","synopsis":"1인칭 또는 밀착 시점으로 화자를 솔직하고 평범하게 그려 독자가 무조건 신뢰하게 만든다. 동시에 결말의 반전을 지탱할 '거짓 없이 쓰였지만 오해를 유도하는' 문장을 심는다."},{"title":"사건의 제시","synopsis":"실종·살인·사고가 발생하고 화자가 사건을 설명한다. 화자의 해석을 곧 진실로 받아들이게 유도하되, 회수 가능한 빈틈(생략·모호한 대명사·시점의 공백)을 남긴다."},{"title":"표면적 수사 시작","synopsis":"화자가 사건을 좇거나 수사에 협력한다. 독자가 화자와 한편이라 느끼게 만들어, 화자가 곧 의심 대상일 가능성을 차단한다."}]},{"title":"제2막 · 어긋나는 조각들","synopsis":"미세한 위화감을 쌓되 합리화로 덮는다.","folder":true,"children":[{"title":"설명되지 않는 디테일","synopsis":"타임라인의 공백, 화자가 회피하는 화제, 타인의 이상한 반응 등 작은 균열을 흩뿌린다. 독자가 눈치채더라도 곧 그럴듯하게 무마되도록 배치한다."},{"title":"가짜 용의 구도","synopsis":"명백한 제3의 용의자를 세워 의심을 그쪽으로 몰아간다. 진짜 트릭(화자·서술 자체)에서 독자의 시선을 떼어 놓는다."},{"title":"관점의 균열","synopsis":"다른 인물의 진술이나 문서가 화자의 서술과 미묘하게 충돌한다. 독자에게 '무언가 잘못됐다'는 불안을 처음 심되 정체는 숨긴다."}]},{"title":"제3막 · 전복의 일격","synopsis":"지금까지의 전제를 뒤집는 단 하나의 사실을 공개한다.","folder":true,"children":[{"title":"결정적 폭로","synopsis":"화자가 범인이거나, 죽은 사람이거나, 시점·시간·정체가 거짓이었음이 드러난다. 한 문장 혹은 한 장면으로 독자의 인식 틀 전체를 무너뜨린다."},{"title":"전면 재해석","synopsis":"앞서 흩뿌린 단서·문장들을 새 진실의 빛으로 다시 비춘다. '거짓말은 한 적 없다, 당신이 오해했을 뿐'임을 증명해 공정성을 확보한다."}]},{"title":"제4막 · 재독의 보상","synopsis":"반전의 여진과 두 번째 읽기의 단서를 정돈한다.","folder":true,"children":[{"title":"동기와 전말 정리","synopsis":"화자가 왜 이렇게 서술했는지, 트릭의 전모와 동기를 밝힌다. 반전이 충격용이 아니라 주제(죄책감·자기기만·정체성)와 맞물리게 한다."},{"title":"마지막 여운과 복선 회수","synopsis":"첫 장면의 문장이 전혀 다른 의미로 되읽히는 마무리를 둔다. 독자가 책장을 덮고 다시 첫 페이지로 돌아가고 싶게 만드는 잔향을 남긴다."}]}]},{"id":"g1-ticking-clock","category":"스릴러·서스펜스","name":"타임어택 (시한폭탄형 스릴러)","desc":"물리적·명시적 데드라인이 서사 전체를 압박하는 구조. 인질·폭탄·바이러스 확산·납치 골든타임처럼 '남은 시간'이 카운트다운되며, 독자는 시계가 0이 되기 전 주인공이 막아낼 수 있을지에 매달린다. 24, 본 시리즈, 더 록, 스피드 같은 액션 스릴러의 핵심 골격.","beats":[{"title":"1막 — 카운트다운 점화","synopsis":"위협의 정체와 마감 시한이 명확히 선언되는 도입부. 시간이 흐르고 있음을 독자에게 각인시킨다.","folder":true,"children":[{"title":"평온의 균열","synopsis":"주인공의 일상(가능하면 직업적 유능함이 드러나는 순간)을 짧게 보여준 뒤, 정상 상태가 한순간에 깨지는 사건을 배치한다. 독자가 '잃을 것'을 먼저 각인하도록 주인공이 지키려는 대상(가족·도시·승객)을 클로즈업."},{"title":"데드라인 선언","synopsis":"폭탄 타이머·인질 처형 예고·바이러스 잠복기 등 정확한 시한을 수치로 못 박는다. 'X시간 안에'라는 문장이 독자 머릿속에 박히게 쓰고, 실패 시 치를 구체적 대가(사망자 수, 폭발 반경)를 명시."},{"title":"주인공 강제 소환","synopsis":"주인공이 이 사건에서 도망칠 수 없는 이유를 만든다. 개인적 연루(인질이 가족), 직업적 책임(현장 유일 전문가), 혹은 적의 지명 도발. 거부 불가능성을 확보해 이후 모든 무모한 선택을 정당화."}]},{"title":"2막 — 추격과 장애물 누적","synopsis":"남은 시간이 줄어드는 동안 해결을 가로막는 장애물이 연쇄적으로 등장. 각 장면 끝에 시계를 노출해 압박을 갱신.","folder":true,"children":[{"title":"첫 단서, 첫 함정","synopsis":"주인공이 위협을 추적할 실마리를 얻지만, 그 추적 자체가 적이 설계한 미로의 일부였음을 드러낸다. 한 걸음 전진할 때마다 시간이 더 빠르게 소모되는 거래 구조를 보여줄 것."},{"title":"신뢰의 붕괴","synopsis":"조력자·상부·시스템이 주인공을 방해하거나 배신한다. 관료적 무능, 내부 첩자, 잘못된 표적 지목 등으로 주인공을 고립시켜 '혼자 시계와 싸우는' 그림을 강화."},{"title":"리버스(역전 카드)","synopsis":"중간 지점에서 위협의 규모나 정체가 예상보다 크다는 사실이 드러난다. 폭탄이 하나가 아니거나, 진짜 표적이 따로 있거나. 데드라인이 더 가까워지거나 추가되어 절망을 한 단계 끌어올린다."},{"title":"희생적 우회","synopsis":"시간을 벌기 위해 주인공이 작은 손실(자기 부상, 보조 목표 포기, 동료 위험 노출)을 감수하는 장면. 카운트다운이 위험 수준으로 떨어진 시점에 배치해 긴장 최고조 직전을 만든다."}]},{"title":"3막 — 제로 직전의 해제","synopsis":"시계가 한 자릿수로 떨어진 가운데 최종 대결과 해제 시도가 동시에 벌어지는 클라이맥스.","folder":true,"children":[{"title":"최후의 진입","synopsis":"주인공이 위협의 핵심 장소·인물에 도달한다. 물리적 장벽(경비·지형·시간차)을 실시간으로 돌파하며, 초 단위로 줄어드는 시계를 교차 편집하듯 서술."},{"title":"와이어 컷 (해제의 순간)","synopsis":"폭탄 해체·인질 구출·코드 입력 등 단 한 번의 선택에 모든 것이 걸리는 지점. 일부러 실패 가능성을 한 번 보여준 뒤(잘못된 선·예상 밖 변수) 마지막 순간에 해결하거나, 의도된 비극을 택한다."},{"title":"여진과 대가","synopsis":"위협 해제 직후의 정적. 살린 것과 잃은 것을 정산하고, 주인공이 치른 대가(트라우마·관계 균열·다음 위협의 암시)를 짧게 남겨 안도와 씁쓸함을 동시에 준다."}]}]},{"id":"g1-domestic-suspense","category":"스릴러·서스펜스","name":"도메스틱 서스펜스 (가까운 사람이 위험)","desc":"위협이 외부 괴한이 아니라 배우자·가족·이웃 같은 친밀한 관계 안에서 자라나는 구조. '나를 가장 잘 아는 사람이 가장 위험하다'는 공포가 핵심. 나를 찾아줘, 사라진 소녀, 기차 안의 낯선 여자, 비포 아이 고 투 슬립 등 도메스틱 누아르의 골격. 신뢰할 수 없는 화자와 일상 공간의 잠식이 무기.","beats":[{"title":"1막 — 완벽해 보이는 일상","synopsis":"겉보기 안정적인 가정/관계를 세우고, 그 표면에 미세한 균열을 심는 단계.","folder":true,"children":[{"title":"이상적 표면","synopsis":"부러울 만큼 정상적인 관계·가정을 묘사하되, 화자의 시점 자체에 미묘한 결함(기억 공백, 과장된 행복, 회피하는 화제)을 심어 독자가 무의식적으로 의심하게 만든다."},{"title":"작은 이물감","synopsis":"사라진 물건, 맞지 않는 진술, 낯선 전화 한 통 같은 '일상의 어긋남'을 배치한다. 단독으로는 사소하지만 화자가 과민 반응하는지 둔감한지를 통해 신뢰도를 흔든다."},{"title":"사건의 방아쇠","synopsis":"실종·죽음·고백·발견 등 일상을 미스터리로 전환시키는 결정적 사건. 외부 수사보다 화자의 사적 의심이 먼저 작동하도록 구성해 '집 안의 조사'로 무게중심을 둔다."}]},{"title":"2막 — 의심의 전이","synopsis":"의심이 인물들 사이를 옮겨 다니며, 누가 화자를 속이는지(혹은 화자가 독자를 속이는지) 끊임없이 재배치된다.","folder":true,"children":[{"title":"용의 선상의 친밀함","synopsis":"가장 가까운 사람(배우자·부모·절친)에게 의심이 향하는 장면. 사랑과 공포가 같은 대상에게 향하는 양가감정을 묘사하고, 결정적 증거 직전에 무해한 설명도 함께 제시해 판단을 유보시킨다."},{"title":"과거의 누설","synopsis":"회상·일기·옛 지인을 통해 인물의 숨겨진 과거가 조금씩 새어 나온다. 이중 타임라인(과거/현재)을 교차해 현재의 위협이 오래된 비밀에서 비롯됐음을 암시할 것."},{"title":"화자 신뢰도 균열","synopsis":"화자 자신이 거짓말하거나 기억을 왜곡하고 있다는 단서를 흘린다. 독자가 '내가 따라온 시점이 틀렸을 수 있다'고 의심하게 만들어 도메스틱 서스펜스 특유의 발밑이 꺼지는 감각을 형성."},{"title":"고립의 심화","synopsis":"주인공이 도움을 구할 외부 통로(경찰·친구·직장)에서 점점 차단된다. '미친 사람' 취급을 받거나 증거가 사라지며, 안전해야 할 집이 가장 위험한 밀실로 변한다."}]},{"title":"3막 — 가면 벗기","synopsis":"진짜 위협의 정체와 동기가 드러나고, 친밀한 공간 안에서 최종 대치가 벌어진다.","folder":true,"children":[{"title":"반전의 폭로","synopsis":"독자가 믿어온 구도를 뒤집는 진실 공개. 가해자/피해자 역할의 전복, 화자가 숨긴 진짜 의도, 혹은 공모 관계를 드러낸다. 앞에서 심은 이물감들이 일제히 회수되도록 설계."},{"title":"집 안의 대치","synopsis":"도망갈 곳 없는 사적 공간(집·차·침실)에서의 직접 충돌. 화려한 액션 대신 심리적 협박·폭로전·도구가 된 일상 사물로 긴장을 만든다."},{"title":"회복 불가능한 정상","synopsis":"생존했더라도 관계와 자아가 영구히 변한 상태를 그린다. 표면적 안정으로의 복귀를 보여주되, 마지막 한 줄로 위협의 잔재나 화자의 변질을 암시해 여운을 남긴다."}]}]},{"id":"g1-conspiracy-paranoia","category":"스릴러·서스펜스","name":"음모·편집증 스릴러 (거대한 적과 외톨이)","desc":"평범한 개인이 우연히 거대 권력(국가·기업·조직)의 비밀을 목격하고, 시스템 전체가 그를 지우려 추격하는 구조. 진실을 폭로해야 살아남는 '한 명 대 모두'의 구도. 콘돌의 3일, 펠리컨 브리프, 미션 임파서블, 토니 스콧/그리샴 계열의 골격. 누구도 믿을 수 없는 편집증적 분위기가 핵심.","beats":[{"title":"1막 — 잘못된 목격","synopsis":"평범한 주인공이 봐서는 안 될 것을 보거나 알게 되어, 의도치 않게 표적이 되는 단계.","folder":true,"children":[{"title":"정상 궤도의 주인공","synopsis":"분석가·기자·말단 직원 등 시스템 안에서 평범히 기능하는 주인공을 보여준다. 그의 일상적 유능함(관찰력·집요함)이 나중에 생존 무기가 되도록 미리 심을 것."},{"title":"치명적 정보 접촉","synopsis":"우연한 문서·통화·증인을 통해 권력의 비밀에 접촉한다. 본인은 그 정보의 가치를 아직 모르게 하고, 독자에게만 위험 신호를 흘려 서스펜스(주인공보다 독자가 더 아는 상태)를 발생."},{"title":"첫 청소 시도","synopsis":"조직이 주인공 주변을 제거하기 시작한다(동료 몰살·집 습격). 주인공이 간발의 차로 살아남으며 '나도 지워질 대상'임을 깨닫는 충격의 전환점."}]},{"title":"2막 — 도주와 진실 추적","synopsis":"추격을 피해 달아나면서 동시에 자신이 가진 정보의 의미를 해독해 가는 이중 과제 단계.","folder":true,"children":[{"title":"신뢰의 불가능","synopsis":"도움을 청한 상대가 조직과 연결돼 있거나, 안전가옥이 함정으로 드러난다. '누구도 믿을 수 없다'는 편집증을 사건으로 증명해 주인공과 독자를 함께 고립."},{"title":"위태로운 동맹","synopsis":"어쩔 수 없이 손잡게 되는 조력자(처음엔 적대적이거나 무관심한)를 등장시킨다. 신뢰가 검증되지 않은 채로 협력해야 하는 긴장, 배신 가능성의 상존을 유지."},{"title":"퍼즐 조각 결합","synopsis":"흩어진 정보가 연결되며 음모의 윤곽이 드러난다. 단, 핵심 증거나 증인이 손에 잡힐 듯 매번 빠져나가게 하여 추적의 동력과 좌절을 반복 공급."},{"title":"내부자 폭로","synopsis":"조직 내부의 양심·내분을 활용해 음모의 정점(배후·진짜 목적)을 노출한다. 동시에 주인공의 적이 단순 악당이 아니라 시스템 자체임을 드러내 규모감을 키운다."}]},{"title":"3막 — 폭로 아니면 소멸","synopsis":"증거를 세상에 터뜨리려는 마지막 시도와, 그것을 막으려는 권력의 총력전.","folder":true,"children":[{"title":"공개의 무대 설정","synopsis":"기자회견·생방송·공개 데이터 유출 등 진실을 '여러 사람 앞에' 내놓을 수밖에 없는 상황을 만든다. 한 명이 죽어도 정보가 살아남도록 설계하는 주인공의 보험 장치를 보여줄 것."},{"title":"최종 추격전","synopsis":"증거 전달 직전, 조직이 마지막으로 모든 자원을 동원해 주인공을 막는다. 물리적 추격과 정보 차단이 동시에 벌어지는 교차 클라이맥스로 구성."},{"title":"불완전한 승리","synopsis":"진실은 폭로됐지만 권력의 핵심은 빠져나가거나, 주인공은 돌아갈 곳을 잃은 채 남는다. '이긴 듯 진' 결말로 음모 스릴러 특유의 냉소와 경계를 남긴다."}]}]},{"id":"g1-cat-and-mouse","category":"스릴러·서스펜스","name":"추적자 대 추적당하는 자 (캣앤마우스 듀얼 시점)","desc":"수사자(형사·프로파일러)와 범죄자(연쇄살인범·천재 사기꾼)가 서로를 의식하며 벌이는 두뇌 게임 구조. 양측 시점을 교차해 독자가 범인을 알면서도 추적의 긴장을 즐기는 서스펜스. 양들의 침묵, 세븐, 레드 드래곤, 캐치 미 이프 유 캔 계열. 사냥꾼과 사냥감의 역할이 수시로 뒤집히는 것이 묘미.","beats":[{"title":"1막 — 게임의 개시","synopsis":"추적자와 추적 대상이 각각 소개되고, 둘을 엮는 첫 충돌이 발생하는 단계.","folder":true,"children":[{"title":"추적자의 결함","synopsis":"수사자를 소개하되 명백한 약점(과거 실패·트라우마·아웃사이더 위치)을 부여한다. 이 결함이 범인에게 파고들 틈이 되고, 동시에 인간적 몰입 포인트가 되게 설계."},{"title":"사냥감의 솜씨","synopsis":"범죄자의 시점 혹은 그 흔적을 통해 그의 지능·패턴·의식(시그니처)을 드러낸다. 범인을 매력적이고 유능하게 그려 독자가 '잡힐까'와 '잡힐 수 있을까'를 동시에 궁금해하게 만든다."},{"title":"첫 수와 응수","synopsis":"범죄 현장 혹은 도발(편지·전화·단서 흘리기)을 통해 둘의 게임이 시작된다. 추적자가 범인의 존재를 체감하고, 범인도 추적자를 특정 라이벌로 인식하는 상호 호명의 순간."}]},{"title":"2막 — 수읽기 전쟁","synopsis":"양측이 서로의 다음 수를 예측하고 함정을 파는 두뇌 대결. 우위가 번갈아 넘어간다.","folder":true,"children":[{"title":"범인의 내부 잠입","synopsis":"범인이 수사 정보·수사자의 사생활에 침투하거나, 반대로 추적자가 범인의 심리에 빙의한다. '상대처럼 생각해야 잡는다'는 위험한 동화를 묘사해 경계를 흐린다."},{"title":"거짓 승리","synopsis":"추적자가 범인을 잡았다고 믿는 순간을 만든다. 엉뚱한 용의자 체포, 모방범, 위장된 시신 등으로 가짜 해결을 제시한 뒤 진범이 건재함을 드러내 충격을 준다."},{"title":"표적이 된 추적자","synopsis":"범인이 추적자 본인이나 그가 아끼는 사람을 다음 표적으로 삼는다. 사냥꾼이 사냥감으로 전환되는 역전 지점으로, 게임이 추상적 두뇌전에서 개인적 생존전으로 격상."},{"title":"패턴의 균열","synopsis":"추적자가 범인의 시그니처에서 미세한 예외(감정의 누설·실수)를 포착한다. 완벽해 보이던 사냥감의 인간적 약점을 통해 마지막 공략 지점을 확보."}]},{"title":"3막 — 최후의 대면","synopsis":"두 지능이 마침내 직접 마주하는 클라이맥스와 게임의 종결.","folder":true,"children":[{"title":"함정의 설치","synopsis":"양측이 동시에 상대를 향해 덫을 놓는 장면. 추적자의 계획과 범인의 계획을 교차로 보여주되, 누구의 함정이 진짜인지 끝까지 감춰 클라이맥스의 불확실성을 극대화."},{"title":"대면과 진실","synopsis":"둘이 직접 마주 앉거나 맞붙는 정점. 말의 칼날을 주고받으며 범인의 진짜 동기와 추적자의 결함이 동시에 폭발한다. 물리 충돌보다 심리적 우열의 전환에 집중."},{"title":"이긴 자의 그림자","synopsis":"게임의 승자를 정하되, 승리에 그늘을 남긴다. 범인을 잡았으나 추적자가 그를 닮아버렸거나, 범인이 죽으며 더 큰 게임(후계자·미해결)을 예고한다."}]}]},{"id":"g1-unreliable-twist","category":"스릴러·서스펜스","name":"서술 트릭·반전 서스펜스 (믿을 수 없는 진실)","desc":"독자가 따라온 서사 자체가 교묘하게 설계된 거짓이며, 결말의 단 한 번의 폭로로 모든 장면의 의미가 재배열되는 구조. 시점·시간·정체의 트릭이 무기. 셔터 아일랜드, 식스 센스, 유주얼 서스펙트, 곤 걸 후반부, 디 아더스 계열. 재독(再讀)을 견디는 정교한 복선 설계가 생명.","beats":[{"title":"1막 — 가짜 전제 깔기","synopsis":"독자가 의심 없이 받아들일 '기본 전제'를 세우는 단계. 이 전제 자체가 나중에 뒤집힐 거짓말이다.","folder":true,"children":[{"title":"선명한 프레임 제시","synopsis":"장르·상황·주인공의 정체성을 또렷하게 규정한다(이 사람은 형사다, 이건 수사다 등). 너무 분명해 의심할 필요가 없게 만들어, 바로 그 분명함을 반전의 표적으로 삼는다."},{"title":"이중 의미 복선","synopsis":"표면상 한 뜻으로 읽히지만 진실을 알면 정반대로 읽히는 대사·행동·소품을 자연스럽게 심는다. 첫 독자는 흘려보내고 재독 시 무릎을 치게 만드는 것이 핵심. 최소 3개 이상 분산 배치."},{"title":"공모하는 조연","synopsis":"주변 인물들이 주인공/독자에게 진실을 숨기는 데 가담하고 있음을, 표면적으로는 평범한 상호작용으로 위장해 보여준다. 이들의 어색한 반응을 '성격'으로 오인하게 유도."}]},{"title":"2막 — 균열의 누적","synopsis":"전제와 맞지 않는 작은 모순들이 쌓이지만, 그럴듯한 설명으로 매번 봉합되는 단계.","folder":true,"children":[{"title":"불일치 신호","synopsis":"사람들의 반응·물리적 디테일·시간 흐름이 미묘하게 어긋나는 순간을 흩뿌린다. 독자가 '뭔가 이상한데' 느끼되 확신하지 못할 강도로 조절하는 것이 관건."},{"title":"합리화의 함정","synopsis":"주인공(또는 화자)이 모순을 그럴듯하게 설명해 넘긴다. 음모론·기억 왜곡·외부 탓 등으로 봉합하되, 그 설명의 과도함 자체가 또 하나의 단서가 되게 한다."},{"title":"가짜 미스터리 미끼","synopsis":"독자의 주의를 진짜 트릭이 아닌 다른 수수께끼(엉뚱한 용의자·표면적 음모)로 유인한다. 진짜 반전을 사각지대에 두기 위한 의도적 미스디렉션."},{"title":"진실의 문턱","synopsis":"주인공이 진실에 거의 닿는 순간을 만들었다가 다시 밀어낸다. 결정적 단서를 손에 쥐고도 오독하게 하여, 독자에게 '거의 알았는데'의 안타까움과 재독 욕구를 심는다."}]},{"title":"3막 — 재배열의 충격","synopsis":"단 하나의 폭로로 모든 앞 장면의 의미가 뒤집히고, 독자가 자신의 독해를 의심하게 되는 클라이맥스.","folder":true,"children":[{"title":"키스톤 폭로","synopsis":"전체 전제를 무너뜨리는 핵심 진실 한 가지를 공개한다(주인공의 진짜 정체·시간의 진상·화자의 거짓). 한 문장/한 이미지로 충격이 응축되도록 절제해서 터뜨릴 것."},{"title":"복선 회수 몽타주","synopsis":"앞서 심은 이중 의미 장면들을 빠르게 재생하며 진짜 뜻을 보여준다. 독자가 '그래서 그때 그랬구나'를 체험하게 하는, 반전 구조의 카타르시스를 책임지는 비트."},{"title":"되감을 수 없는 인식","synopsis":"진실을 안 뒤의 주인공/독자의 변화를 그린다. 비극적 수용, 자기 파괴, 혹은 마지막 한 줄의 추가 반전으로 '이마저 거짓이었나' 하는 여운을 남겨 재독을 유도."}]}]},{"id":"g1-survival-isolation","category":"스릴러·서스펜스","name":"고립 생존 서스펜스 (밀폐된 공간의 위협)","desc":"외부와 차단된 한정 공간(외딴 저택·눈보라 산장·표류·재난 봉쇄)에 갇힌 인물들 사이에서 위협이 자라나는 구조. 탈출 불가능성과 신뢰 붕괴가 압박의 핵심. 그리고 아무도 없었다, 더 씽, 미저리, 콰이어트 플레이스, 폭설 산장 미스터리 계열. 폐쇄 공간이 곧 압력솥이 된다.","beats":[{"title":"1막 — 봉쇄의 성립","synopsis":"인물들이 한 공간에 모이고, 외부와의 연결이 차단되어 탈출이 불가능해지는 단계.","folder":true,"children":[{"title":"모임의 구실","synopsis":"서로 다른 동기를 가진 인물들을 한 장소에 모으는 명분(초대·임무·조난·격리)을 만든다. 각자 숨긴 비밀이나 이해관계를 미리 흘려 폭발의 연료를 깔아 둘 것."},{"title":"퇴로 차단","synopsis":"통신 두절·도로 봉쇄·배 침몰·문 잠김 등으로 외부 도움과 탈출을 동시에 끊는다. 차단의 원인이 자연이든 인위든, '여기서 나갈 수 없다'를 사건으로 확정."},{"title":"첫 희생 혹은 위협 표면화","synopsis":"첫 사망·실종·공격으로 '우리 중에/이 안에 위협이 있다'는 사실을 선언한다. 사고로 위장하거나 외부 존재인지 내부 존재인지 모호하게 남겨 의심의 방향을 열어 둔다."}]},{"title":"2막 — 내부 붕괴","synopsis":"공간이 좁혀지고 인원이 줄어드는 동안 생존자들 사이의 신뢰가 무너지고 의심이 전염되는 단계.","folder":true,"children":[{"title":"용의자 색출","synopsis":"남은 인물들이 서로를 의심하며 위협의 정체를 추론한다. 알리바이·동기·과거를 들춰내되, 정보가 불완전해 누구도 결백을 증명 못 하게 하여 편집증을 키운다."},{"title":"자원의 고갈","synopsis":"식량·연료·시간·체온 등 한정 자원이 줄어들며 물리적 압박을 추가한다. 위협뿐 아니라 환경 자체가 적이 되어 인물들을 비이성적 선택으로 몰아간다."},{"title":"동맹과 배신","synopsis":"생존을 위해 임시 동맹이 맺어졌다가 깨진다. 누군가 비밀을 들키거나 먼저 배신해 인원이 또 줄고, 진짜 위협이 누구/무엇인지에 대한 가설이 한 번 뒤집힌다."},{"title":"공간의 협소화","synopsis":"안전지대가 점점 좁아진다(저택→한 방, 산장→지하실). 물리적 압축으로 긴장을 시각화하고, 마지막 남은 사람들끼리의 대치가 불가피해지도록 무대를 좁힌다."}]},{"title":"3막 — 정체의 폭로와 탈출","synopsis":"위협의 진짜 정체가 드러나고, 최후 생존자가 탈출 혹은 종결을 시도하는 클라이맥스.","folder":true,"children":[{"title":"위협의 진면목","synopsis":"범인/괴물/진실의 정체를 공개한다. 내부자의 정체, 위협의 비인간적 본질, 혹은 모든 게 한 사람의 설계였음 등. 앞서 깔아 둔 비밀들과 인과로 연결되게 폭로할 것."},{"title":"최후의 발버둥","synopsis":"마지막 생존자(들)가 위협을 제거하거나 봉쇄를 뚫으려 사투한다. 좁은 공간을 역이용하는 기지, 자원의 마지막 한 방울을 건 도박으로 절체절명을 연출."},{"title":"열린 출구의 대가","synopsis":"탈출에 성공해도 온전치 않은 결말을 그린다. 혼자 살아남은 죄책감, 위협이 완전히 끝나지 않았다는 암시, 혹은 구조된 세상이 더 위험하다는 반전으로 여운을 남긴다."}]}]},{"id":"g2-first-contact-protocol","category":"SF·과학소설","name":"퍼스트 콘택트 / 외계 지성 조우","desc":"미지의 외계 지성·신호·구조물과의 첫 접촉을 다루는 구조. 핵심은 '소통 불가능성'과 '인간 인식의 한계'다. 《콘택트》《당신 인생의 이야기(컨택트)》《라마와의 랑데부》처럼, 액션이 아니라 해석·번역·오해의 드라마로 긴장을 만든다. 외계는 적이 아니라 거울이며, 결말은 인류가 자기 자신을 다시 정의하는 데서 온다.","beats":[{"title":"1막 — 신호의 출현","synopsis":"일상의 과학적 질서가 설명 불가능한 신호로 균열을 일으키는 단계.","folder":true,"children":[{"title":"정상 상태의 과학","synopsis":"주인공(언어학자·천체물리학자·SETI 연구자 등)의 전문성과 일상 루틴, 그리고 '아무 일도 일어나지 않을 것'이라는 학계의 회의를 먼저 세워라. 나중에 무너질 인식의 기준선을 깔아두는 것이 목적이다."},{"title":"이상 신호 포착","synopsis":"반복·소수·기하학 등 '자연적이지 않음'을 증명하는 패턴을 통해 신호가 발견되는 순간을 쓴다. 독자가 주인공보다 약간 먼저 '이건 진짜다'를 직감하게 하는 디테일에 집중."},{"title":"검증과 부정","synopsis":"오류·장난·냉전 무기일 가능성을 하나씩 배제하는 과정. 과학적 절차의 신뢰성을 보여주는 동시에, 진실을 향한 저항(군·정부·종교의 개입)을 예고한다."}]},{"title":"2막 — 번역의 미로","synopsis":"접촉이 확정된 뒤, 소통을 시도하며 인간 사고의 한계에 부딪히는 단계.","folder":true,"children":[{"title":"공동 통제권 싸움","synopsis":"군사·정치·자본·과학이 신호의 해석권을 두고 충돌한다. 외계 자체보다 인간 집단의 두려움과 욕망이 더 큰 위협임을 드러내는 비트."},{"title":"비인간적 문법과의 충돌","synopsis":"외계의 시간관·인과관·감각 체계가 인간과 근본적으로 다름을 보여라. 《당신 인생의 이야기》식 '언어가 사고를 바꾼다'처럼, 번역 자체가 주인공을 변형시키는 장면이 핵심."},{"title":"치명적 오해","synopsis":"선의의 신호가 위협으로, 또는 그 반대로 오역되어 사태가 임계점으로 치닫는다. 소통 실패가 곧 파국이 될 수 있다는 서스펜스를 최고조로."}]},{"title":"3막 — 인식의 전환","synopsis":"외계가 아니라 인간 자신에 대한 이해가 바뀌며 사건이 마무리되는 단계.","folder":true,"children":[{"title":"도약의 대가","synopsis":"주인공이 인간 한계를 넘는 이해(혹은 희생)를 감수하는 절정. 외계의 진의가 드러나지만 그것이 '정답'이 아니라 새로운 질문임을 보여준다."},{"title":"변형된 인류","synopsis":"접촉 이후 세계가 어떻게 달라졌는지(또는 끝내 달라지지 못했는지)를 그린다. 외계는 떠나거나 침묵하고, 남은 것은 변한 인간의 시선이다."},{"title":"거울로서의 결말","synopsis":"최종적으로 외계 존재가 인류에 대한 은유였음을 독자가 깨닫게 하는 여운. 답보다 '우리는 누구인가'라는 잔상을 남기며 닫아라."}]}]},{"id":"g2-dystopian-awakening","category":"SF·과학소설","name":"디스토피아 / 체제 각성과 저항","desc":"전체주의·감시·계급화된 미래 사회에서 한 개인이 체제의 거짓을 자각하고 저항하다 부서지거나 균열을 내는 구조. 《1984》《멋진 신세계》《핸드메이즈 테일》《화씨 451》의 계보. 세계관 자체가 적대자이며, 승리가 아니라 '진실을 보았다는 사실' 자체가 서사의 핵이다. 비극적 결말도 장르적 정통이다.","beats":[{"title":"1막 — 완벽한 거짓","synopsis":"디스토피아가 '정상'으로 작동하는 세계를 안에서부터 보여주는 단계.","folder":true,"children":[{"title":"순응하는 주인공","synopsis":"체제의 톱니로 기능하는 주인공의 일상을 그려라. 통제·배급·감시·세뇌가 너무 자연스러워 독자조차 처음엔 디스토피아임을 잊게 만드는 것이 목표."},{"title":"작은 균열","synopsis":"금지된 책·금지된 감정·기록의 모순 등 체제의 거짓을 암시하는 첫 단서. 주인공의 무의식적 불편함이 의식으로 올라오기 직전의 긴장을 쓴다."},{"title":"유혹하는 타자","synopsis":"각성을 촉발하는 인물(연인·반체제자·이방인)의 등장. 주인공이 '다른 삶이 가능하다'는 위험한 가능성에 처음 노출되는 비트."}]},{"title":"2막 — 금지된 진실","synopsis":"주인공이 체제 바깥을 엿보고 이중생활에 빠져드는 단계.","folder":true,"children":[{"title":"지하의 발견","synopsis":"체제가 숨긴 역사·자원·저항 조직을 발견한다. 세계관의 진짜 작동 원리(누가 이득을 보는가)를 독자에게 폭로하는 핵심 정보 장면."},{"title":"이중생활의 황홀","synopsis":"금지된 사랑·예술·자유를 맛보는 짧은 해방기. 잃을 것이 생겼기에 더 위험해진 주인공의 처지를 통해 다가올 추락의 낙폭을 키운다."},{"title":"감시망의 조임","synopsis":"체제가 주인공을 의심하기 시작하고 동료가 사라진다. 신뢰가 무너지고 누가 밀고자인지 알 수 없는 편집증적 긴장을 고조시켜라."}]},{"title":"3막 — 체제의 응답","synopsis":"저항이 체제와 정면충돌하고 그 대가를 치르는 단계.","folder":true,"children":[{"title":"체포와 심문","synopsis":"주인공이 붙잡혀 체제의 진짜 얼굴(고문·재교육·세뇌)과 마주한다. 《1984》의 101호실처럼, 개인의 내면을 부수는 것이 체제의 궁극 목표임을 보여주는 절정."},{"title":"굴복 혹은 불씨","synopsis":"주인공이 부서지거나(비극), 혹은 진실의 작은 불씨를 다음 세대로 넘긴다(희미한 희망). 어느 쪽이든 체제는 건재하되 균열은 남는다."},{"title":"차가운 여운","synopsis":"에필로그적 시점에서 체제의 영속성 또는 붕괴의 전조를 암시하라. 독자에게 '이것은 미래가 아니라 경고다'라는 정치적 잔상을 남기며 닫는다."}]}]},{"id":"g2-hard-sf-problem","category":"SF·과학소설","name":"하드 SF / 과학적 난제 해결","desc":"물리·궤도역학·생화학 등 실제 과학 법칙이 곧 적대자가 되는 구조. 《마션》《그래비티》《중력의 임무》《스타크래프트적 생존물》의 계보. 빌런이 없다. 우주·물리·시간이 인정사정없는 장애물이고, 주인공은 지성과 공학으로 한 단계씩 문제를 푼다. 독자의 쾌감은 '논리적으로 말이 되는 해결'에서 온다.","beats":[{"title":"1막 — 시스템과 재난","synopsis":"정교한 기술 환경을 세우고, 그것이 한순간에 치명적 위기로 변하는 단계.","folder":true,"children":[{"title":"유능한 전문가","synopsis":"주인공의 직업적 역량과 시스템의 작동 원리를 자연스럽게 학습시켜라. 나중에 이 지식들이 생존의 도구가 되므로, '체호프의 총'으로서 기술 디테일을 심는다."},{"title":"예측 못 한 변수","synopsis":"단순한 사고·고장·자연현상이 연쇄 실패를 일으키는 순간. 악의가 아니라 확률과 물리 법칙이 주인공을 고립·위기에 빠뜨린다는 점이 핵심."},{"title":"냉정한 현실 점검","synopsis":"주인공이 자원·시간·생존 가능성을 숫자로 계산한다. 절망의 크기를 정량적으로 제시해 독자가 '이걸 어떻게 풀지'에 몰입하게 만든다."}]},{"title":"2막 — 문제의 분해","synopsis":"거대한 위기를 풀 수 있는 작은 공학적 문제들로 쪼개 하나씩 격파하는 단계.","folder":true,"children":[{"title":"임시방편의 천재성","synopsis":"가용 자원만으로 즉석 해법을 만드는 장면. 과정·실패·재시도를 구체적으로 보여 독자가 함께 문제를 푸는 듯한 몰입감을 준다."},{"title":"교차 시점의 지원","synopsis":"지상 관제·동료·외부 조직의 병렬 분투를 교차로 보여라(《마션》식). 고립된 주인공과 바깥 세계의 시간차·정보차가 서스펜스를 만든다."},{"title":"역설적 후퇴","synopsis":"한 문제를 풀자 더 큰 문제가 드러나는 반전. 해결이 새로운 변수를 낳는 물리적 인과의 냉혹함으로 중반 침체를 막는다."}]},{"title":"3막 — 한계 돌파","synopsis":"모든 자원을 건 마지막 도박으로 물리 법칙의 틈을 비집고 생존하는 단계.","folder":true,"children":[{"title":"마진 제로의 도박","synopsis":"오차 허용범위가 사라진 단 한 번의 시도. 계산·궤도·연료 등 정량적 긴장을 초 단위로 압축해 절정의 카타르시스를 만든다."},{"title":"과학으로 얻은 구원","synopsis":"1막에서 심어둔 디테일이 결정적으로 맞물려 생존이 성립한다. 행운이 아니라 지성과 협력의 결과임을 명확히 해 장르적 약속을 지킨다."},{"title":"겸허한 귀환","synopsis":"생존 이후, 우주·자연 앞에서 인간의 작음과 끈질김을 동시에 성찰하는 마무리. 승리감보다 경외감을 남긴다."}]}]},{"id":"g2-time-loop-paradox","category":"SF·과학소설","name":"타임 패러독스 / 시간 루프와 인과의 덫","desc":"시간여행·루프·인과율의 모순을 구조 자체로 삼는 SF. 《엣지 오브 투모로우》《타임 패러독스(프리데스티네이션)》《테넷》《당신 인생의 이야기》의 계보. 플롯이 곧 퍼즐이다. 반복·되감기·자기지시적 인과를 통해 독자가 조각을 맞추게 하며, 마지막에 '시간 구조 자체'가 드러나는 충격이 핵심 쾌감이다.","beats":[{"title":"1막 — 규칙의 발견","synopsis":"시간의 변칙이 시작되고 주인공이 그 규칙을 더듬어 알아가는 단계.","folder":true,"children":[{"title":"첫 번째 반복(혹은 도약)","synopsis":"주인공이 시간이 정상이 아님을 깨닫는 순간. 혼란·불신·재확인의 과정을 통해 독자에게 이 세계의 '시간 규칙'을 함께 체득시킨다."},{"title":"규칙 실험","synopsis":"주인공이 의도적으로 시간을 조작·테스트하며 가능/불가능의 경계를 정한다. 여기서 확립한 규칙이 후반 트릭의 공정성(독자와의 약속)을 보장한다."},{"title":"목표의 설정","synopsis":"반복을 끝내거나 누군가를 구하거나 미래를 바꾸려는 명확한 동기 부여. 시간 퍼즐에 감정적 무게를 싣는 비트."}]},{"title":"2막 — 인과의 미로","synopsis":"시간을 다룰수록 인과가 꼬이고 모순이 쌓여가는 단계.","folder":true,"children":[{"title":"숙달과 오만","synopsis":"주인공이 시간 규칙을 능숙히 다루며 작은 승리를 거두는 몽타주. 통제감이 정점에 이르렀을 때가 가장 위험하다는 복선을 깐다."},{"title":"자기지시적 함정","synopsis":"과거의 자신·미래의 자신이 현재에 개입하며 인과가 폐곡선을 이루기 시작한다. 《프리데스티네이션》식으로 '원인이 곧 결과'인 모순을 독자에게 슬쩍 노출."},{"title":"되돌릴 수 없는 손실","synopsis":"시간 조작의 대가로 결코 복구 못 할 것을 잃는다. 무한해 보이던 반복에 진짜 위험과 유한성이 생기는 전환점."}]},{"title":"3막 — 폐곡선의 폭로","synopsis":"흩어진 시간 조각이 하나로 맞물리며 진짜 구조가 드러나는 단계.","folder":true,"children":[{"title":"퍼즐의 결합","synopsis":"앞서 무심히 지나친 장면들이 사실 인과의 핵심 고리였음이 한꺼번에 드러난다. 재방문·재해석으로 '아하' 순간을 설계하라."},{"title":"선택 혹은 수용","synopsis":"주인공이 루프를 끊는 자유의지를 행사하거나(능동), 정해진 운명을 끌어안는다(《당신 인생의 이야기》식 수용). 시간관에 대한 작품의 철학이 결정되는 절정."},{"title":"닫힌 고리의 여운","synopsis":"마지막 장면이 첫 장면과 맞물리거나, 새 루프의 시작을 암시한다. 독자가 책을 덮고 다시 1페이지를 떠올리게 만드는 회귀적 마무리."}]}]},{"id":"g2-post-apocalypse-survival","category":"SF·과학소설","name":"포스트 아포칼립스 / 문명 붕괴 후 생존","desc":"재앙으로 무너진 세계에서 인간성과 공동체의 의미를 묻는 구조. 《더 로드》《스테이션 일레븐》《행복한 종말(The Last of Us)》《나는 전설이다》의 계보. 핵심 갈등은 '생존이냐 인간성이냐'이며, 진짜 괴물은 종종 변종이 아니라 살아남은 인간이다. 폐허는 무대인 동시에 잃어버린 것의 거대한 은유다.","beats":[{"title":"1막 — 잿더미의 세계","synopsis":"붕괴 이후의 일상화된 생존을 보여주며 인물의 규칙과 상실을 세우는 단계.","folder":true,"children":[{"title":"생존 루틴","synopsis":"물·식량·은신처를 둘러싼 일상화된 사투를 그려라. 붕괴가 이미 과거임을 전제로, 이 세계의 잔혹한 규칙을 담담하게 학습시킨다."},{"title":"잃어버린 세계의 흔적","synopsis":"낡은 사진·노래·책 등 옛 문명의 파편을 통해 무엇을 잃었는지 환기한다. 향수가 곧 인간성의 척도임을 암시하는 비트."},{"title":"여정의 촉발","synopsis":"안전지대·치료제·소문 속 공동체 등 목표가 생겨 주인공이 길을 나선다. 머무름이 곧 죽음인 세계에서 이동 자체가 플롯의 엔진."}]},{"title":"2막 — 길 위의 인간들","synopsis":"여정에서 다양한 생존 공동체를 만나며 인간성의 스펙트럼을 시험받는 단계.","folder":true,"children":[{"title":"거짓 안식처","synopsis":"이상적으로 보이는 공동체가 사실 약탈·신정·식인 등 어두운 비밀을 품고 있음을 폭로한다. '문명의 흉내'가 더 무서울 수 있음을 보여라."},{"title":"유대의 형성","synopsis":"동행과 신뢰가 싹트며 '왜 살아남는가'에 대한 답이 사람으로 옮겨간다. 잃을 것이 생기는 것이 곧 강함이자 약점이 되는 정서적 핵심."},{"title":"선을 넘는 선택","synopsis":"생존을 위해 인간성을 포기해야 하는 딜레마. 주인공이 한 번 선을 넘으며 스스로 무엇이 되어가는지 마주하는 어두운 전환점."}]},{"title":"3막 — 인간성의 값","synopsis":"목적지에서 진실과 마주하고 무엇을 위해 살지 최종 선택하는 단계.","folder":true,"children":[{"title":"목적지의 진실","synopsis":"찾던 곳이 환상이었거나, 구원에 끔찍한 대가가 따름을 알게 된다(《라스트 오브 어스》식 딜레마). 외부의 위협이 내면의 윤리 문제로 수렴한다."},{"title":"가장 인간적인 선택","synopsis":"주인공이 생존의 논리를 거스르고 사랑·존엄·다음 세대를 택하는(혹은 끝내 못 택하는) 절정. 이 선택이 작품의 인간관을 정의한다."},{"title":"재의 새싹","synopsis":"폐허 속 작은 회복의 징표(아이·씨앗·음악·이야기)로 끝맺는다. 문명은 무너졌으나 인간을 인간이게 하는 것은 남았다는 희미한 빛을 남긴다."}]}]},{"id":"g2-cyberpunk-noir","category":"SF·과학소설","name":"사이버펑크 / 하이테크 로우라이프 누아르","desc":"거대 기업이 국가를 대체하고 신체·의식이 상품화된 근미래에서, 밑바닥 주인공이 의뢰·해킹·음모를 따라가는 누아르 구조. 《뉴로맨서》《블레이드 러너》《알티드 카본》《공각기동대》의 계보. '하이테크 로우라이프'가 강령이며, 의식·기억·인간성의 경계를 묻는 정체성 미스터리가 액션 아래 흐른다.","beats":[{"title":"1막 — 네온과 진창","synopsis":"기업 지배의 디스토피아 도시와 밑바닥 주인공, 그리고 미끼 같은 의뢰를 세우는 단계.","folder":true,"children":[{"title":"거리의 주인공","synopsis":"해커·용병·사립탐정 등 시스템 가장자리의 주인공과 그의 결핍(빚·중독·잃어버린 과거)을 그린다. 도시의 감각적 디테일로 '하이테크 로우라이프'를 체화시켜라."},{"title":"거절 못 할 의뢰","synopsis":"수상하지만 거절 불가능한 일거리가 들어온다. 보수의 크기만큼 위험이 큼을 암시하고, 의뢰주의 진의를 의심하게 만드는 누아르식 도입."},{"title":"기술의 규칙","synopsis":"사이버웨어·의식 업로드·뇌 해킹 등 세계의 기술 규칙을 보여라. 이 규칙이 후반 정체성 반전의 토대가 되므로 자연스럽게 심는다."}]},{"title":"2막 — 음모의 배선","synopsis":"의뢰를 파고들수록 거대 기업·AI의 음모가 드러나고 주인공이 소모품임을 깨닫는 단계.","folder":true,"children":[{"title":"침투와 대가","synopsis":"전뇌 공간 해킹·기업 잠입 등 핵심 액션 시퀀스. 화려한 기술 묘사 속에서 주인공이 무언가를 훔치되 더 큰 함정에 걸려드는 구성."},{"title":"배신의 연쇄","synopsis":"조력자·의뢰주·연인이 차례로 거짓임이 드러난다. 누구도 믿을 수 없는 누아르 특유의 편집증과, 주인공이 거대 게임의 졸이었다는 자각을 키운다."},{"title":"경계의 붕괴","synopsis":"기억 조작·복제·의식 이전 등으로 '나는 진짜 나인가'라는 의심이 폭발한다. 외부 음모가 주인공의 정체성 문제로 전환되는 핵심 비트."}]},{"title":"3막 — 유령과 껍데기","synopsis":"음모의 정점에서 정체성의 진실과 마주하고 시스템에 응답하는 단계.","folder":true,"children":[{"title":"진실의 코어","synopsis":"기업·AI가 감춘 핵심 비밀(주인공의 기원, 의식의 비밀)이 폭로된다. 인간과 기계, 진짜와 복제의 경계가 무의미함을 드러내는 절정의 반전."},{"title":"시스템과의 정산","synopsis":"주인공이 거대 권력에 맞서 데이터 폭로·자기희생·합일 등으로 한 방을 먹인다. 세계를 바꾸진 못해도 자기 존재를 스스로 정의하는 선택."},{"title":"젖은 네온의 새벽","synopsis":"도시는 그대로 굴러가고 주인공만 변한 채 빗속으로 사라진다. 승리도 패배도 아닌, 정체성에 대한 차갑고 모호한 누아르식 여운을 남긴다."}]}]},{"id":"g3-heros-journey-epic","category":"판타지","name":"영웅의 여정 (에픽 하이판타지)","desc":"톨킨·로버트 조던·브랜든 샌더슨 계열의 정통 영웅 서사. 평범한 출신의 주인공이 부름을 받아 멘토와 동료를 얻고, 세계를 위협하는 어둠의 군주에 맞서 성장하며 운명을 완수한다. 캠벨의 단일신화 골격에 광활한 세계관과 종족·왕국 단위의 갈등을 얹는다.","beats":[{"title":"1막 — 평범한 세계와 부름","synopsis":"주인공의 일상과 결핍을 보여주고, 세계를 뒤흔들 위협이 그의 좁은 삶에 침입하는 단계.","folder":true,"children":[{"title":"일상 세계의 결핍","synopsis":"변방 마을·농가 등 평범한 무대에서 주인공의 갑갑한 처지와 막연한 동경을 묘사한다. 동시에 멀리서 다가오는 어둠의 징조(이상기후, 사라진 마을, 떠도는 소문)를 배경에 깔아 독자가 '여기서 끝날 삶이 아니다'를 느끼게 한다."},{"title":"모험의 부름과 거부","synopsis":"유산, 예언, 정체불명의 추격자, 죽어가는 노인의 전언 등 부름이 도착한다. 주인공은 두려움·의무감으로 처음엔 거부하지만, 일상이 파괴되는 사건(마을 습격, 가족의 죽음)으로 더는 돌아갈 곳이 없어진다."},{"title":"멘토와 비밀의 출생","synopsis":"마법사·노전사·현자 등 멘토가 등장해 주인공의 진짜 혈통이나 잠재력, 세계의 진실 일부를 흘린다. 멘토가 줄 도구(검·반지·주문)와 함께 '아직 다 말하지 않은 비밀'을 남겨 후반 반전의 씨앗을 심는다."}]},{"title":"2막 — 문턱 너머와 시련의 길","synopsis":"익숙한 세계를 떠나 낯선 영토로 진입, 동료를 모으고 적의 규모를 실감하며 능력을 키운다.","folder":true,"children":[{"title":"첫 문턱과 동료 규합","synopsis":"국경·숲·관문 등을 넘으며 미지의 세계로 들어간다. 성격과 능력이 대조되는 동료들(전사, 도둑, 이종족, 라이벌)을 차례로 합류시키되 각자의 비밀스러운 동기를 부여해 후반 갈등의 연료로 쓴다."},{"title":"시련과 능력 각성","synopsis":"연속된 전투·추격·수수께끼로 일행을 단련한다. 주인공이 자신의 마법/힘을 처음으로 통제 불능 상태에서 발현하고, 그 대가(소모·폭주·저주)를 보여줘 능력에 무게를 둔다."},{"title":"중간 거점과 세계관 확장","synopsis":"거대 도시·고대 유적·요정 왕국 등 중심 거점에서 호흡을 고른다. 정치 지형, 종족 간 역사, 적 군주의 기원을 정보 누설(고문서, 살아있는 전설)로 풀어 스케일을 끌어올린다."},{"title":"배신과 첫 패배","synopsis":"신뢰하던 인물의 배신 혹은 적의 결정적 한 수로 일행이 흩어지거나 멘토를 잃는다. 주인공이 의지하던 외부 버팀목이 사라지며 '스스로 일어서야 한다'는 압박을 만든다."}]},{"title":"3막 — 심연과 진실","synopsis":"가장 어두운 골짜기에서 주인공이 자신과 세계의 진실을 직면하고 내적으로 거듭난다.","folder":true,"children":[{"title":"가장 어두운 동굴","synopsis":"포로·고립·절망의 밑바닥 장면. 주인공이 모든 것을 잃은 듯한 상태에서 멘토의 마지막 가르침이나 예언의 숨은 의미를 떠올리게 한다."},{"title":"정체성의 진실","synopsis":"출생의 비밀, 적 군주와의 관계, 예언의 진짜 대상 등 1막에서 심은 비밀을 회수해 반전을 터뜨린다. 주인공의 자기 인식이 무너졌다가 새 의미로 재조립되게 한다."},{"title":"내면의 결단","synopsis":"힘의 유혹(어둠에 합류·복수·도피)을 거절하고, 희생을 감수하는 결단으로 주인공을 도덕적으로 완성한다. 잃었던 동료와 재결합하거나 새 연대를 맺어 최종 결전 진영을 정비한다."}]},{"title":"4막 — 최후의 결전과 귀환","synopsis":"축적된 모든 것을 쏟아붓는 클라이맥스와, 변화한 영웅의 귀환으로 마무리한다.","folder":true,"children":[{"title":"결전의 진군","synopsis":"대군의 충돌·공성전 등 거시 전장과, 주인공-군주의 미시 대결을 교차편집하듯 배치한다. 앞서 뿌린 복선(유물의 진짜 용도, 동료의 숨은 능력)을 회수해 승리의 개연성을 만든다."},{"title":"최종 대결과 대가","synopsis":"어둠의 군주와의 정면승부. 주인공은 힘만이 아니라 1~3막에서 얻은 깨달음·관계로 승리하되, 반드시 무언가(능력, 동료, 평범함)를 잃는 대가를 치르게 해 카타르시스에 무게를 싣는다."},{"title":"변화한 귀환","synopsis":"전쟁 후의 세계와 주인공의 자리를 정리한다. 떠나온 일상으로 돌아오되 더 이상 같은 사람이 아님을, 새 질서·남은 상처·다음 세대의 암시로 보여주며 여운을 남긴다."}]}]},{"id":"g3-academy-progression","category":"판타지","name":"마법학원·성장 시스템물","desc":"해리포터·바람의 이름·현대 웹소설 '회귀 천재'류를 아우르는, 폐쇄된 교육기관과 단계적 실력 상승을 축으로 한 구조. 입학→서열·시험→숨은 음모→학년/등급 졸업의 사이클이 반복되며, 독자의 '성장 쾌감'과 '소속감'을 자극한다.","beats":[{"title":"1막 — 입학과 신세계","synopsis":"비범한 자질을 지닌 주인공이 마법 교육기관에 들어가 규칙과 위계를 학습한다.","folder":true,"children":[{"title":"선발과 입학","synopsis":"재능 발견·시험 합격·추천 등으로 주인공이 학원에 진입한다. 바깥 세계와의 단절(평민 출신, 변방 출신)을 강조해 '이방인의 시선'으로 마법 세계의 경이를 신선하게 소개한다."},{"title":"규칙·서열·기숙 체계 학습","synopsis":"학년·등급·기숙사·교수진 등 시스템을 명확한 룰로 제시한다. 라이벌(명문가 자제), 첫 친구, 호의적/적대적 교수를 배치해 인간관계 좌표를 깐다."},{"title":"재능의 첫 증명","synopsis":"첫 수업·실기에서 주인공만의 강점(특이 속성, 비상한 기억력, 회귀 지식)을 작게 터뜨려 기대치를 만든다. 동시에 약점·결핍을 명확히 해 성장 여지를 남긴다."}]},{"title":"2막 — 수련과 경쟁","synopsis":"시험·대회·과제를 통해 실력을 단계적으로 끌어올리고 또래 갈등을 심화한다.","folder":true,"children":[{"title":"단계별 과제와 성장 곡선","synopsis":"주문 습득·실기 평가·등급 승급 등 측정 가능한 목표를 연속 배치한다. 막힘→돌파의 작은 사이클을 반복해 독자에게 누적 성장 쾌감을 준다."},{"title":"라이벌·파벌 갈등","synopsis":"대회·결투·점수 경쟁으로 라이벌과 정면 충돌시킨다. 단순 악역이 아니라 가치관·출신이 다른 경쟁자로 그려 후반 협력/반전의 폭을 확보한다."},{"title":"금지된 영역의 발견","synopsis":"출입 금지 구역·봉인된 서고·학원의 숨은 역사에 우연히 접근한다. 호기심이 메인 음모의 단서로 이어지도록, 사소해 보이는 이상 징후를 흘린다."},{"title":"멘토와 비전 전수","synopsis":"특정 교수·선배가 주인공의 잠재력을 알아보고 비공식 가르침을 준다. 멘토의 과거·정치적 입장이 후반 음모와 연결되는 떡밥을 심는다."}]},{"title":"3막 — 숨은 음모의 부상","synopsis":"학원 일상 아래 잠복하던 위협이 표면화되며 주인공이 사건의 중심에 선다.","folder":true,"children":[{"title":"사건의 가시화","synopsis":"실종·저주·금기 마법 발현 등 학원을 흔드는 사건이 터진다. 교직원의 은폐·축소 시도로 주인공이 직접 진실을 파게 만든다."},{"title":"조사와 오인","synopsis":"주인공 일행이 단서를 모으며 엉뚱한 인물을 의심하게 한다. 미스터리적 오답을 한 번 거쳐 진범의 의외성을 키운다."},{"title":"배후의 실체","synopsis":"학원 권력층·외부 세력·과거의 비극과 얽힌 진짜 배후를 드러낸다. 주인공의 출생/재능이 음모의 핵심 변수였음을 연결해 개인 서사와 사건을 묶는다."}]},{"title":"4막 — 결전과 진급","synopsis":"축적한 실력으로 위협을 막아내고, 한 단계 성장한 채 다음 사이클을 예고한다.","folder":true,"children":[{"title":"실력의 총동원","synopsis":"그동안 배운 주문·전술·동료 연계를 총집결해 위기를 정면 돌파한다. 성장 곡선의 페이오프로, 1막의 무력했던 자신과 명확히 대비시킨다."},{"title":"대가와 각성","synopsis":"승리하되 친구의 부상·금기의 사용·진실의 무게 등 대가를 치른다. 주인공이 한 단계 더 위험한 진실(더 큰 적, 자신의 위험한 힘)에 눈뜨게 한다."},{"title":"진급과 다음 사이클의 씨앗","synopsis":"학년/등급 졸업, 방학, 새 학기 예고로 매듭짓는다. 이번에 풀리지 않은 떡밥(배후의 잔당, 봉인의 진실)을 남겨 다음 권의 동력을 확보한다."}]}]},{"id":"g3-grimdark-politics","category":"판타지","name":"그림다크 정치·왕좌 쟁탈","desc":"조지 R.R. 마틴·조 아버크롬비 계열의 다시점 권력 게임. 명확한 선악 대신 회색 인물들이 왕좌·영지·생존을 두고 음모와 배신을 벌인다. 마법은 희소하고 위험하며, 죽음이 누구에게나 닥친다. 도덕적 안전망 없는 냉혹함이 핵심 정서.","beats":[{"title":"1부 — 균형과 균열","synopsis":"표면적 안정 아래 여러 세력의 야심과 원한을 다시점으로 깔아둔다.","folder":true,"children":[{"title":"표면의 질서","synopsis":"왕가·가문·교단 등 세력 지형과 위태로운 평화를 보여준다. 각 시점 인물의 처지와 욕망을 별도 장으로 소개해 독자가 여러 진영에 동시에 이입하게 만든다."},{"title":"촉발 사건(죽음/모욕)","synopsis":"왕의 죽음·계승 분쟁·공개적 모욕 등 균형을 깨는 사건을 터뜨린다. 이 사건이 각 세력에게 서로 다른 '기회'이자 '위협'으로 읽히게 설계한다."},{"title":"숨은 패의 노출","synopsis":"음모가·첩자·사생아 등 잠복한 변수를 일부만 드러낸다. 독자만 아는 정보와 인물이 모르는 정보의 격차로 드라마틱 아이러니를 깐다."}]},{"title":"2부 — 음모와 합종연횡","synopsis":"세력들이 동맹과 배신을 거듭하며 판이 복잡해지고 신뢰가 무기가 된다.","folder":true,"children":[{"title":"동맹과 정략","synopsis":"혼인·밀약·인질 교환 등 정치적 거래를 배치한다. 모든 동맹에 균열의 씨앗(엇갈린 이해, 과거의 원한)을 심어 언제든 깨질 수 있게 한다."},{"title":"첩보와 기만","synopsis":"스파이·이중첩자·위조 서신으로 정보전을 전개한다. 누가 누구의 편인지 독자도 헷갈리게 해, 진실 자체가 권력 자원임을 보여준다."},{"title":"충격적 죽음","synopsis":"주요 시점 인물 한 명을 예고 없이 제거한다. '아무도 안전하지 않다'는 장르 규칙을 각인시켜 이후 모든 위기의 긴장을 끌어올린다."},{"title":"권력 공백의 쟁탈","synopsis":"죽음/몰락으로 생긴 공백을 두고 2차 경쟁을 벌인다. 약자였던 인물에게 부상의 기회를 주거나, 야심가의 본색을 드러내 판을 재편한다."}]},{"title":"3부 — 파국의 가속","synopsis":"음모들이 충돌해 전면적 위기로 비화하고 회색 인물들의 본성이 시험대에 오른다.","folder":true,"children":[{"title":"전쟁/대학살의 발발","synopsis":"전투·배신의 연회·대숙청 등 폭력의 정점을 배치한다. 명예로운 인물이 비참하게, 비열한 인물이 살아남는 식으로 장르의 냉혹함을 관철한다."},{"title":"도덕의 붕괴와 선택","synopsis":"생존을 위해 신념을 꺾어야 하는 막다른 선택을 각 인물에게 강요한다. 선택의 결과로 캐릭터의 회색 스펙트럼을 더 짙게 칠한다."},{"title":"외부 위협의 그림자","synopsis":"내전에 몰두한 사이 더 큰 위협(이종족·초자연·역병)이 다가옴을 암시한다. 인간들의 권력 다툼이 얼마나 근시안적인지 대비로 드러낸다."}]},{"title":"4부 — 잿더미 위의 질서","synopsis":"승자와 패자를 가르되 완전한 승리는 없는, 씁쓸한 새 균형을 세운다.","folder":true,"children":[{"title":"최후의 수싸움","synopsis":"남은 세력들의 마지막 한 수가 충돌한다. 무력이 아닌 정보·타이밍·인내가 승부를 가르게 해 정치극의 색을 유지한다."},{"title":"왕좌의 대가","synopsis":"권력을 쥔 자가 치른 대가(잃은 사람, 더럽혀진 손, 의심받는 정통성)를 드러낸다. 승리조차 공허하게 그려 그림다크의 정서를 완성한다."},{"title":"다음 폭풍의 예고","synopsis":"외부 위협의 본격화나 새 야심가의 부상으로 불안한 결말을 남긴다. '질서는 또 깨질 것'이라는 순환을 암시해 후속의 동력을 만든다."}]}]},{"id":"g3-portal-isekai","category":"판타지","name":"이세계 전이·환생(포털 판타지)","desc":"나니아·이세계물·게임판타지를 관통하는 '다른 세계로 넘어간 현대인'의 구조. 전생/전이로 얻은 지식·시스템·치트가 무기가 되며, 적응→정착→귀환(혹은 정착 결심)의 동선을 그린다. 독자는 낯선 세계를 주인공과 함께 학습하는 발견의 쾌감을 즐긴다.","beats":[{"title":"1막 — 전이와 충격","synopsis":"주인공이 원래 세계에서 이세계로 넘어가 생존과 적응의 출발선에 선다.","folder":true,"children":[{"title":"현세의 마지막과 전이","synopsis":"사고사·소환진·게임 접속 등으로 전이 계기를 만든다. 원래 세계에서의 미련·결핍(과로사한 직장인, 외톨이)을 짧게 박아 이세계가 '두 번째 기회'로 읽히게 한다."},{"title":"낯선 세계의 첫 규칙","synopsis":"언어·화폐·마법·몬스터 등 세계의 기본 규칙과 위험을 생존형 사건으로 학습시킨다. 죽을 뻔한 첫 위기로 '여긴 게임이 아니라 현실'임을 각인시킨다."},{"title":"치트/시스템의 발견","synopsis":"상태창·전생의 지식·고유 스킬 등 주인공만의 이점을 드러낸다. 단, 만능이 아닌 제약(쿨타임, 대가, 비밀 유지 필요)을 함께 설계해 긴장을 남긴다."}]},{"title":"2막 — 적응과 기반 구축","synopsis":"이점을 활용해 동료·자원·거점을 확보하고 이 세계에서 자리를 잡는다.","folder":true,"children":[{"title":"조력자와 첫 거점","synopsis":"구해준 사람·길드·상단을 통해 인맥과 안전지대를 마련한다. 현대 지식(위생, 상거래, 전술)을 이세계에 이식해 차별화된 활약을 보여준다."},{"title":"현대 지식의 무기화","synopsis":"비누·화약·농법·전술 등 원래 세계의 상식을 이 세계의 혁신으로 전환한다. 작은 성공이 평판·부·세력으로 누적되는 과정을 보여 성취감을 쌓는다."},{"title":"이세계의 어두운 면","synopsis":"노예제·차별·부패한 권력 등 세계의 그늘을 드러낸다. 주인공이 현대인의 가치관으로 충돌·개입하게 해 갈등 노선을 깐다."},{"title":"세력의 견제","synopsis":"급부상한 주인공을 경계하는 귀족·교단·라이벌이 등장한다. 치트의 비밀이 노출될 위험을 만들어 다음 위기의 압력을 높인다."}]},{"title":"3막 — 정체성과 귀환의 물음","synopsis":"이 세계와 원래 세계 사이에서 주인공이 자신의 자리와 목적을 재정의한다.","folder":true,"children":[{"title":"귀환의 단서","synopsis":"원래 세계로 돌아갈 방법·이유에 대한 단서를 던진다. 전이의 진짜 원인(소환의 배후, 전생의 사연)이 드러나며 사건이 개인화된다."},{"title":"두 세계의 저울질","synopsis":"이곳에서 얻은 관계·책임과 원래 세계의 미련을 충돌시킨다. 주인공의 내적 갈등을 통해 '돌아갈 것인가 남을 것인가'의 테마를 전면화한다."},{"title":"비밀의 위기","synopsis":"치트/정체가 폭로되거나 소중한 동료가 위협받는 위기를 터뜨린다. 더는 이방인으로 관망할 수 없게 만들어 결단을 강제한다."}]},{"title":"4막 — 결단과 정착","synopsis":"최대 위협을 돌파하고 두 세계 사이에서 자기 답을 내려 이야기를 매듭짓는다.","folder":true,"children":[{"title":"총력전과 치트의 정점","synopsis":"축적한 힘·인맥·지식을 총동원해 배후 세력/대위협과 맞선다. 그동안 제약 속에 아껴둔 능력의 진가를 결정적 순간에 터뜨린다."},{"title":"남느냐 돌아가느냐","synopsis":"귀환의 문 앞에서 최종 선택을 한다. 잔류든 귀환이든 그 선택이 1막의 결핍을 치유하는 답이 되도록 감정선을 정리한다."},{"title":"새 세계의 일상","synopsis":"선택 이후의 안정된 자리와 남은 과제를 보여준다. 영지 경영·새 모험·재회 등으로 후일담을 열어 정착형 결말의 만족감을 준다."}]}]},{"id":"g3-low-fantasy-quest","category":"판타지","name":"변경 용병·로우판타지 퀘스트","desc":"제멜라이트·검과 마법(소드 앤 소서리)·위처 계열의, 거대 운명보다 생계와 한탕을 좇는 어두운 모험담. 마법은 음습하고 도덕은 흐릿하며, 주인공은 영웅이 아니라 칼잡이·도굴꾼·괴물 사냥꾼이다. 한 건의 의뢰가 점점 더 깊은 진창으로 이어진다.","beats":[{"title":"1막 — 의뢰와 미끼","synopsis":"생계에 쪼들린 주인공이 수상하지만 거절하기 힘든 일감을 받는다.","folder":true,"children":[{"title":"변경의 일상과 궁핍","synopsis":"술집·뒷골목·황량한 변경에서 주인공의 거칠고 빈한한 처지를 보여준다. 과거의 상처나 빚을 암시해 그가 위험한 일을 받을 수밖에 없는 동기를 깐다."},{"title":"수상한 의뢰","synopsis":"보수가 지나치게 좋거나 정보가 부족한 의뢰가 들어온다. 의뢰인의 거짓말 냄새를 풍겨 독자에게 '이건 함정 같다'는 불안을 미리 심는다."},{"title":"동행과 셈법","synopsis":"임시 동료·고용주의 부하 등 신뢰할 수 없는 동행을 붙인다. 각자의 속셈을 흘려, 한탕 뒤 누가 배신할지에 대한 긴장을 깐다."}]},{"title":"2막 — 진창으로","synopsis":"단순해 보이던 일이 예상 밖의 위험과 도덕적 수렁으로 번진다.","folder":true,"children":[{"title":"예상 밖의 첫 난관","synopsis":"괴물·함정·경쟁자 등 정보에 없던 장애가 닥친다. 주인공의 실전적 기지·잔혹함을 보여주되, 깔끔한 승리 대신 대가(부상, 소모)를 치르게 한다."},{"title":"의뢰의 진짜 목적","synopsis":"의뢰가 단순 사냥/회수가 아니라 어두운 음모(인신매매, 금지된 의식, 정치 청부)의 일부임을 드러낸다. 주인공이 자신도 모르게 악행의 도구가 됐음을 깨닫게 한다."},{"title":"음습한 마법의 대가","synopsis":"저주·사령술·악마 거래 등 로우판타지 특유의 위험한 마법을 등장시킨다. 마법을 경이가 아닌 공포·오염으로 그려 세계의 음습한 톤을 강화한다."},{"title":"내부의 배신","synopsis":"동행이나 고용주가 등을 찌른다. 주인공이 홀로 적진 한복판에 남겨지는 최악의 상황으로 몰아, 순수한 생존 모드로 전환시킨다."}]},{"title":"3막 — 칼끝의 선택","synopsis":"주인공이 잇속과 양심, 복수와 생존 사이에서 진창의 한가운데를 가른다.","folder":true,"children":[{"title":"막다른 골목","synopsis":"퇴로가 막힌 채 가장 불리한 조건에서 적과 대치한다. 영웅적 명분이 아니라 살기 위한 독기와 임기응변으로 활로를 모색하게 한다."},{"title":"회색의 결단","synopsis":"보수를 챙기고 떠날지, 손해를 감수하고 누군가를 구할지 택하게 한다. 어느 쪽도 깨끗하지 않게 설계해 주인공의 흐릿한 도덕을 드러낸다."},{"title":"역공의 한 수","synopsis":"약자의 위치에서 함정·독·정보를 무기로 판을 뒤집는다. 정정당당함보다 영악함이 승부를 가르는, 장르 특유의 통쾌함을 살린다."}]},{"title":"4막 — 청산과 다음 길","synopsis":"피값을 치르고 일을 끝내되, 영광 없이 다시 길 위에 서는 결말로 닫는다.","folder":true,"children":[{"title":"피의 청산","synopsis":"배신자·배후와의 최후 정산을 벌인다. 깔끔한 승리가 아닌, 상처투성이의 신산한 마무리로 그려 비정한 톤을 유지한다."},{"title":"남은 것과 잃은 것","synopsis":"손에 쥔 보수와 잃어버린 것(동료, 신념, 일부 자아)을 저울질한다. 한탕의 끝이 결국 공허할 수 있음을 씁쓸하게 비춘다."},{"title":"다시 길 위에서","synopsis":"정착하지 못하고 다음 변경, 다음 의뢰로 향하는 떠돌이의 숙명을 보여준다. 풀리지 않은 과거의 실마리를 남겨 연작의 여지를 둔다."}]}]},{"id":"g3-mythic-coming-of-age","category":"판타지","name":"신화적 성장·운명의 아이","desc":"어슐러 르 귄·다이애나 윈 존스·일부 영어덜트 판타지 계열의, 거대 전쟁보다 한 인물의 내면과 균형을 중시하는 서정적 성장담. 마법은 대가와 책임을 동반하며, 진정한 적은 외부의 군주가 아니라 주인공 자신의 오만·그림자·미성숙이다. 분위기와 상징, 통과의례가 중심.","beats":[{"title":"1부 — 재능과 오만","synopsis":"비범한 재능을 지닌 어린 주인공이 자신의 힘에 눈뜨지만 그것을 다룰 그릇은 아직 없다.","folder":true,"children":[{"title":"재능의 발현","synopsis":"위기 상황에서 주인공이 통제되지 않은 강한 힘을 처음 드러낸다. 주변의 경탄과 두려움을 동시에 보여 재능이 축복이자 위험임을 암시한다."},{"title":"스승과 첫 가르침","synopsis":"마법사·현자에게 맡겨져 기초와 절제의 원리(균형, 이름, 대가)를 배운다. 스승의 경고를 통해 '힘에는 책임이 따른다'는 주제를 명시한다."},{"title":"자만의 씨앗","synopsis":"또래와의 경쟁심·인정 욕구로 주인공이 가르침을 어기려는 충동을 드러낸다. 후반 파국의 원인이 될 성격적 결함을 또렷이 심는다."}]},{"title":"2부 — 금기와 그림자","synopsis":"주인공이 경고를 어기고 힘을 남용해 돌이킬 수 없는 결과를 부른다.","folder":true,"children":[{"title":"금기의 위반","synopsis":"과시·복수·조급함으로 주인공이 금지된 마법을 사용한다. 그 순간의 통쾌함 뒤에 즉각적이고 끔찍한 대가가 따르게 한다."},{"title":"풀려난 그림자","synopsis":"주인공의 오만이 불러낸 존재(분신·저주·균열)가 세상에 풀려난다. 그것이 외부 괴물처럼 보이지만 실은 주인공 자신의 일부임을 단서로 깐다."},{"title":"추격과 도피","synopsis":"그림자에게 쫓기며 주인공이 점점 고립되고 쇠약해진다. 도망치는 동안 마주치는 사람·풍경을 통해 세계의 깊이와 주인공의 죄책감을 그린다."}]},{"title":"3부 — 추적의 역전","synopsis":"쫓기던 주인공이 도망을 멈추고 자신이 그림자를 추적하기로 결심한다.","folder":true,"children":[{"title":"도망에서 직면으로","synopsis":"조력자의 말이나 깨달음으로 주인공이 회피가 답이 아님을 인식한다. 두려움의 대상을 향해 스스로 방향을 트는 내적 전환점을 만든다."},{"title":"세계의 끝으로","synopsis":"그림자를 쫓아 미지의 변경·바다 끝·경계 너머로 나아간다. 외적 여정을 내면 탐험의 은유로 삼아 서정적 긴장을 고조시킨다."},{"title":"진실의 직감","synopsis":"그림자의 정체에 대한 결정적 깨달음이 다가온다. 적의 이름이 곧 자신의 이름임을 예감하게 하여 클라이맥스의 의미를 준비한다."}]},{"title":"4부 — 합일과 성숙","synopsis":"주인공이 자신의 그림자를 받아들임으로써 분열을 치유하고 어른이 된다.","folder":true,"children":[{"title":"이름의 직면","synopsis":"마침내 그림자와 마주해 그것을 자신의 이름으로 부른다. 싸워 없애는 것이 아니라 받아들여 하나가 되는 방식으로 대결을 전복한다."},{"title":"균형의 회복","synopsis":"합일을 통해 세계의 균열이 닫히고 풀려났던 위험이 거둬진다. 화려한 승리가 아닌 조용한 회복으로 그려 주제(균형)에 충실하게 한다."},{"title":"어른이 된 자리","synopsis":"온전해진 주인공이 자신의 책임과 다음 길을 받아들인다. 힘의 정점이 아니라 자기 수용의 평온함으로 마무리해 성장담의 여운을 남긴다."}]}]},{"id":"g4-revenge-blood-feud","category":"무협","name":"복수혈사 (멸문지화 복수담)","desc":"가문·사문이 멸문당하고 홀로 살아남은 주인공이 절치부심 끝에 무공을 이뤄 원수를 추적해 응징하는 무협의 가장 고전적인 동력. 김용 '사조영웅전'의 곽정 가계나 '연성결', 와룡생류 전통 복수극의 결을 따른다. 핵심은 '왜 강해져야 하는가'가 처음부터 못박혀 있다는 점과, 복수의 끝에서 마주하는 허무·진실의 반전이다.","beats":[{"title":"1막 · 멸문의 밤","synopsis":"평온이 핏빛으로 뒤집히고 주인공이 유일한 생존자가 되는 발단부.","folder":true,"children":[{"title":"평온한 일상과 가문의 위상","synopsis":"멸문 직전의 가문/사문을 따뜻하게 그려라. 부모·사부의 무공 명성, 형제·동문 간 정, 주인공이 물려받을 가전절기의 존재를 슬쩍 심어둔다. 독자가 이 세계가 무너지기를 아까워하도록 정서적 자산을 쌓는 단계."},{"title":"기습과 학살","synopsis":"정체불명의 흑의인 또는 위장한 손님이 가문을 도륙한다. 압도적 무력차를 보여 절망감을 각인시켜라. 주인공은 우물·지하실·시신 더미 속 등 우연한 곳에 숨어 살아남고, 원수의 특징(흉터·병기·문양·말투) 하나만 목격한다."},{"title":"단 하나의 단서와 유언","synopsis":"죽어가는 사부/부모가 비급, 신물, 혹은 '누구를 찾아가라'는 유언을 남긴다. 복수의 방향과 성장의 수단을 동시에 쥐어주되, 정보를 의도적으로 불완전하게 남겨 후반 반전의 씨앗을 묻는다."}]},{"title":"2막 · 와신상담의 수련","synopsis":"바닥에서 일어선 주인공이 기연과 고행으로 힘을 쌓는 성장부.","folder":true,"children":[{"title":"굴욕과 바닥","synopsis":"무력한 주인공이 강호의 냉혹함을 체감한다. 거지·하인·노예로 전락하거나 약자로서 멸시당하는 장면으로 '현재의 무력함'을 독자가 함께 견디게 한다. 복수심이 식지 않도록 원수에 대한 소문을 간헐적으로 흘려라."},{"title":"기연 또는 은거고수와의 만남","synopsis":"동굴 속 비급, 죽어가는 마교 노고수, 절벽 아래 영약 등 무협 특유의 '기연'을 배치. 단 거저 얻지 말고 대가(목숨을 건 시련, 사부의 까다로운 조건, 신체적 한계)를 치르게 해 성장의 설득력을 확보한다."},{"title":"벽을 넘는 폐관수련","synopsis":"주화입마 위기, 깨달음의 순간(자연·검·물의 흐름에서 얻는 오성)을 그린다. 무공의 작동 원리를 구체적으로 묘사해 후반 결투의 카타르시스를 위한 기술적 복선을 깐다."},{"title":"첫 시험과 작은 복수","synopsis":"성장을 검증하는 중간 전투. 원수의 졸개·하수인을 처치하며 정보를 캐낸다. 동시에 '복수의 사다리'가 생각보다 높고 배후가 거대함을 알게 되어 사건의 규모를 키운다."}]},{"title":"3막 · 원수 추적과 강호의 음모","synopsis":"원수에 다가갈수록 드러나는 거대한 진실과 흔들리는 신념.","folder":true,"children":[{"title":"조력자와 연심","synopsis":"여협·동료·정파 인물이 합류한다. 복수에만 매몰된 주인공을 인간적으로 붙드는 축. 복수와 사랑/우정 사이의 가치 충돌을 미리 긴장으로 깔아둔다."},{"title":"거짓 원수와 첫 반전","synopsis":"지목했던 원수가 실은 누명을 썼거나 또 다른 배후의 도구였음이 드러난다. 주인공의 정의가 흔들리고, 진짜 적의 윤곽이 강호 전체의 음모(맹주·황실·마교)와 얽혀 있음을 보여준다."},{"title":"신념의 위기","synopsis":"복수의 정당성 자체가 회의에 빠지는 저점. 무고한 희생, 자신이 괴물이 되어가는 자각, 또는 원수에게 동정할 사연이 있음을 알게 되어 내적 갈등을 극대화한다."}]},{"title":"4막 · 최후의 결착","synopsis":"진짜 원수와의 결전, 그리고 복수 이후의 공허를 다루는 결말.","folder":true,"children":[{"title":"진상의 폭로","synopsis":"멸문의 진짜 이유(가전절기·신물·과거의 죄·정파의 위선)가 완전히 밝혀진다. 1막에 심은 단서들이 회수되며 독자의 퍼즐이 맞춰지는 순간."},{"title":"최종 결투","synopsis":"축적한 무공·깨달음·동료의 도움이 총동원되는 클라이맥스. 단순 우세승이 아니라 신념의 차이가 승부를 가르도록 설계. 2막에서 깐 기술적 복선을 결정타로 회수한다."},{"title":"복수 그 후의 허무와 선택","synopsis":"원수를 베었으나 남는 것은 공허뿐. 주인공이 강호에 남을지, 은거할지, 연인과 떠날지를 택하며 '복수가 사람을 구원하지 못한다'는 무협적 비애를 남긴다."}]}]},{"id":"g4-orphan-to-grandmaster","category":"무협","name":"출세입신 (소년영웅 성장기)","desc":"보잘것없는 소년/하급제자가 강호에 나아가 협을 행하며 천하제일을 향해 성장하는 정통 영웅서사. 김용 '사조영웅전' 곽정, '의천도룡기' 장무기, 와룡생·고룡 초기작의 골격. 핵심은 무공의 단계적 성장과 더불어 '협(俠)'이라는 가치의 내면화, 그리고 정파-마교-황실로 확장되는 강호 세계관의 점층적 개방이다.","beats":[{"title":"1막 · 강호로의 출발","synopsis":"우물 안에서 벗어나 넓은 강호의 첫발을 딛는 도입부.","folder":true,"children":[{"title":"촌뜨기 소년의 결핍","synopsis":"주인공의 출신을 낮게 잡되 숨은 자질(우직함, 기억력, 특이체질, 가전 내공)을 심어둔다. 세상 물정 모르는 순박함이 후일 협의 그릇임을 암시. 독자가 응원하고 싶은 약자로 출발시킨다."},{"title":"스승/입문과 첫 무공","synopsis":"기인을 만나거나 문파에 입문해 무공의 기초를 배운다. 정통 내공심법의 원리, 초식의 이름과 결을 소개하며 무협 세계의 '룰'을 독자에게 학습시킨다."},{"title":"넓은 세상의 충격","synopsis":"처음 강호에 나와 고수들의 세계, 문파 간 알력, 정사 대립을 목격한다. 자신이 우물 안 개구리였음을 깨닫고 더 큰 목표를 품는다."}]},{"title":"2막 · 협의 시련","synopsis":"강호의 부조리에 부딪히며 협의 의미를 배우는 단계.","folder":true,"children":[{"title":"불의와의 첫 대면","synopsis":"강자가 약자를 핍박하는 현장에 끼어든다. 힘이 모자라 좌절하거나 값비싼 대가를 치르되, '왜 협을 행해야 하는가'를 몸으로 배우는 가치 형성의 장면."},{"title":"동료·연인·라이벌의 형성","synopsis":"평생의 의형제, 정인, 숙적이 될 인물들과 인연을 맺는다. 무협 특유의 강호 인맥도를 깔되, 각 인물에게 후반에 회수할 사연·욕망을 부여한다."},{"title":"기연과 비약적 성장","synopsis":"절세비급·영약·내공전수 등 결정적 성장 기연. 단 운이 아니라 앞서 행한 협행의 보답으로 얻게 해 '선행=성장'의 무협적 인과를 강화한다."},{"title":"정체성의 시험","synopsis":"정파의 위선과 마교의 매력 사이, 혹은 사문과 정의 사이에서 갈등한다. 흑백논리를 넘어선 자기만의 협을 정립하기 시작하는 분기점."}]},{"title":"3막 · 강호의 격랑","synopsis":"주인공이 강호 대사건의 한복판으로 휘말려 드는 절정 전단계.","folder":true,"children":[{"title":"대음모의 발각","synopsis":"무림맹 탈취, 마교 발호, 황실 개입, 절세신공 쟁탈 등 천하를 흔드는 거대 음모가 드러난다. 개인의 성장담이 강호의 운명과 결합되는 규모 확장."},{"title":"누명과 추락","synopsis":"주인공이 배신·오해·함정으로 누명을 쓰고 모두에게 쫓기는 신세가 된다. 가장 낮은 곳에서 진짜 자신을 마주하는 무협적 정화의 저점."},{"title":"각성과 재기","synopsis":"고립 속에서 무공의 정점을 돌파하거나 진정한 협의 의미를 깨우친다. 흩어진 동료를 다시 규합하며 반격을 준비한다."}]},{"title":"4막 · 천하제일을 향하여","synopsis":"최종 대결과 새로운 강호의 질서를 세우는 결말.","folder":true,"children":[{"title":"최종 보스와의 결전","synopsis":"강호를 어지럽힌 절대악(마교주·역적·위선의 맹주)과 맞붙는다. 성장의 총합이 발휘되는 동시에 협의 신념이 무력을 이기는 구도로 설계한다."},{"title":"협의 완성과 명성","synopsis":"주인공이 천하의 인정을 받는다. 다만 천하제일의 자리보다 '협을 지킨 사람'으로 기억되는 데 방점을 둬 무협의 도덕적 이상을 구현한다."},{"title":"강호를 떠나거나 새 질서","synopsis":"명예를 뒤로하고 정인과 은거하거나, 후학을 위해 새 질서를 세운다. 끝없이 이어지는 강호의 순환을 암시하며 여운을 남긴다."}]}]},{"id":"g4-jianghu-noir-loner","category":"무협","name":"고검비정 (낭인 하드보일드)","desc":"고룡(古龍)이 개척한 결. 출신·문파·성장담을 비우고, 이미 완성된 고독한 검객/낭인이 단 하나의 사건을 통과하며 인간과 강호의 그늘을 응시한다. '소십일랑', '초류향', '다정검객무정검'의 분위기. 액션보다 분위기·심리·반전, 짧고 시적인 문체, 우정과 술과 배신이 핵심 정조. 누가 이겼느냐보다 '어떤 인간이었느냐'를 묻는다.","beats":[{"title":"1막 · 비 오는 객잔","synopsis":"고독한 검객과 하나의 사건이 조우하는 분위기 도입부.","folder":true,"children":[{"title":"낭인의 등장","synopsis":"이미 강호에 이름났거나 잊힌 고수가 술집·객잔·빈 거리에 등장한다. 과거를 직접 설명하지 말고 흉터·눈빛·낡은 검·주변의 반응으로 내력을 암시. 첫 장면에 시적·건조한 톤을 박아라."},{"title":"의뢰 또는 사건의 발단","synopsis":"살인 의뢰, 실종, 도난당한 신물, 친구의 죽음 등 사건이 던져진다. 주인공이 왜 개입하는지 명분을 모호하게 두되, 그의 신념·미감이 거절을 못 하게 만드는 인물임을 보여준다."},{"title":"강호의 그늘","synopsis":"화려한 강호의 이면 — 돈으로 움직이는 살수, 위선적 명문, 버려진 약자들을 스케치한다. 세계의 냉소적 질감을 깔아 주인공의 고독을 부각한다."}]},{"title":"2막 · 술과 친구와 거짓말","synopsis":"사건을 좇으며 인연과 함정 사이를 헤매는 전개부.","folder":true,"children":[{"title":"맞수와의 교감","synopsis":"적이 될지 벗이 될지 모를 또 다른 고수와 만난다. 고룡식 '검을 겨누기 전의 대화', 술 한 잔의 교감을 통해 무력보다 인간 됨됨이를 견준다."},{"title":"거짓 정보와 헛다리","synopsis":"사건의 표면이 거짓임을 암시하는 단서들. 주인공이 한 번 속고, 그 속에서 진짜 적의 그림자를 직감한다. 추리적 긴장을 분위기로 끌고 간다."},{"title":"여인과 위험","synopsis":"팜파탈 혹은 비극의 여인이 등장한다. 매혹과 의심이 공존하는 관계로, 그녀가 사건의 열쇠이자 함정일 가능성을 양립시켜 둔다."},{"title":"배신의 첫 칼","synopsis":"믿었던 인물의 배신, 혹은 친구의 죽음으로 사건이 급변한다. 주인공의 냉정에 처음으로 금이 가는 감정의 균열을 보여준다."}]},{"title":"3막 · 진실의 칼끝","synopsis":"사건의 본질과 인간의 밑바닥이 드러나는 반전부.","folder":true,"children":[{"title":"흑막의 정체","synopsis":"사건을 설계한 진짜 인물이 드러난다. 흔히 가장 가깝거나 가장 고결해 보이던 자. 무공의 강함이 아니라 인간 욕망의 깊이로 충격을 준다."},{"title":"고독의 대가","synopsis":"주인공이 잃은 것 — 친구, 연인, 신념 — 을 마주한다. 승리가 예정돼 있어도 공허할 것임을 미리 느끼게 하는 정서적 클라이맥스."}]},{"title":"4막 · 마지막 한 수","synopsis":"단 한 합의 결투와 떠나가는 검객의 뒷모습.","folder":true,"children":[{"title":"일초필살의 대결","synopsis":"고룡식 결투 — 길게 끌지 않고 단 한 합, 한 호흡에 승부가 난다. 속도보다 그 한 수에 담긴 인생과 신념을 묘사하는 데 집중한다."},{"title":"이긴 자의 빈손","synopsis":"이겼으나 모든 것을 잃은 주인공. 강호는 그대로 흐르고, 죽은 자도 떠난 자도 돌아오지 않음을 담담히 보여준다."},{"title":"다시 길 위로","synopsis":"주인공이 말없이 강호 어딘가로 사라진다. 끝맺지 않은 여운, 다음 비 오는 객잔을 암시하며 낭인의 영원한 유랑을 남긴다."}]}]},{"id":"g4-divine-art-contest","category":"무협","name":"비급쟁탈 (신공쟁패 강호대란)","desc":"절세무공 비급·신병이기·강호제패의 열쇠를 둘러싸고 정파·사파·마교가 뒤엉켜 천하가 피로 물드는 대하 군상극. 김용 '소오강호'의 벽사검보·규화보전, '천룡팔부'의 군웅할거, 양우생류 강호대란의 골격. 핵심은 여러 세력의 동시다발적 욕망, 무림맹·맹주쟁탈전, 그리고 '무공을 향한 욕망이 사람을 어떻게 망가뜨리는가'라는 주제다.","beats":[{"title":"1막 · 강호를 흔든 소문","synopsis":"비급/신물의 출현이 강호 전체에 파문을 일으키는 발단.","folder":true,"children":[{"title":"전설의 출현","synopsis":"사라졌던 절세비급·신병의 단서가 세상에 나타난다. 그 무공의 위력에 얽힌 전설(과거 그것을 익힌 자의 광기·종말)을 깔아 욕망과 경고를 동시에 심는다."},{"title":"첫 피와 군웅의 발동","synopsis":"단서를 쥔 자가 떼죽음당하며 쟁탈전의 막이 오른다. 정·사·마 각 세력의 핵심 인물들을 한꺼번에 등장시켜 군상극의 판을 깐다."},{"title":"주인공의 우연한 연루","synopsis":"별 욕심 없던 주인공이 우연히 단서·유품·생존자를 떠안으며 소용돌이에 휘말린다. 모두가 그를 노리게 되는 추격의 시작."}]},{"title":"2막 · 정사마의 합종연횡","synopsis":"세력 간 동맹과 배신이 어지럽게 교차하는 전개부.","folder":true,"children":[{"title":"무림맹의 계산","synopsis":"정파 무림맹이 명분을 내세워 비급을 '봉인'한다며 실은 독점하려 한다. 정파의 위선을 드러내고, 맹주 자리를 둘러싼 내부 암투를 보여준다."},{"title":"마교/사파의 책략","synopsis":"마교·사파가 정면이 아닌 이간·잠입·독계로 움직인다. 단순 악역이 아니라 그들 나름의 논리·매력·억울함을 부여해 선악 구도를 흐린다."},{"title":"위장 동맹과 이중간자","synopsis":"주인공 진영에도 첩자가 있고, 적 진영에도 내응자가 있다. 누가 누구 편인지 모르는 정보전의 긴장을 고조시킨다."},{"title":"쟁탈의 첫 대혈전","synopsis":"비급의 위치가 특정되며 모든 세력이 한곳에 집결, 난전이 벌어진다. 다수 고수의 무공을 교차 편집하듯 보여주는 군상 액션의 하이라이트."}]},{"title":"3막 · 욕망의 대가","synopsis":"비급을 둘러싼 진실과 인간 파멸이 드러나는 절정.","folder":true,"children":[{"title":"비급의 비밀","synopsis":"절세무공의 숨은 대가(자아 상실·신체 파괴·인륜 위배, 예: 자궁/거세 같은 금기)가 폭로된다. 욕망의 정점에서 무공의 저주적 본질이 드러나는 반전."},{"title":"광기에 삼켜진 자들","synopsis":"비급을 익힌 자들이 주화입마·광기·괴물화로 무너진다. 무공을 향한 집착이 인간을 어떻게 파괴하는지 구체적 비극으로 형상화한다."},{"title":"주인공의 선택","synopsis":"비급을 익혀 절대자가 될 것인가, 파기할 것인가. 천하제일의 유혹 앞에서 주인공의 인간성이 시험받는 주제적 분기점."}]},{"title":"4막 · 강호의 새 질서","synopsis":"최종 결착과 비급 이후 강호의 향방을 그리는 결말.","folder":true,"children":[{"title":"최후의 쟁패","synopsis":"비급을 완성한 최강자, 혹은 흑막과의 최종 결전. 단순 무력이 아니라 신념·연대·희생이 변수가 되도록 설계한다."},{"title":"비급의 종말","synopsis":"비급이 소멸하거나 봉인되거나, 욕망의 화신과 함께 사라진다. 1막의 전설·경고가 회수되며 '천하제일은 환상'이라는 주제가 매듭지어진다."},{"title":"남은 자들의 강호","synopsis":"쟁탈전이 남긴 폐허와 생존자들. 정사마의 세력 재편, 새 맹주, 그리고 또 다른 전설의 씨앗을 암시하며 강호의 영원한 순환을 남긴다."}]}]},{"id":"g4-undercover-infiltration","category":"무협","name":"와신잠행 (위장잠입 첩보무협)","desc":"주인공이 신분을 숨기고 적의 문파·마교·관부 내부에 잠입해 정보를 캐고 음모를 파헤치는 첩보·서스펜스형 무협. 정체 탄로의 긴장, 적 진영에서 싹트는 의외의 인연, 그리고 '어느 쪽이 진짜 나인가'라는 정체성 붕괴가 핵심. 황실 암투·금의위·동창류 무협, 정탐·세작 모티프의 결을 따른다. 무력보다 두뇌·연기·심리전이 우위.","beats":[{"title":"1막 · 잠입의 명령","synopsis":"주인공이 위장 신분을 쓰고 적진에 침투하는 도입부.","folder":true,"children":[{"title":"임무의 부여","synopsis":"사문·맹·관부로부터 적 진영 잠입 임무를 받는다. 잠입의 명분(복수·대의·강요된 약점)을 분명히 하고, 실패 시 대가(가족 인질·사문 멸문)를 걸어 배수진을 친다."},{"title":"가짜 신분의 구축","synopsis":"주인공이 새 이름·내력·말투·무공 위장을 준비한다. 위장의 디테일과 허점을 동시에 심어, 그 허점이 후반 위기의 씨앗이 되게 한다."},{"title":"적진의 문턱","synopsis":"입문 시험·신원 검증을 통과하며 적 진영에 들어선다. 첫 의심의 눈초리, 감시자의 존재를 배치해 잠입 서스펜스의 기조를 깐다."}]},{"title":"2막 · 이중생활","synopsis":"적진에 녹아들며 정보를 캐고 정체를 숨기는 긴장부.","folder":true,"children":[{"title":"신뢰의 획득","synopsis":"주인공이 공을 세우거나 위기를 모면하며 적 수뇌의 신임을 얻는다. 적의 핵심부로 한 발씩 들어가되, 그 과정에서 양심을 거스르는 선택을 강요받는다."},{"title":"적진의 인연","synopsis":"적 진영에서 정인·동료·은인이 생긴다. 그들이 결코 단순한 악이 아님을 보여줘, 임무 완수가 곧 배신이 되는 도덕적 딜레마를 심는다."},{"title":"발각의 위기","synopsis":"위장이 들통날 뻔한 아슬아슬한 순간들. 정체를 의심하는 인물, 과거를 아는 자의 등장, 위장의 허점 노출 등으로 서스펜스를 끌어올린다."},{"title":"충격적 진실의 단서","synopsis":"잠입 끝에 캐낸 정보가 임무의 전제를 뒤흔든다 — 진짜 악은 적이 아니라 자신을 보낸 쪽일 수도. 신념의 지반이 흔들리기 시작한다."}]},{"title":"3막 · 정체성의 붕괴","synopsis":"어느 편이 진짜 자신인지 흔들리는 내적 절정.","folder":true,"children":[{"title":"정체 탄로","synopsis":"결국 위장이 벗겨진다. 적 진영의 인연들이 배신감에 등을 돌리는 순간, 주인공이 잃을 것의 무게가 비로소 드러난다."},{"title":"양쪽 모두의 적","synopsis":"적에게도 아군에게도 버림받는 고립. 진짜 흑막의 음모가 전모를 드러내고, 주인공은 어느 쪽도 정의롭지 않음을 깨닫는다."},{"title":"자기 자신의 선택","synopsis":"주어진 임무도 적의 논리도 아닌, 자신이 믿는 협을 택한다. 위장된 정체성을 벗고 진짜 자신으로 서는 주제적 전환점."}]},{"title":"4막 · 폭로와 결착","synopsis":"진짜 흑막을 무너뜨리고 정체성을 회복하는 결말.","folder":true,"children":[{"title":"흑막의 음모 분쇄","synopsis":"양 진영을 조종한 진짜 흑막과의 대결. 잠입으로 모은 정보·인맥·증거가 무기가 되어, 무력만으로 풀 수 없던 매듭을 푼다."},{"title":"적이었던 자들과의 화해","synopsis":"적진의 인연들과 오해를 풀거나 비극적으로 작별한다. 잠입이 남긴 상흔과, 그럼에도 진짜였던 마음을 매듭짓는다."},{"title":"벗은 가면 이후","synopsis":"임무가 끝나고 주인공이 자신의 진짜 이름으로 돌아간다. 잠입이 바꿔놓은 그의 신념과, 강호에 남긴 변화를 여운으로 남긴다."}]}]},{"id":"g4-rebirth-cheat","category":"무협","name":"환생회귀 (전생귀환 먼치킨)","desc":"현대 신무협·웹소설 무협의 주류 결. 절정 고수였다 죽거나 패배한 주인공이 과거(혹은 다른 몸)로 회귀·환생해, 전생의 기억과 무공 지식을 치트로 삼아 운명을 다시 쓴다. '검신' '나노마신' '화산귀환'류의 골격. 핵심은 '미래를 아는 자'의 우위, 사이다식 응징과 성장, 비극적 과거의 교정, 그리고 회귀로도 바꿀 수 없는 운명과의 싸움이다.","beats":[{"title":"1막 · 죽음과 회귀","synopsis":"절정에서 추락한 주인공이 과거로 돌아가는 발단.","folder":true,"children":[{"title":"전생의 최후","synopsis":"주인공이 천하제일을 코앞에 두고, 혹은 모든 것을 잃고 죽는 순간을 강렬하게 그린다. 무엇을 후회하는지(배신·무력·잃은 이) 명확히 박아 회귀의 목표를 설정한다."},{"title":"눈을 뜨니 과거","synopsis":"약하고 어렸던 시절, 혹은 운명의 분기점으로 돌아온 자각의 충격. 전생의 기억·무공 이해가 고스란히 남아 있음을 확인시켜 치트의 전제를 세운다."},{"title":"달라진 첫 선택","synopsis":"전생과 다른 첫 결정으로 즉각적 우위를 보여준다. 미래 지식으로 위기를 회피하거나 기연을 선점하는 '사이다' 첫 한 방으로 독자를 사로잡는다."}]},{"title":"2막 · 운명을 다시 쓰다","synopsis":"미래 지식을 무기로 빠르게 성장하고 판을 바꾸는 전개부.","folder":true,"children":[{"title":"기연의 선점","synopsis":"전생에 남이 가져갔거나 놓쳤던 비급·영약·인재를 먼저 차지한다. 미래를 아는 자의 압도적 효율을 보여주되, 너무 쉽지 않게 약간의 변수를 섞는다."},{"title":"전생의 은원 정리","synopsis":"은인은 미리 구하고 원수는 싹부터 자른다. 통쾌한 응징과 따뜻한 보은을 교차시켜 '회귀의 보상'을 독자에게 지급한다."},{"title":"압도적 성장의 가속","synopsis":"전생의 시행착오를 건너뛴 효율적 수련으로 또래·선배를 압도한다. 무공 성장의 쾌감을 단계적으로 보여주되, 주변의 경이·시기 반응으로 입체화한다."},{"title":"어긋나는 미래","synopsis":"주인공의 개입으로 역사가 비틀리며 알던 미래가 빗나가기 시작한다. 치트의 유효기간이 끝나가는 긴장, '이제부터는 미지'라는 새 국면을 연다."}]},{"title":"3막 · 바꿀 수 없는 운명","synopsis":"회귀로도 거스르지 못하는 거대한 적과 마주하는 절정 전단계.","folder":true,"children":[{"title":"전생을 망친 진짜 원흉","synopsis":"전생의 파멸 배후에 있던 거대한 흑막·천재지변·강호대란의 정체가 드러난다. 개인의 복수를 넘어선, 회귀의 진짜 사명이 제시된다."},{"title":"회귀의 한계","synopsis":"미래 지식이 통하지 않는 압도적 적, 혹은 회귀해도 반복되는 비극과 마주한다. 치트만으로 이길 수 없음을 깨닫는 저점의 위기."},{"title":"진짜 성장","synopsis":"전생의 답습이 아닌, 이번 생에서만 얻은 깨달음·인연·새 무공으로 한계를 돌파한다. 회귀자에서 '새로운 자신'으로 진화하는 전환점."}]},{"title":"4막 · 새로 쓴 결말","synopsis":"전생의 비극을 끝내고 다른 결말을 완성하는 클라이맥스와 결말.","folder":true,"children":[{"title":"운명과의 최종 결전","synopsis":"전생을 망쳤던 적·재앙과 다시 맞붙는다. 이번엔 미래 지식과 새로 얻은 힘·동료가 결합되어, 전생과 정반대의 결과를 만들어내는 클라이맥스."},{"title":"지키고 싶던 것을 지키다","synopsis":"전생에 잃었던 사람·문파·신념을 이번 생에선 지켜낸다. 회귀의 정서적 보상이 완성되는 가장 감정적인 순간."},{"title":"전생 너머의 삶","synopsis":"전생의 정점(천하제일)을 넘어선 자리, 혹은 권력을 내려놓은 평온. 회귀자가 비로소 '미래에 매이지 않는' 진짜 삶을 사는 결말로 매듭짓는다."}]}]},{"id":"g5-slow-burn-classic","category":"로맨스","name":"슬로우번 정통 로맨스 (만남→오해→화해→결합)","desc":"두 사람이 서서히 끌리고, 관계가 깊어지는 순간 결정적 오해나 외부 장애로 갈라졌다가, 진심을 증명하며 재결합하는 로맨스의 가장 보편적인 정통 구조. 제인 오스틴 계열·할리퀸·정통 한국 로맨스의 뼈대. 독자는 '두 사람이 결국 이어진다'는 약속(HEA, 해피엔딩) 위에서 감정의 밀도를 기대한다.","beats":[{"title":"1막 — 만남과 끌림의 씨앗","synopsis":"두 주인공이 처음 마주치고, 호감과 마찰이 동시에 발생하는 단계. 끝까지 갈 감정의 첫 불씨를 심는다.","folder":true,"children":[{"title":"운명적 첫 대면","synopsis":"여주와 남주가 처음 만나는 장면. 인상적인 첫 대사·사건으로 둘의 성격 대비를 드러내고, 독자가 '이 둘이 어떻게 될까' 궁금하게 만드는 미세한 스파크를 심어라. 첫인상은 호감이거나 반대로 가벼운 충돌이 좋다."},{"title":"재회를 만드는 장치","synopsis":"우연이 아닌 필연으로 다시 엮이게 만드는 구조적 이유를 깐다. 같은 직장·계약·이웃·가족 연 등 '계속 부딪힐 수밖에 없는 설정'을 제시해 만남의 빈도를 정당화하라."},{"title":"끌림의 자각과 부정","synopsis":"한쪽 혹은 양쪽이 상대에게 끌리는 자신을 깨닫지만 이유(과거 상처·신분·자존심)를 들어 부정하는 장면. 독자가 응원하고 싶은 '밀당의 시작'을 만든다."}]},{"title":"2막 — 가까워짐과 친밀의 축적","synopsis":"함께 보내는 시간이 늘며 신뢰와 감정이 쌓이는 단계. 작은 다정함과 취약함의 공유로 관계를 깊게 만든다.","folder":true,"children":[{"title":"벽을 허무는 사건","synopsis":"위기·돌봄·비밀 공유 등으로 한 사람이 다른 사람의 방어벽을 무너뜨리는 장면. 평소 보이지 않던 약한 면이나 따뜻한 면을 노출시켜 감정이 확 가까워지게 하라."},{"title":"달콤한 동행 몽타주","synopsis":"일상 공유·작은 데이트·은근한 스킨십이 누적되는 장면들. 독자가 가장 즐기는 '설렘 구간'. 사소한 배려와 시선 교환을 디테일하게 묘사해 케미를 끌어올려라."},{"title":"감정의 정점·첫 진심 고백 직전","synopsis":"둘 다 서로를 향한 마음을 인정하게 되는 절정 장면(첫 키스·뜨거운 순간·진심 어린 대화). 동시에 곧 닥칠 갈등의 복선을 살짝 깔아 긴장을 예고하라."}]},{"title":"3막 — 오해와 결별 (블랙 모먼트)","synopsis":"관계가 가장 좋을 때 결정적 오해·비밀 폭로·외부 압력이 터져 둘이 갈라서는 가장 어두운 국면.","folder":true,"children":[{"title":"비밀의 폭로","synopsis":"앞서 깔아둔 비밀(거짓 정체·과거·계약의 진실)이 최악의 타이밍에 드러나는 장면. 상대가 배신감을 느낄 충분한 근거를 보여줘 결별을 설득력 있게 만들어라."},{"title":"결별과 절망","synopsis":"둘이 갈라서는 블랙 모먼트. 각자 혼자 남아 상실을 통감하는 모습을 교차 묘사해 독자의 감정을 바닥까지 끌어내린다. '이대로 끝일까' 하는 공포를 심어라."},{"title":"오해의 진실 발견","synopsis":"제3자의 증언·증거·회상을 통해 오해의 실체가 드러나는 장면. 잘못한 쪽이 자신의 과오를 깨닫고, 다시 다가갈 명분과 동기를 얻게 하라."}]},{"title":"4막 — 증명과 재결합 (HEA)","synopsis":"진심을 행동으로 증명하고 장애를 넘어 다시 하나가 되는 마무리. 독자가 기다린 해피엔딩의 보상.","folder":true,"children":[{"title":"대담한 사과·그랜드 제스처","synopsis":"주인공이 자존심을 버리고 상대에게 진심을 증명하는 결정적 행동(공개 고백·희생·먼 길을 달려옴). 변화한 모습을 행동으로 보여줘 화해를 정당화하라."},{"title":"마음의 빗장 풀기와 재결합","synopsis":"용서와 받아들임의 순간. 그동안 쌓인 감정이 터지는 카타르시스의 키스·포옹·고백을 배치하라. 관계의 본질이 무엇이었는지 한 줄로 못 박는 대사가 효과적이다."},{"title":"에필로그 — 약속된 미래","synopsis":"시간이 흐른 뒤 안정된 두 사람의 일상이나 결혼·아이 등 미래를 보여주는 보너스 장면. 독자에게 완전한 안심과 여운을 선사하라."}]}]},{"id":"g5-enemies-to-lovers","category":"로맨스","name":"원수에서 연인으로 (Enemies-to-Lovers)","desc":"처음엔 서로를 적대·경멸하던 두 사람이 강제로 엮이며 미움이 끌림으로 뒤집히는 구조. 적대의 강도가 클수록 결합의 카타르시스가 큰 '텐션 중심' 로맨스. 라이벌 기업·정적·앙숙 가문·복수 관계 등에서 자주 쓰이며, 날선 대사 배틀과 권력 다툼이 매력 포인트.","beats":[{"title":"1막 — 선언된 적대","synopsis":"두 사람이 명확한 이해 충돌로 적이 되는 단계. 미움의 근거와 팽팽한 대립 구도를 세운다.","folder":true,"children":[{"title":"충돌의 선전포고","synopsis":"두 주인공이 정면으로 부딪히는 첫 장면. 경쟁·복수·이권 등 적대의 명확한 이유를 제시하고, 날카로운 설전으로 둘의 만만찮은 기싸움을 보여줘라."},{"title":"강제 동거·동맹의 빌미","synopsis":"미워하면서도 떨어질 수 없게 만드는 장치(공동 프로젝트·정략·한 공간 갇힘)를 깐다. 적대하던 둘이 어쩔 수 없이 협력해야 하는 상황을 설계하라."},{"title":"예상 밖의 한 수","synopsis":"상대가 단순한 악당이 아님을 보여주는 첫 균열. 의외의 유능함·배려·취약함을 한 번 노출시켜 '미움' 안에 '인정'의 씨앗을 심어라."}]},{"title":"2막 — 적대 속 끌림 (싸우며 가까워짐)","synopsis":"협력하며 서로의 진면목을 보고, 미움과 끌림이 뒤섞여 혼란스러워지는 단계.","folder":true,"children":[{"title":"날선 케미와 위태로운 거리","synopsis":"말다툼이 곧 밀당이 되는 장면들. 서로를 도발하다 의식하게 되는 순간, 가까워진 물리적 거리에서 발생하는 긴장을 농밀하게 묘사하라."},{"title":"약점을 본 순간","synopsis":"한쪽이 상대의 숨겨진 상처·고독·진심을 우연히 목격하는 장면. 미움의 명분이 흔들리고 연민과 끌림으로 바뀌는 전환점을 만들어라."},{"title":"선을 넘는 사건","synopsis":"감정이 폭발해 한 번 선을 넘는 키스나 뜨거운 순간. 직후 둘 다 '이건 실수다' '적인데' 하며 혼란에 빠지게 해 텐션을 극대화하라."}]},{"title":"3막 — 충성심의 시험 (배신의 위기)","synopsis":"끌림과 원래의 적대적 목적이 충돌하며, 한쪽이 상대를 배신하거나 배신처럼 보이는 위기.","folder":true,"children":[{"title":"과거 목적과의 충돌","synopsis":"복수·승리·임무 등 처음의 적대 목적이 다시 전면에 떠오르는 장면. 사랑과 목적 중 하나를 택해야 하는 딜레마에 주인공을 몰아넣어라."},{"title":"배신과 추락","synopsis":"한쪽이 상대를 이용했거나 해친 사실이 드러나는 블랙 모먼트. 적대로 시작한 관계였기에 더 깊은 상처가 되는 결별을 그려라."},{"title":"진심의 재확인","synopsis":"배신한 쪽이 자신이 진짜 잃은 것이 무엇인지 깨닫는 장면. 적대의 목적보다 상대가 소중했음을 통감하고 되돌리기로 결심하게 하라."}]},{"title":"4막 — 동맹에서 연인으로","synopsis":"적대를 완전히 청산하고 서로를 선택하는 결말. 옛 원수가 가장 든든한 내 편이 되는 반전의 쾌감.","folder":true,"children":[{"title":"편이 되어주는 증명","synopsis":"예전 같으면 적이었을 상대를 위해 자신의 이익·자존심·승리를 포기하는 결정적 선택. 행동으로 '이제 네 편'임을 증명하게 하라."},{"title":"항복 같은 고백","synopsis":"끝까지 지지 않으려던 두 사람이 마침내 서로에게 마음을 내주는 고백. 적대 시절의 대사를 뒤집어 재활용하면 강렬한 여운을 준다."},{"title":"에필로그 — 최강의 동맹","synopsis":"옛 원수가 이제 누구보다 강한 파트너십을 이룬 미래를 보여줘라. 함께라면 세상도 상대할 수 있다는 만족감으로 마무리한다."}]}]},{"id":"g5-fake-relationship","category":"로맨스","name":"가짜 관계 (계약·위장 연애에서 진짜로)","desc":"계약 연애·위장 결혼·가짜 약혼 등 거짓 관계로 시작했다가 연기가 진심이 되는 구조. 각자의 이해관계(상속·체면·비자·복수)로 손을 잡지만, 함께 연기하는 사이 진짜 감정이 자라난다. '거짓과 진심의 경계'에서 오는 달콤한 긴장이 핵심이며 한국 로맨스·로맨틱 코미디의 단골.","beats":[{"title":"1막 — 계약의 성립","synopsis":"거짓 관계가 필요한 이유와 그 규칙이 정해지는 단계. 두 사람의 거래가 시작된다.","folder":true,"children":[{"title":"각자의 절박한 사정","synopsis":"두 주인공이 왜 가짜 관계가 필요한지 보여주는 장면. 상속·결혼 압박·체면·복수 등 서로 다른 이해관계를 제시해 거래의 동기를 명확히 하라."},{"title":"거래의 협상과 규칙","synopsis":"둘이 조건을 흥정하며 계약을 맺는 장면. '선을 넘지 않는다' 같은 규칙을 정하게 해, 나중에 그 규칙이 깨질 때의 카타르시스를 예약해 두어라."},{"title":"어설픈 첫 연기","synopsis":"공식 석상에서 처음 커플을 연기하는 장면. 호흡이 안 맞아 벌어지는 코믹한 상황과, 의외로 잘 맞는 한순간을 동시에 보여줘 케미의 가능성을 깔아라."}]},{"title":"2막 — 연기 속에 스며드는 진심","synopsis":"함께 연기를 거듭하며 가짜와 진짜의 경계가 흐려지고, 진짜 감정이 자라는 단계.","folder":true,"children":[{"title":"역할에 빠져드는 순간","synopsis":"남들 앞에서 보여주려던 다정함이 진심으로 변하는 장면. 손잡기·포옹 등 '연기'가 실제 설렘이 되는 미묘한 감정 변화를 섬세하게 포착하라."},{"title":"사적인 발견","synopsis":"계약 밖의 진짜 모습(가족·상처·일상)을 알게 되는 장면. 거래 상대가 아닌 한 인간으로 상대를 이해하게 되며 마음이 깊어지게 하라."},{"title":"질투라는 균열","synopsis":"가짜 관계인데도 상대 곁의 다른 사람에게 질투를 느끼는 장면. '왜 내가 이러지' 하는 자각으로 진심을 더 이상 부정할 수 없게 만들어라."}]},{"title":"3막 — 거짓의 대가","synopsis":"가짜 관계라는 전제가 진심과 충돌하고, 계약의 종료나 거짓의 탄로로 위기가 닥치는 단계.","folder":true,"children":[{"title":"계약 종료의 시계","synopsis":"목적이 달성되어 관계를 끝낼 때가 다가오는 장면. '이제 헤어져야 한다'는 현실 앞에서 진심을 들킬까 봐 두려워하는 내면을 그려라."},{"title":"거짓의 탄로·진심의 부정","synopsis":"관계가 가짜였다는 사실이 폭로되거나, 자존심에 한쪽이 '처음부터 계약일 뿐이었다'고 진심을 부정하는 블랙 모먼트. 상대에게 깊은 상처를 남겨라."},{"title":"잃고 나서 아는 진심","synopsis":"관계가 끝난 뒤 비로소 그게 거짓이 아니었음을 깨닫는 장면. 텅 빈 일상 속에서 상대의 빈자리를 통감하게 하라."}]},{"title":"4막 — 진짜의 시작","synopsis":"계약을 넘어선 진짜 관계를 선택하는 결말. 거짓으로 시작했지만 진심으로 끝맺는다.","folder":true,"children":[{"title":"계약 없는 고백","synopsis":"이제 아무런 거래 조건 없이, 순수한 진심만으로 상대에게 다가가는 장면. '이번엔 계약이 아니라 진짜'라는 점을 분명히 드러내는 고백을 배치하라."},{"title":"규칙을 깨는 선택","synopsis":"1막에서 정한 규칙(선을 넘지 않는다 등)을 보란 듯이 깨뜨리며 진짜 연인이 되는 장면. 앞선 설정을 회수해 강한 카타르시스를 줘라."},{"title":"에필로그 — 진짜가 된 관계","synopsis":"가짜였던 약혼·결혼이 진짜가 된 미래를 보여줘라. 처음의 거래 장면과 대비되는 따뜻한 일상으로 변화를 강조하며 마무리한다."}]}]},{"id":"g5-second-chance","category":"로맨스","name":"재회 로맨스 (헤어진 연인의 두 번째 기회)","desc":"한때 사랑했으나 헤어진 두 사람이 세월이 흐른 뒤 재회해 묵은 상처를 마주하고 다시 사랑하는 구조. 첫사랑·전 연인·이혼 후 재결합 등을 다루며, 과거의 미련과 현재의 변화가 교차하는 '회한과 성숙'의 정서가 핵심. 어른들의 로맨스, 잔잔한 멜로에서 강세.","beats":[{"title":"1막 — 예고 없는 재회","synopsis":"헤어진 두 사람이 다시 마주치며 묻어둔 감정이 되살아나는 단계. 과거의 그림자를 드러낸다.","folder":true,"children":[{"title":"다시 마주친 그 사람","synopsis":"전혀 예상 못한 곳에서 옛 연인과 재회하는 장면. 반가움·당혹·원망이 뒤섞인 복잡한 첫 반응을 그리고, 둘 사이에 끝나지 않은 무언가가 있음을 암시하라."},{"title":"과거의 회상 단서","synopsis":"둘이 어떻게 사랑했고 왜 헤어졌는지 짧은 회상으로 흘리는 장면. 이별의 이유를 한 번에 다 보여주지 말고, 미스터리처럼 조금씩 풀 단서를 심어라."},{"title":"엮일 수밖에 없는 현재","synopsis":"피하고 싶지만 계속 마주쳐야 하는 현재의 상황(같은 일·공통 지인·한 동네)을 설정한다. 회피하려 할수록 가까워지는 아이러니를 만들어라."}]},{"title":"2막 — 묵은 감정의 재발견","synopsis":"재회를 거듭하며 변한 점과 변하지 않은 점을 확인하고, 식지 않은 감정과 미해결된 상처를 동시에 마주하는 단계.","folder":true,"children":[{"title":"변한 너, 그대로인 우리","synopsis":"세월에 성숙해진 상대의 모습과, 여전히 통하는 옛 호흡을 동시에 보여주는 장면. '그때 그 사람'과 '지금의 그 사람' 사이의 거리감을 섬세하게 다뤄라."},{"title":"미해결의 상처 건드리기","synopsis":"이별 당시의 오해·서운함이 다시 수면 위로 떠오르는 장면. 옛 상처를 건드려 갈등을 일으키되, 그 안에 아직 남은 미련을 비춰라."},{"title":"다시 끌리는 두려움","synopsis":"또 사랑에 빠지는 자신을 자각하면서도 '같은 상처를 반복할까' 두려워하는 장면. 한 번 실패했기에 더 신중하고 더 절실한 감정을 그려라."}]},{"title":"3막 — 과거의 진실과 현재의 장애","synopsis":"헤어진 진짜 이유가 밝혀지고, 다시 시작을 가로막는 현재의 현실이 동시에 압박하는 단계.","folder":true,"children":[{"title":"이별의 진실 폭로","synopsis":"오랫동안 오해했던 이별의 진짜 이유(가족의 개입·희생·전달되지 못한 진심)가 드러나는 장면. 'we가 헤어질 운명이 아니었다'는 사실로 회한을 폭발시켜라."},{"title":"현재의 발목 — 새로운 현실","synopsis":"재결합을 막는 현재의 장애(새 연인·가족·직업·거리)를 부각하는 장면. 과거의 오해가 풀려도 현실은 여전히 만만치 않음을 보여줘라."},{"title":"물러섬 혹은 놓아줌","synopsis":"상처를 반복하지 않으려, 또는 상대를 위해 다시 한번 멀어지려는 블랙 모먼트. '이번에도 우린 안 되는 걸까' 하는 절망의 바닥을 그려라."}]},{"title":"4막 — 두 번째 기회의 완성","synopsis":"과거의 후회를 딛고, 같은 실수를 반복하지 않겠다는 성숙한 결심으로 다시 사랑을 선택하는 결말.","folder":true,"children":[{"title":"이번엔 놓지 않겠다는 선택","synopsis":"과거에 하지 못했던 행동(붙잡기·솔직한 고백·우선순위 변경)을 이번엔 해내는 결정적 장면. 한 번의 실패가 성숙으로 이어졌음을 행동으로 증명하라."},{"title":"용서와 화해의 재결합","synopsis":"서로의 옛 잘못을 용서하고 다시 받아들이는 장면. 첫사랑 때와는 다른, 상처를 알기에 더 단단해진 사랑의 결을 묘사하라."},{"title":"에필로그 — 못다 한 미래","synopsis":"과거에 함께 그렸으나 이루지 못했던 미래를 마침내 실현하는 장면(그때 못 간 여행·미룬 결혼). 두 번째 기회가 완성됐음을 상징적으로 보여줘라."}]}]},{"id":"g5-forbidden-love-melo","category":"로맨스","name":"금지된 사랑 멜로 (장벽을 사이에 둔 비극적 로맨스)","desc":"신분·가문·직업윤리·도덕·사회적 금기 등 넘기 힘든 장벽을 사이에 둔 사랑. 사랑할수록 더 위험해지는 구조로, 비장미와 절절함이 핵심 정서. 비극으로 치닫는 정통 멜로형과, 끝내 장벽을 부수는 극복형 두 갈래로 변주된다. '닿을 수 없기에 더 간절한' 감정을 판다.","beats":[{"title":"1막 — 넘지 말아야 할 선","synopsis":"사랑하면 안 되는 두 사람과 그들을 가르는 장벽이 제시되는 단계. 금기를 명확히 세운다.","folder":true,"children":[{"title":"운명적 끌림과 금기의 존재","synopsis":"강하게 끌리는 두 사람을 보여주되, 동시에 둘을 갈라놓는 절대적 장벽(신분·가문 원수·직업 윤리·기혼 등)을 명확히 제시하라. 끌림과 금기가 한 장면에 공존하게."},{"title":"선을 의식하며 멀어지기","synopsis":"이성적으로 '안 된다'며 거리를 두려는 장면. 끌릴수록 더 강하게 자제하는 내적 갈등을 그려, 금기의 무게를 독자에게 각인시켜라."},{"title":"거부할 수 없는 재근접","synopsis":"멀어지려 해도 운명처럼 다시 가까워지는 장면. 의지로 막을 수 없는 감정의 인력을 보여줘 '이미 늦었다'는 비장한 예감을 심어라."}]},{"title":"2막 — 위험한 사랑의 탐닉","synopsis":"금기를 알면서도 사랑에 빠져, 비밀스럽고 위태로운 행복을 누리는 단계. 들킬 위험이 점점 조여온다.","folder":true,"children":[{"title":"비밀의 밀회","synopsis":"남들 몰래 만나는 은밀하고 달콤한 장면들. 들킬까 조마조마한 긴장과 짧은 행복의 대비로, 위험할수록 더 강렬한 감정을 연출하라."},{"title":"장벽의 압박 가시화","synopsis":"장벽이 구체적 위협으로 다가오는 장면(가문의 감시·소문·직업적 위기). 행복의 대가가 점점 커지고 있음을 독자가 체감하게 하라."},{"title":"선택의 기로 예고","synopsis":"사랑을 지키려면 모든 것(가문·지위·신념)을 잃어야 하는 양자택일이 다가옴을 예고하는 장면. 곧 닥칠 비극적 결단의 무게를 깔아라."}]},{"title":"3막 — 파국 (대가의 청구)","synopsis":"비밀이 폭로되고 장벽이 전면적으로 두 사람을 덮쳐, 사랑과 모든 것을 잃을 위기에 몰리는 최악의 국면.","folder":true,"children":[{"title":"폭로와 단죄","synopsis":"관계가 만천하에 드러나 사회·가문·조직의 단죄가 쏟아지는 장면. 두 사람이 치러야 할 혹독한 대가를 적나라하게 보여줘라."},{"title":"강요된 이별","synopsis":"외압에 의해 강제로 갈라서거나, 상대를 지키려 한쪽이 스스로 떠나는 비극의 정점. 사랑하기에 놓아야 하는 절절한 희생을 그려라."},{"title":"잃은 자리의 공허","synopsis":"헤어진 뒤 각자 무너지는 모습을 교차로 보여주는 장면. 장벽을 지켰지만 영혼은 이미 죽은 듯한 공허로 독자의 가슴을 후벼라."}]},{"title":"4막 — 장벽 너머의 선택","synopsis":"비극으로 마무리되거나(정통 멜로), 마침내 장벽을 부수고 사랑을 쟁취하거나(극복형) — 작품 톤에 따라 결말을 선택한다.","folder":true,"children":[{"title":"모든 것을 건 결단","synopsis":"사랑을 위해 가진 모든 것을 포기하거나, 목숨을 건 위험을 감수하는 결정적 선택의 장면. 비극형이든 극복형이든 이 결단이 결말의 무게를 결정한다."},{"title":"장벽의 붕괴 또는 운명의 완성","synopsis":"극복형이면 장벽이 무너지고 둘이 결합하는 카타르시스를, 비극형이면 닿지 못한 채 운명이 완성되는 처연한 마지막을 그려라. 톤에 맞춰 한쪽을 택한다."},{"title":"에필로그 — 사랑의 증명","synopsis":"세월 뒤에도 그 사랑이 헛되지 않았음을 보여주는 장면(함께한 미래 또는 남겨진 사람의 기억). 금기를 넘은 사랑의 의미를 한 컷으로 못 박아 여운을 남겨라."}]}]},{"id":"g5-rom-com-meet-cute","category":"로맨스","name":"로맨틱 코미디 (밋큐트·소동·해프닝)","desc":"유쾌한 우연과 오해, 좌충우돌 소동을 동력으로 두 사람이 티격태격하다 사랑에 빠지는 경쾌한 구조. 밋큐트(귀여운 첫 만남)·신분 오해·뒤바뀐 정체·거짓말이 눈덩이처럼 커지는 코믹 갈등이 핵심. 무게보다 리듬과 위트, 사랑스러운 캐릭터의 매력으로 승부한다.","beats":[{"title":"1막 — 밋큐트와 엉킨 첫 단추","synopsis":"황당하고 귀여운 첫 만남, 그리고 작은 오해나 거짓말로 관계가 비틀리며 시작되는 단계.","folder":true,"children":[{"title":"황당한 첫 만남(밋큐트)","synopsis":"예상 못한 사고·우연으로 둘이 엮이는 코믹한 첫 장면(부딪힘·뒤바뀐 물건·민망한 상황). 첫인상부터 웃음과 티키타카가 터지게 설계하라."},{"title":"작은 거짓말·오해의 발단","synopsis":"체면·상황 모면을 위해 내뱉은 작은 거짓말이나 신분 오해가 생기는 장면. 나중에 눈덩이처럼 커질 '코믹 폭탄'의 도화선을 심어라."},{"title":"다시 엮이는 불운","synopsis":"피하고 싶은 상대와 계속 마주치게 되는 코믹한 우연을 반복한다. 운명의 장난처럼 자꾸 부딪혀 '인연이네' 싶은 웃음을 만들어라."}]},{"title":"2막 — 좌충우돌 가까워지기","synopsis":"티격태격 소동을 함께 헤쳐 나가며, 미운 정 고운 정으로 어느새 가까워지는 단계.","folder":true,"children":[{"title":"강제 협력 소동","synopsis":"둘이 어쩔 수 없이 한 팀이 되는 소동(같은 임무·내기·곤란한 상황 수습). 옥신각신하면서도 손발이 척척 맞는 의외의 케미를 코믹하게 보여줘라."},{"title":"거짓말이 키운 눈덩이","synopsis":"1막의 작은 거짓말이 점점 커져 더 큰 거짓말로 막아야 하는 코믹 위기 장면. 들킬 듯 말 듯한 아슬아슬함으로 웃음과 긴장을 동시에 줘라."},{"title":"문득 설레는 순간","synopsis":"웃고 떠들다 문득 분위기가 묘해지는 장면. 코미디 한가운데 진짜 설렘이 끼어드는 순간을 배치해, 가벼움 속 진심의 싹을 틔워라."}]},{"title":"3막 — 거짓말의 폭로와 대형 사고","synopsis":"그동안 쌓인 거짓말·오해가 한꺼번에 터지며 관계가 와르르 무너지는, 로코식 블랙 모먼트.","folder":true,"children":[{"title":"최악의 타이밍 폭로","synopsis":"거짓말·정체가 가장 안 좋은 순간(중요한 자리·진심 고백 직전)에 들통나는 장면. 코믹하게 쌓아온 모든 것이 한순간에 와르르 무너지게 하라."},{"title":"배신감과 결별","synopsis":"속았다는 상처로 상대가 등을 돌리는 장면. 가벼운 톤을 유지하면서도 진짜 아픈 감정을 한 번은 깊게 찔러 무게중심을 잡아라."},{"title":"혼자 남아 깨닫는 진심","synopsis":"각자 떨어져 후회하는 장면. 소동이 없는 조용한 일상이 얼마나 허전한지 대비시켜, 그 사람이 진짜였음을 자각하게 하라."}]},{"title":"4막 — 사랑스러운 대단원","synopsis":"엉킨 거짓말을 풀고 진심으로 다가가, 모두가 흐뭇해지는 코믹하고 따뜻한 해피엔딩.","folder":true,"children":[{"title":"체면 던진 그랜드 제스처","synopsis":"주인공이 망신을 무릅쓰고 벌이는 사랑스럽고 떠들썩한 고백 이벤트(공개 추격·대형 사고급 이벤트). 로코다운 과감하고 유쾌한 클라이맥스를 연출하라."},{"title":"웃음 속 진심 고백","synopsis":"그동안의 코믹한 거짓말을 다 인정하고 진심만 남기는 고백 장면. 1막의 밋큐트 상황을 위트 있게 재활용하면 웃음과 감동을 동시에 잡는다."},{"title":"에필로그 — 여전히 소란스러운 행복","synopsis":"맺어진 뒤에도 여전히 티격태격하지만 행복한 일상을 보여줘라. 변치 않은 케미와 유쾌함으로 끝까지 미소 짓게 하며 마무리한다."}]}]},{"id":"g6-regression-revenge-romance","category":"로맨스판타지","name":"회귀 복수-구원형","desc":"비참하게 죽거나 버림받은 여주가 과거로 회귀해, 전생의 비극을 막으며 진짜 인연을 다시 선택하는 구조. 로판 웹소설 최대 주류 중 하나로, '두 번째 인생'의 정보 우위와 통쾌한 단죄, 그리고 전생에 놓쳤던 남주와의 재회가 핵심 쾌감이다.","beats":[{"title":"1막 — 파국과 회귀","synopsis":"전생의 파멸을 강렬하게 각인시키고, 회귀라는 두 번째 기회를 부여하는 단계.","folder":true,"children":[{"title":"전생의 마지막 순간","synopsis":"처형대·독배·버림받은 임종 등 여주가 가장 비참한 순간을 1인칭 회한으로 연다. 누가 배신했는지, 무엇을 후회하는지 구체적 이름과 장면으로 박아 독자에게 복수 동기를 선물한다."},{"title":"눈을 뜨니 과거","synopsis":"데뷔탕트 직전·약혼 전·입궁 첫날 등 '모든 게 어긋나기 직전'으로 회귀. 손의 흉터, 어린 동생, 살아있는 가족 등 시점 단서로 회귀를 확정하고 여주의 차가운 결심을 드러낸다."},{"title":"달라진 첫 선택","synopsis":"전생엔 순순히 따랐던 결정을 정반대로 뒤집는 첫 장면. 약혼 거절, 가문 재산 빼돌리기 방어, 독초 알아보기 등 정보 우위를 활용한 '사이다' 한 컷으로 변화를 증명한다."}]},{"title":"2막 — 판 갈아엎기","synopsis":"전생 지식으로 적의 수를 미리 막고 자기 기반을 다지며, 진짜 남주를 재평가하는 단계.","folder":true,"children":[{"title":"미래를 아는 자의 포석","synopsis":"곧 일어날 사건(역병·반란·파혼·사업 실패)을 선제 대응. 예언처럼 들어맞는 여주의 판단에 주변이 경악하고, 여주는 돈·정보·인맥이라는 자기 권력을 축적한다."},{"title":"전생 가해자와의 재대면","synopsis":"전생에 자신을 죽인 약혼자·계모·언니 등과 다시 마주치되, 이번엔 미소 뒤에 칼을 숨긴다. 겉으론 우아하게, 속으론 함정을 까는 이중 연기의 긴장감을 묘사한다."},{"title":"오해했던 남주 재발견","synopsis":"전생엔 무섭거나 무관심하다 오해했던 남주의 진짜 의도·상처를 알게 되는 전환. 그가 전생에도 자신을 지키려 했음을 암시하는 사소한 행동(대신 맞은 칼, 숨겨준 도주로)을 배치한다."},{"title":"흔들리는 마음과 거리두기","synopsis":"또 상처받을까 두려워 일부러 남주를 밀어내는 여주. 자기 보호 본능과 끌림 사이의 내적 갈등을 통해 로맨스 텐션을 끌어올린다."}]},{"title":"3막 — 단죄와 위기","synopsis":"전생 악인을 무너뜨리는 통쾌함과, 회귀를 비튼 변수로 인한 최대 위기가 겹치는 단계.","folder":true,"children":[{"title":"복수의 완성","synopsis":"축적한 증거·권력으로 가해자를 사회적·법적으로 파멸시키는 클라이맥스. 전생의 처형 구도를 거울처럼 뒤집어(이번엔 그들이 처벌받게) 카타르시스를 극대화한다."},{"title":"회귀가 만든 새 변수","synopsis":"여주가 미래를 바꾼 탓에 전생엔 없던 위협(살아남은 적, 분기점이 어긋난 사건)이 등장. 정보 우위가 더는 통하지 않는 진짜 위기로 긴장을 재점화한다."},{"title":"남주의 진심 고백·희생","synopsis":"위기 한가운데서 남주가 목숨을 걸고 여주를 구하며 마음을 드러낸다. 두 번째 생에서 비로소 여주가 자기 의지로 남주를 선택하는 감정의 정점."}]},{"title":"4막 — 다시 쓴 결말","synopsis":"전생과 정반대의 해피엔딩으로 두 번째 인생의 의미를 봉인하는 단계.","folder":true,"children":[{"title":"전생 비극의 반전 재현","synopsis":"전생에 죽었던 그 장소·날짜를 이번엔 행복의 순간으로 덮어쓰는 미러링 장면. 독자에게 '이번 생은 다르다'는 정서적 보상을 확실히 준다."},{"title":"회귀의 비밀과 화해","synopsis":"회귀 사실을 남주(혹은 핵심 조력자)에게 털어놓거나, 굳이 말하지 않아도 통하는 신뢰를 확인. 과거의 자신과 화해하며 회한을 내려놓는다."},{"title":"새로운 일상의 약속","synopsis":"결혼·즉위·가문 재건 등 안정된 미래를 보여주는 에필로그. 다음 세대나 못다 푼 떡밥을 가볍게 남겨 여운을 준다."}]}]},{"id":"g6-villainess-bookreincarnation","category":"로맨스판타지","name":"빙의 악역영애 생존형","desc":"읽던 소설·게임 속 '파멸 예정 악역 영애'로 빙의·환생한 주인공이, 원작 지식으로 죽음 플래그를 부수고 살아남으려다 도리어 모두의 호감을 사는 구조. 로판 빙의물의 대표격으로, 메타적 원작 비틀기와 '오해형 호감 폭발'이 핵심 재미다.","beats":[{"title":"1막 — 빙의와 사형선고","synopsis":"현대인이 악역 영애 몸에 들어와 자신의 파멸 결말을 자각하는 단계.","folder":true,"children":[{"title":"정신차려보니 악역","synopsis":"거울 속 낯선 얼굴, 익숙한 이름으로 빙의를 자각하는 오프닝. 자신이 읽던/하던 작품의 '그 악역'임을 깨닫는 순간의 멘붕과 메타 코멘트를 살린다."},{"title":"원작 결말 복기","synopsis":"이 캐릭터가 어떻게 파멸하는지(파혼·추방·처형·몰락) 원작 줄거리를 정리해 보여준다. 데드 플래그의 구체적 조건과 데드라인을 명확히 해 생존 목표를 세운다."},{"title":"생존 전략 선언","synopsis":"'주인공(여주)·공략남에게 절대 얽히지 않고 조용히 산다'는 1차 목표 수립. 악행을 멈추고 시골 영지로 빠지거나 약혼 파기를 노리는 등 회피 전략을 코믹하게 짠다."}]},{"title":"2막 — 플래그 부수기의 역효과","synopsis":"악행을 멈춘 선의가 원작에 없던 호감으로 돌아와, 조용히 살려는 계획이 어긋나는 단계.","folder":true,"children":[{"title":"착해진 악역의 나비효과","synopsis":"괴롭히지 않고 베푼 작은 친절이 하인·기사·동생에게 강렬한 충성으로 돌아온다. 원작과 달라진 평판으로 주변 인물들의 태도가 미묘하게 변하기 시작한다."},{"title":"공략남의 예상 밖 접근","synopsis":"여주에게 가야 할 남주(황태자·기사단장·마탑주)가 변화한 영애에게 흥미를 느낀다. 피하려는 영애와 끌리는 남주의 엇갈린 추격전으로 텐션을 만든다."},{"title":"원작 주인공과의 조우","synopsis":"진짜 여주인공을 마주치는 장면. 적대하지 않고 오히려 도와주려다 우정·동맹이 싹트거나, 반대로 원작과 다른 여주의 본색이 드러나며 구도가 뒤틀린다."},{"title":"숨겨둔 능력·매력 노출","synopsis":"전생 지식·현대 감각·잠든 마력 등이 우연히 드러나며 '평범하지 않은 영애'로 주목받는다. 본인은 들킨 줄도 모르고 태연한 갭이 호감을 증폭시킨다."}]},{"title":"3막 — 원작 균열과 정체 위기","synopsis":"바뀐 행동들이 원작 사건의 톱니를 어긋내며, 빙의자의 정체나 진짜 위협이 드러나는 단계.","folder":true,"children":[{"title":"원작 강제력의 반격","synopsis":"아무리 피해도 원래 일어날 핵심 사건(연회 추문·전쟁·암살)이 형태를 바꿔 닥쳐온다. '운명을 거스를 수 있나'라는 긴장으로 절정 직전을 조인다."},{"title":"빙의/이질감 발각 위기","synopsis":"달라진 말투·지식 탓에 누군가 영애의 정체를 의심한다. 남주가 '너는 내가 알던 그 사람이 아니'라며 추궁하거나 보호하려는 선택의 순간을 만든다."},{"title":"진짜 흑막 등장","synopsis":"원작에선 비중 없던 진짜 악(저주·신·배후 가문)이 부상하며, 영애의 파멸이 사실은 더 큰 음모의 일부였음을 폭로한다."}]},{"title":"4막 — 데드 플래그 무효화","synopsis":"정해진 파멸을 완전히 뒤집고, 빙의자가 이 세계의 진짜 주인공으로 자리 잡는 단계.","folder":true,"children":[{"title":"파멸의 날 정면돌파","synopsis":"원작 처형·추방의 그 무대에서, 쌓아둔 동맹과 능력으로 결말을 뒤엎는 클라이맥스. 악역의 단죄가 아니라 악역의 구원이라는 반전 카타르시스를 친다."},{"title":"남주와의 관계 확정","synopsis":"원작 커플링을 깨고 영애-남주의 사랑을 공식화. '책 속 인물'이 아닌 진짜 사람으로 서로를 선택했음을 확인하는 감정의 정점."},{"title":"내 이야기로의 결말","synopsis":"더는 원작 줄거리에 종속되지 않는 새 미래를 보여주는 에필로그. 빙의 사실을 받아들이고 이 세계를 자기 삶으로 끌어안는 마무리."}]}]},{"id":"g6-contract-marriage-political","category":"로맨스판타지","name":"계약결혼 궁중정치형","desc":"정략·계약·위장으로 시작한 결혼이 권력 암투 속에서 진짜 사랑으로 변하는 구조. 황후·공작부인물의 정통 라인으로, 신뢰 없는 두 사람이 외부의 적과 맞서며 동맹에서 연인으로 진화하는 '슬로우번 + 권력게임'이 핵심이다.","beats":[{"title":"1막 — 거래로 맺은 인연","synopsis":"사랑 없는 조건부 결혼의 성립과 두 사람의 동상이몽을 세팅하는 단계.","folder":true,"children":[{"title":"벼랑 끝의 제안","synopsis":"몰락 위기의 여주(빚·정적·가문 붕괴)에게 권력자 남주가 계약결혼을 제안. 서로의 이해관계와 '절대 사랑하지 않는다'는 차가운 조건을 명문화한다."},{"title":"계약서의 조항들","synopsis":"기간·별거·후계·이혼 조건 등 구체적 계약 조항을 보여주며 관계의 룰을 설정. 이 조항들이 후반에 발목을 잡거나 깨질 복선으로 깔린다."},{"title":"낯선 부부의 첫날","synopsis":"거대한 저택·궁에 입성한 여주가 적대적인 가신·전처의 그림자·차가운 남주를 마주한다. 위장 부부 연기와 진짜 거리감의 어색한 긴장을 그린다."}]},{"title":"2막 — 적 앞의 공동전선","synopsis":"외부 위협에 맞서 협력하며 계약 관계에 신뢰와 끌림이 스며드는 단계.","folder":true,"children":[{"title":"공동의 적 출현","synopsis":"정적·황실 파벌·암살 위협 등 부부를 동시에 노리는 적이 등장. 살아남으려면 진짜로 손을 잡아야 하는 상황으로 둘을 묶는다."},{"title":"사교계·궁정의 칼날","synopsis":"연회·티타임·무도회를 무대로 한 정보전과 기싸움. 여주의 기지로 위기를 넘기고, 남주가 의외의 순간 그를 감싸며 동맹의 균열을 메운다."},{"title":"선 넘는 순간들","synopsis":"다친 상대를 간호하거나, 위장 키스가 진심이 되는 등 계약을 넘는 접촉이 쌓인다. '이건 연기일 뿐'이라 되뇌는 자기기만으로 슬로우번을 가열한다."},{"title":"과거의 상처 공유","synopsis":"남주의 냉정함 뒤에 숨은 트라우마(배신·전쟁·전처)와 여주의 결핍이 드러나며 정서적 유대가 깊어진다. 서로가 서로를 이해하는 첫 진심의 대화를 배치한다."}]},{"title":"3막 — 신뢰의 시험","synopsis":"오해·외부 음모·계약 조항이 충돌해 막 싹튼 사랑이 최대 시험에 드는 단계.","folder":true,"children":[{"title":"이간질과 오해","synopsis":"적이 흘린 거짓 정보·과거 연인 등장·계약의 진실 폭로로 두 사람 사이가 틀어진다. '결국 거래였을 뿐'이라는 의심이 관계를 흔든다."},{"title":"권력 게임의 절정","synopsis":"반역·즉위·암살 시도 등 정치 음모가 클라이맥스로 터진다. 여주가 독자적 판단으로 판을 뒤집으며 자신의 능력과 결단을 증명한다."},{"title":"계약 파기의 기로","synopsis":"계약 종료·이혼 조건이 발동될 순간, 둘 중 하나가 관계를 끝낼지 붙잡을지 선택해야 한다. 사랑을 인정할 것인가의 정면 대결로 감정을 최고조로."}]},{"title":"4막 — 거래를 넘어선 사랑","synopsis":"계약을 무효화하고 자발적 사랑으로 관계를 재정의하는 단계.","folder":true,"children":[{"title":"진심의 선택","synopsis":"위기를 넘긴 뒤 한쪽이 먼저 '계약이 아니라 너를 원한다'고 고백. 조항이 아닌 마음으로 함께하기를 택하는 감정의 정점을 그린다."},{"title":"권력의 안정","synopsis":"정적 제거·즉위·작위 안정 등 외부 위협을 정리하고 부부가 공동 권력으로 우뚝 선다. 동등한 파트너로서의 위상을 확정한다."},{"title":"찢어버린 계약서","synopsis":"처음의 차가운 계약서를 상징적으로 폐기·재서약하는 에필로그. 거래로 시작해 사랑으로 끝난 관계의 완성을 봉인한다."}]}]},{"id":"g6-academy-growth-romance","category":"로맨스판타지","name":"아카데미 성장-군상형","desc":"마법·기사 아카데미를 무대로, 미천하거나 숨은 신분의 주인공이 입학-경쟁-사건을 거쳐 성장하며 여러 매력적 인물과 얽히는 구조. 학원물 특유의 또래 군상극, 라이벌·동료·다수 호감 캐릭터, 단계적 시험을 통한 성장 서사가 핵심이다.","beats":[{"title":"1막 — 입학과 낙인","synopsis":"주인공이 아카데미에 들어가 자신의 위치와 비밀, 첫 인연을 세팅하는 단계.","folder":true,"children":[{"title":"특별한 입학","synopsis":"장학생·편입·신분 위장 등 남다른 사연으로 입학하는 주인공. 숨겨야 할 비밀(신분·능력·과거)과 입학의 진짜 목적을 독자에게만 살짝 보여준다."},{"title":"첫인상과 낙인","synopsis":"출신·소문 탓에 무시·견제당하는 첫날. 동시에 강렬한 첫 만남의 상대(까칠한 천재·다정한 선배·냉정한 교관)와 부딪히며 관계의 씨앗을 뿌린다."},{"title":"숨은 재능의 첫 발현","synopsis":"배치고사·첫 실습에서 예상 밖 능력이 드러나며 주목받는다. '평범한 줄 알았던 아이'의 반전으로 라이벌과 호감 캐릭터들의 시선을 동시에 끈다."}]},{"title":"2막 — 경쟁과 우정","synopsis":"수업·결투·팀 과제를 거치며 실력을 키우고 또래 군상과의 관계망을 짜는 단계.","folder":true,"children":[{"title":"라이벌 구도 형성","synopsis":"실력으로 부딪히는 라이벌과의 경쟁이 본격화. 적대에서 인정으로, 혹은 라이벌이 호감 대상으로 변해가는 관계의 결을 깔아둔다."},{"title":"동료와 팀 결성","synopsis":"기숙사·조별 과제·서클을 통해 든든한 동료들을 모은다. 각기 다른 매력의 군상 캐릭터를 입체적으로 소개하고 우정의 기반을 다진다."},{"title":"단계적 시험 돌파","synopsis":"토너먼트·던전 실습·자격시험 등 가시적 관문을 통과하며 성장을 증명. 매 시험마다 한 단계씩 강해지는 RPG식 성취감을 준다."},{"title":"감정선의 교차","synopsis":"함께 위기를 넘기며 특정 인물과의 거리가 좁혀진다. 여러 호감 캐릭터 사이에서 주인공의 마음이 한쪽으로 기울기 시작하는 미묘한 전환점."}]},{"title":"3막 — 비밀과 사건","synopsis":"아카데미를 위협하는 큰 사건이 터지고 주인공의 숨은 정체가 흔들리는 단계.","folder":true,"children":[{"title":"교내를 흔든 사건","synopsis":"마수 침입·금기 마법·학생 실종 등 학원 전체를 위협하는 사건 발생. 평화롭던 일상이 깨지고 주인공 일행이 진상에 휘말린다."},{"title":"정체의 폭로 위기","synopsis":"위기 대응 중 숨겨온 신분·능력·목적이 드러날 위기에 처한다. 신뢰하던 동료·연심 상대에게 비밀을 들킬지 말지의 긴장으로 관계를 시험한다."},{"title":"성장의 시련","synopsis":"실력과 의지의 한계를 넘어야 하는 절체절명의 순간. 동료의 도움과 각성으로 한계를 돌파하며 진정한 실력자로 거듭난다."}]},{"title":"4막 — 졸업과 선택","synopsis":"사건을 해결하고 성장을 완성하며 관계와 진로를 매듭짓는 단계.","folder":true,"children":[{"title":"사건의 해결","synopsis":"배후를 밝히고 위협을 물리치는 클라이맥스. 주인공이 입학 때의 목적을 이루거나, 더 큰 진실에 한 걸음 다가서며 성장을 입증한다."},{"title":"마음의 확정","synopsis":"흔들리던 감정선을 정리해 한 사람을 향한 사랑을 확정. 군상 속에서 선택한 인연과의 결정적 고백·확인 장면을 배치한다."},{"title":"새로운 출발","synopsis":"졸업·임관·차기 무대로의 진출을 보여주는 에필로그. 아카데미를 넘어선 더 넓은 세계와 다음 이야기의 가능성을 열어둔다."}]}]},{"id":"g6-fated-mate-curse","category":"로맨스판타지","name":"운명의 짝 저주-해주형","desc":"신탁·각인·저주로 운명적으로 묶인 두 존재(용/신수/마수/이종족 남주와 인간 여주 등)가, 거부와 끌림을 오가며 저주의 비밀을 풀고 운명을 받아들이는 구조. 이종족·신화 로판의 대표 라인으로, '거부할 수 없는 끌림'과 '저주의 대가'라는 비극성·관능성이 핵심이다.","beats":[{"title":"1막 — 운명의 각인","synopsis":"두 존재가 운명·저주로 강제로 엮이며 거부 속에서도 끌림이 시작되는 단계.","folder":true,"children":[{"title":"이종족과의 조우","synopsis":"용·신수·마왕·정령 등 인간 아닌 남주와 여주의 운명적 첫 만남. 제물·계약·우연한 구원 등 신화적 설정으로 둘을 한 공간에 묶는다."},{"title":"각인·신탁의 발동","synopsis":"예언·표식·각인이 발현되며 '운명의 짝'임이 선언된다. 둘 다 원치 않지만 거부할 수 없는 끌림과, 떨어지면 고통받는 등의 강제력을 설정한다."},{"title":"저주의 제시","synopsis":"이 운명에 걸린 저주·대가(수명·기억·생명·이성 상실)를 명확히 드러낸다. 운명을 받아들이면 무엇을 잃는지 보여주며 비극적 긴장을 깐다."}]},{"title":"2막 — 거부와 끌림","synopsis":"운명을 거부하려는 의지와 본능적 끌림이 충돌하며 서로를 알아가는 단계.","folder":true,"children":[{"title":"운명에 대한 저항","synopsis":"강요된 인연을 거부하고 도망·반항하는 여주(혹은 남주). 자유의지와 운명의 대립을 통해 '선택해서 사랑하고 싶다'는 욕망을 부각한다."},{"title":"본능을 거스를 수 없는 순간","synopsis":"위험·발정기·각인 폭주 등으로 끌림이 폭발하는 장면. 이성과 본능의 줄다리기로 관능적·정서적 텐션을 동시에 끌어올린다."},{"title":"이종족의 세계와 비밀","synopsis":"남주 종족의 문화·역사·금기를 알아가며 저주의 기원에 다가선다. 이질적 세계관을 통해 두 존재가 왜 묶였는지 단서를 흩뿌린다."},{"title":"마음의 빗장 풀림","synopsis":"서로의 외로움·결핍을 알아보며 운명이 아닌 '사람으로서' 끌리기 시작한다. 거부하던 마음이 진심으로 기우는 정서적 전환점."}]},{"title":"3막 — 저주의 대가","synopsis":"저주를 풀려는 시도가 희생을 요구하며, 운명을 위협하는 외부의 적과 충돌하는 단계.","folder":true,"children":[{"title":"저주의 근원 추적","synopsis":"저주를 건 신·마녀·옛 비극의 진실을 파헤친다. 해주의 조건이 잔혹한 대가(둘 중 하나의 희생)를 전제함을 알게 되는 절망의 발견."},{"title":"운명을 노리는 적","synopsis":"두 존재의 결합을 막거나 그 힘을 탐하는 세력(신전·다른 종족·옛 약혼자)이 공격한다. 운명의 짝이라는 사실이 표적이 되어 위기로 치닫는다."},{"title":"희생의 기로","synopsis":"저주를 풀기 위해 한쪽이 목숨·기억·힘을 내놓으려 한다. 상대를 살리기 위한 자기희생의 결단으로 비극성을 절정으로 끌어올린다."}]},{"title":"4막 — 운명을 다시 쓰다","synopsis":"강요된 운명을 자유의지로 재정의하며 저주를 넘어선 결합을 완성하는 단계.","folder":true,"children":[{"title":"저주의 해방","synopsis":"희생이 아닌 제3의 길(진정한 사랑의 증명·운명의 재계약·신과의 담판)로 저주를 깨는 클라이맥스. 비극을 뒤집는 반전으로 카타르시스를 친다."},{"title":"선택으로서의 운명","synopsis":"강요된 각인이 아니라 '내가 너를 택한다'는 자발적 서약으로 관계를 재정의. 운명을 거부가 아닌 선택으로 끌어안는 감정의 정점."},{"title":"이어진 두 세계","synopsis":"인간과 이종족, 두 세계가 화해하고 함께하는 미래를 보여주는 에필로그. 운명의 짝으로서 새 시대를 여는 여운 있는 마무리."}]}]},{"id":"g7-haunted-house-escalation","category":"호러·공포","name":"흉가·장소 빙의형 (점진적 침식)","desc":"고립된 집/건물 자체가 적대자가 되는 고전 하우스 호러. 평범한 일상이 사소한 이상 징후에서 시작해 부정·합리화·집착·붕괴의 곡선을 그리며, '왜 떠나지 않는가'라는 함정에 인물을 가둔다. 셜리 잭슨 '힐 하우스의 유령', 킹 '샤이닝', 영화 '디 아더스'·'컨저링' 계열의 결.","beats":[{"title":"1막 — 이주와 거짓 안식","synopsis":"새 보금자리에 대한 희망과 안도가 공포의 대비를 만드는 단계. 인물의 결핍(빚·이혼·트라우마)이 '떠날 수 없는 이유'로 심어진다.","folder":true,"children":[{"title":"도피로서의 입주","synopsis":"주인공이 과거의 상처나 경제적 궁지에서 벗어나려 그 집을 선택하는 장면. 집의 시세가 비정상적으로 싼 이유, 전 주인의 행방을 가볍게 흘려 복선화하라. 이 결핍이 후반 '왜 안 떠나냐'의 봉인장치다."},{"title":"집의 첫 인상과 인물 배치","synopsis":"공간 구조(잠긴 방, 지하실, 다락, 닫히지 않는 문)를 독자에게 지도처럼 각인시키는 답사 장면. 나중에 무엇이 어디서 나올지 기대치를 깔아라. 가족 구성원 각자의 약점도 이때 분배한다."},{"title":"최초의 위화감 (해석 가능한 이상)","synopsis":"발소리·냉기·옮겨진 물건 등 '착각일 수도 있는' 1차 징후. 반드시 합리적 설명(낡은 배관, 외풍, 피로)이 동시에 제시되어 인물이 부정할 여지를 남겨야 한다."}]},{"title":"2막 — 부정과 균열","synopsis":"이상 현상의 빈도·강도가 올라가지만 인물들은 서로를 의심하거나 자신을 의심한다. 외부 세계와의 단절이 강화되는 구간.","folder":true,"children":[{"title":"한 사람만 본다 / 믿어주지 않는다","synopsis":"가장 취약한 인물(아이·아내·정신과 병력자)이 먼저 표적이 되고 다른 가족은 망상으로 치부하는 장면. 집안 내부에 불신의 균열을 만들어 공동 대응을 불가능하게 하라."},{"title":"집의 역사 발굴","synopsis":"장롱·지하·도서관·이웃 노인을 통해 과거의 죽음/저주/매장지를 캐내는 조사 비트. 정보를 한 번에 주지 말고 조각으로 흘려 '집이 무엇을 원하는가'를 서서히 그려라."},{"title":"안전지대의 오염","synopsis":"침실·욕실·아이 방 등 가장 사적이고 안전해야 할 공간이 침범당하는 장면. 독자의 일상 감각을 무기로 삼아 '도망갈 곳이 없다'는 폐소감을 심어라."},{"title":"탈출 시도의 좌절","synopsis":"떠나려는 결심이 사고·재정·날씨·집의 개입으로 무산되는 비트. 고립이 물리적 사실로 굳어지고, 이 집과의 운명이 봉인된다."}]},{"title":"3막 — 빙의와 진실","synopsis":"집의 의지가 인물(특히 가장 약하거나 가장 강한 자)을 매개로 발현. 누가 산 자이고 죽은 자인지, 무엇이 진짜였는지 뒤집힌다.","folder":true,"children":[{"title":"내부의 적 — 인물의 변질","synopsis":"한 가족이 집에 동화되어 다른 가족을 위협하는 전환점. '샤이닝'식으로 보호자가 가해자가 되는 배신의 공포를 그려라. 변화의 징후는 앞서 깔아둔 약점에서 자라야 한다."},{"title":"진실의 폭로 (왜 이 집인가)","synopsis":"저주의 기원·전 주인의 운명이 주인공의 처지와 거울처럼 겹친다는 사실을 드러내는 장면. 공포를 단순 사건이 아닌 주제(죄책감·상실·반복)로 승격시켜라."},{"title":"마지막 대치와 대가","synopsis":"탈출 또는 퇴치를 시도하며 희생을 치르는 클라이맥스. 완전한 승리보다 상실을 동반한 생존이 호러의 결에 맞는다."}]},{"title":"에필로그 — 닫히지 않는 문","synopsis":"집은 다음 희생자를 기다린다는 순환 암시. 안도와 불안의 잔향을 동시에 남긴다.","folder":true,"children":[{"title":"표면적 평온","synopsis":"살아남은 자의 일상 복귀나 집의 매각/철거 장면. 모든 게 끝난 듯한 안도를 의도적으로 연출하라."},{"title":"재가동의 징조","synopsis":"새 입주자·이사 트럭·동일한 이상 징후 한 컷으로 순환을 암시. 첫 장면과 운율을 맞춰 '집은 죽지 않는다'를 각인시켜라."}]}]},{"id":"g7-survival-slasher-countdown","category":"호러·공포","name":"서바이벌 슬래셔형 (인원 감소 카운트다운)","desc":"고립된 집단이 정체불명/규칙적인 살해자에게 하나씩 제거되며 '최후의 생존자'가 추려지는 구조. 카펜터 '할로윈', 크레이븐 '나이트메어'·'스크림', 캠프/오두막 슬래셔의 결. 사망 순서·규칙·파이널 걸 관습을 활용하되 메타적으로 비틀 수 있다.","beats":[{"title":"1막 — 집결과 금기","synopsis":"희생자 후보군이 고립된 무대에 모인다. 과거의 죄·전설·경고가 살해의 정당성과 규칙을 세팅한다.","folder":true,"children":[{"title":"고립 무대로의 진입","synopsis":"오두막·캠프·외딴 도로·폐교 등 외부 도움이 차단되는 장소로 집단이 이동하는 장면. 통신 두절·차량 고장 등 퇴로 차단 장치를 자연스럽게 심어라."},{"title":"전설·경고·과거의 죄","synopsis":"현지인이나 표지판이 전하는 금기와 과거 참극의 유래를 제시. 살해자의 동기와 '왜 이들인가'의 연결고리를 복선으로 깔아라."},{"title":"캐릭터 유형 분배와 역할","synopsis":"순결한 파이널 걸 후보, 방종한 커플, 회의론자, 광대 등 군상을 빠르게 각인시키는 장면. 관객이 사망 순서를 예측하게 하되 한둘은 의도적으로 배신할 여지를 둔다."}]},{"title":"2막 — 사냥의 개시","synopsis":"첫 살해로 게임이 시작되고, 집단은 위협을 인지하지 못하거나 흩어진다. 사망이 가속한다.","folder":true,"children":[{"title":"선제 살해 (규칙 공개)","synopsis":"첫 희생자가 무대 밖이나 변두리에서 제거되는 장면. 살해자의 수법·무기·시그니처(마스크, 소리)를 독자에게 학습시키되 전신은 아끼라."},{"title":"부재의 발견과 분열","synopsis":"사라진 동료를 두고 '장난이다 vs 위험하다'로 의견이 갈리는 장면. 집단을 흩어뜨려 1대1 사냥이 가능하도록 판을 짜라."},{"title":"연쇄 제거 시퀀스","synopsis":"방심·일탈·고립된 인물들이 차례로 당하는 중반 몰살 구간. 각 죽음에 개성(상황·아이러니·잔혹도)을 부여하고 긴장의 리듬을 조절하라."},{"title":"위협의 실체 인지","synopsis":"생존자들이 마침내 '쫓기고 있다'를 자각하고 공포가 패닉으로 전환되는 전환점. 시신 발견이나 직접 조우를 클라이맥스 직전 배치한다."}]},{"title":"3막 — 파이널 걸의 반격","synopsis":"최후의 생존자가 도망에서 맞섬으로 전환. 살해자의 정체와 동기가 드러나고 처절한 대결이 벌어진다.","folder":true,"children":[{"title":"정체와 동기의 폭로","synopsis":"마스크를 벗기거나 과거 사건과 연결해 살해자의 정체·동기를 드러내는 장면. '스크림'식 인간 범인이든 초자연이든 1막 복선을 회수하라."},{"title":"쫓김에서 맞섬으로","synopsis":"파이널 걸이 환경(함정·도구·지형)을 역이용해 반격을 준비하는 전환. 무력한 피해자가 능동적 생존자로 각성하는 캐릭터 호선을 완성하라."},{"title":"최후의 대결","synopsis":"일대일 사투의 클라이맥스. 한 번 쓰러뜨린 적이 다시 일어나는 '가짜 결말' 페이크를 적어도 한 번 넣어 긴장을 극대화하라."}]},{"title":"에필로그 — 죽지 않은 악","synopsis":"위협의 소멸이 확실하지 않음을 암시. 속편 가능성과 트라우마의 잔존을 남긴다.","folder":true,"children":[{"title":"사라진 시신","synopsis":"쓰러뜨린 살해자의 시체가 사라졌거나 눈을 뜨는 마지막 컷. 슬래셔 관습대로 악의 불멸성을 암시하라."},{"title":"생존자의 변질","synopsis":"살아남았지만 더 이상 예전이 아닌 파이널 걸의 모습. 생존의 대가로 치른 정신적 상흔을 짧게 각인시켜라."}]}]},{"id":"g7-cosmic-dread-unknowable","category":"호러·공포","name":"코스믹 호러형 (인지 불가의 진실)","desc":"러브크래프트 전통의 우주적 공포. 외딴 마을·고문서·금단의 탐구를 통해 인간이 우주에서 무의미한 존재임을 깨닫고 광기로 무너지는 구조. 괴물보다 '진실을 알아버린 것' 자체가 파국. 'The Call of Cthulhu', '광기의 산맥', 토머스 리고티·'유전' 후반부의 결.","beats":[{"title":"1막 — 균열의 발견","synopsis":"학자·기자·유산 상속자가 설명되지 않는 단서(문서·실종·기형)와 마주친다. 합리주의 세계관이 첫 금을 입는다.","folder":true,"children":[{"title":"유산으로서의 단서","synopsis":"죽은 친척의 유품, 미친 학자의 노트, 발굴된 유물 등 탐구를 촉발하는 '판도라의 상자'를 제시하는 장면. 이성적 주인공이 호기심·의무감으로 끌려 들어가게 하라."},{"title":"설명 불가의 패턴","synopsis":"각기 동떨어진 사건들(꿈·실종·기형 생물·고대 숭배)이 동일한 기하·날짜·상징으로 수렴함을 인물이 눈치채는 장면. 독자에게도 불길한 퍼즐 조각을 흩뿌려라."},{"title":"경고하는 광인","synopsis":"이미 진실을 본 자(미친 노인, 죽어가는 목격자)가 단편적 경고를 남기는 장면. '그만두라'는 만류가 오히려 탐구욕을 자극하는 아이러니를 활용하라."}]},{"title":"2막 — 금단의 탐구","synopsis":"주인공이 단서를 좇아 외딴 장소·고문서로 깊이 들어간다. 알수록 세계의 토대가 흔들리고 동료가 이탈한다.","folder":true,"children":[{"title":"변경으로의 여정","synopsis":"퇴락한 항구 마을, 인적 끊긴 유적, 극지 탐사 등 문명에서 멀어지는 답사 장면. 현지 주민의 기형·침묵·이질적 풍습으로 '여기는 다르다'를 감각화하라."},{"title":"금서·기록의 해독","synopsis":"고문서·벽화·필름을 해독하며 우주적 진실의 윤곽이 드러나는 장면. 정보를 직접 서술하기보다 인물의 정신이 견디지 못하는 반응으로 공포를 전달하라."},{"title":"스쳐가는 존재의 그림자","synopsis":"괴물을 전면에 드러내지 말고 흔적·소리·비현실적 각도·동료의 변질로만 암시하는 장면. '본 것'보다 '암시된 것'이 더 크다는 코스믹 호러 원칙을 지켜라."},{"title":"되돌릴 수 없는 지점","synopsis":"동료의 죽음·실성·배신으로 퇴로가 막히고 주인공만 진실을 향해 나아가는 전환점. 지식이 곧 저주임이 분명해진다."}]},{"title":"3막 — 진실과 와해","synopsis":"주인공이 견딜 수 없는 진실(인류의 무의미함, 잠든 신, 시간의 거짓)과 직면한다. 승리는 없고 인식의 붕괴만 있다.","folder":true,"children":[{"title":"전모의 직시","synopsis":"숨겨진 존재·차원·진실이 마침내 드러나는 클라이맥스. 물리적 위협보다 '우주에 인간은 의미가 없다'는 인식적 충격에 무게를 두라."},{"title":"정신의 붕괴","synopsis":"진실을 안 대가로 주인공의 이성이 무너지는 장면. 도망쳐도 머릿속에서 지울 수 없는 지식이 진짜 형벌임을 그려라."},{"title":"무력한 생존 혹은 동화","synopsis":"괴물을 물리치는 게 아니라 가까스로 도망치거나, 거대 존재에게 흡수·동화되는 결말. 인간의 행위가 우주적으로 무의미했음을 확정하라."}]},{"title":"에필로그 — 깨어나는 것","synopsis":"진실은 봉인되지 않았고 더 큰 것이 다가옴을 암시. 개인의 파멸은 서막에 불과하다.","folder":true,"children":[{"title":"기록으로 남은 광기","synopsis":"수기·녹취·편지 형식으로 주인공의 마지막 진술이 남는 장면. 신뢰할 수 없는 화자의 떨리는 문장으로 진실의 무게를 전하라."},{"title":"다가오는 거대한 것","synopsis":"별의 정렬, 잠든 존재의 뒤척임, 늘어나는 광신도 한 컷으로 인류 차원의 파국을 예고. 개인의 비극을 우주적 스케일로 확장하라."}]}]},{"id":"g7-possession-exorcism-faith","category":"호러·공포","name":"빙의·퇴마형 (신앙과 의식의 대결)","desc":"무고한 자(흔히 아이/여성)에게 악령이 깃들고, 회의하던 성직자/퇴마사가 신앙과 죄책감을 걸고 맞서는 구조. '엑소시스트', '검은 사제들', '곡성', '컨저링' 시리즈의 결. 의학적 설명의 실패 → 영적 진단 → 의식의 사투 → 자기희생 곡선.","beats":[{"title":"1막 — 이상 증세의 시작","synopsis":"평범한 가정에 설명 안 되는 변화가 나타난다. 가족과 의학은 빙의를 의심하지 못한다.","folder":true,"children":[{"title":"변화하는 피해자","synopsis":"온순하던 아이/가족이 성격·목소리·신체가 기이하게 변하는 초기 징후 장면. 사춘기·질병·정신질환과 구분되지 않게 모호하게 그려 부정의 여지를 남겨라."},{"title":"의학의 실패","synopsis":"병원·검사·약물이 모두 무력해지는 장면. 과학적 설명이 막다른 길에 닿아야 영적 해석이 정당성을 얻는다. 이성과 신앙의 경계를 여기서 세워라."},{"title":"회의하는 구원자의 등장","synopsis":"신앙을 잃었거나 과거 실패한 성직자/퇴마사가 사건에 얽히는 장면. 그의 내적 결핍(죽은 이에 대한 죄책감, 신에 대한 의심)을 심어 후반 대가를 예비하라."}]},{"title":"2막 — 진단과 격화","synopsis":"빙의가 영적 사실로 확정되고, 악령은 퇴마사의 약점을 공략한다. 의식 준비와 심리전이 교차한다.","folder":true,"children":[{"title":"영적 진단과 증거","synopsis":"외국어 구사, 미지의 지식, 초자연적 현상 등 빙의의 객관적 증거가 쌓이는 장면. 회의론자(가족·동료 사제)를 설득하는 과정으로 독자의 믿음도 함께 다져라."},{"title":"악령의 심리전","synopsis":"악령이 퇴마사의 죄·비밀·상실을 정확히 찔러 신앙을 흔드는 장면. 적이 단순 괴물이 아니라 '나를 아는 자'임을 보여 공포를 내면화하라."},{"title":"의식의 준비와 규칙","synopsis":"퇴마 의식의 절차·금기·위험(악령의 이름 알아내기, 도중 멈추면 안 됨 등)을 세팅하는 장면. 클라이맥스의 규칙과 긴장 장치를 미리 설치하라."},{"title":"1차 의식의 실패","synopsis":"첫 퇴마 시도가 부분 성공 후 역공당하거나 조력자가 희생되는 좌절 비트. 악령의 격을 끌어올리고 주인공을 한계로 몰아라."}]},{"title":"3막 — 최후의 의식","synopsis":"퇴마사가 자신의 죄·신앙과 정면으로 맞서며 결정적 의식을 감행한다. 승리는 희생을 요구한다.","folder":true,"children":[{"title":"신앙의 회복 혹은 결단","synopsis":"퇴마사가 의심을 넘어 믿음을 되찾거나, 신앙 없이도 사랑·책임으로 맞서기로 결단하는 전환점. 내적 호선의 절정을 의식 직전에 배치하라."},{"title":"결정적 대치","synopsis":"악령과 정면으로 부딪치는 클라이맥스. 악령이 피해자의 얼굴·목소리로 애원하는 페이크와 그 너머의 진짜 적을 구분하는 긴장을 넣어라."},{"title":"자기희생의 추방","synopsis":"퇴마사가 악령을 자기 안에 받아들여 함께 소멸하는 등 자기희생으로 피해자를 구하는 결말. '엑소시스트'식 구원적 희생의 카타르시스를 노려라."}]},{"title":"에필로그 — 떠나지 않은 그림자","synopsis":"피해자는 구원받았으나 악은 완전히 사라지지 않았음을 암시. 신앙과 의심의 여운을 남긴다.","folder":true,"children":[{"title":"회복된 피해자","synopsis":"정상으로 돌아온 피해자와 그를 지켜보는 남은 자들의 장면. 평온 속에 미세한 위화감(기억 없음, 낯선 미소)을 심어라."},{"title":"옮겨간 악","synopsis":"악령이 다른 숙주나 다음 표적으로 이동했음을 암시하는 마지막 컷. 추방이 곧 소멸은 아님을 각인시켜라."}]}]},{"id":"g7-folk-horror-ritual","category":"호러·공포","name":"포크 호러형 (공동체와 제물)","desc":"외부인이 폐쇄적 시골/이교 공동체에 들어갔다가 그들의 오래된 믿음과 의식의 제물이 되는 구조. '위커맨', '미드소마', '곡성', '에일리언급의 환한 공포'. 환대 → 위화감 → 고립 → 진실 → 제의의 곡선. 어둠이 아닌 환한 대낮의 공포가 특징.","beats":[{"title":"1막 — 환대받는 외부인","synopsis":"주인공이 목적(취재·여행·치유·실종자 수색)을 품고 고립 공동체에 도착해 따뜻한 환영을 받는다.","folder":true,"children":[{"title":"공동체로의 진입 동기","synopsis":"주인공이 그곳에 가야만 하는 이유(상실의 치유, 실종자 추적, 학술 조사)를 세우는 장면. 개인적 상처를 심어 공동체가 그 약점을 파고들 여지를 만들어라."},{"title":"기이하게 따뜻한 환대","synopsis":"지나치게 친절한 주민, 풍요로운 축제, 목가적 풍경을 그리는 장면. 밝고 아름다울수록 좋다. 환대 속에 미묘한 통제와 감시를 한두 컷 숨겨라."},{"title":"낯선 관습의 전시","synopsis":"이상한 음식·노래·복식·금기를 주인공이 호기심으로 관찰하는 장면. 나중에 의미가 밝혀질 상징(꽃관, 룬, 제단)을 무해해 보이게 깔아라."}]},{"title":"2막 — 균열과 고립","synopsis":"축제의 이면이 드러나기 시작하고, 동행이 사라지거나 주인공의 퇴로가 막힌다. 외부인은 점점 혼자가 된다.","folder":true,"children":[{"title":"동행의 이탈·소멸","synopsis":"함께 온 일행이 의문스럽게 사라지거나 공동체에 동화되는 장면. 주인공의 지지 기반을 제거해 고립감을 키워라."},{"title":"불온한 의식의 목격","synopsis":"주인공이 우연히 잔혹하거나 비정상적인 의식·문서·과거 흔적을 목격하는 장면. '여기는 단순한 마을이 아니다'를 확정하되 전모는 아끼라."},{"title":"퇴로의 봉쇄","synopsis":"차량·통신·길이 막히고, 도움을 청하려는 시도가 주민에 의해 무력화되는 장면. 환한 대낮에 도망칠 수 없는 폐소공포를 연출하라."},{"title":"선택받은 자라는 암시","synopsis":"주민들이 주인공을 특별하게 대하는 이유가 '제물/배우자/그릇'이었음이 드러나기 시작하는 전환점. 환대가 사육이었음을 깨닫게 하라."}]},{"title":"3막 — 제의","synopsis":"공동체의 진짜 목적이 완성되는 의식이 거행된다. 주인공의 저항은 이미 짜인 각본의 일부다.","folder":true,"children":[{"title":"신앙 체계의 폭로","synopsis":"공동체의 신·주기·희생 논리가 전모를 드러내는 장면. 그들의 광기에 내적 일관성을 부여해 단순한 미치광이가 아니라 '다른 세계관'으로 보이게 하라."},{"title":"저항의 무의미함","synopsis":"주인공의 탈출·반격이 사실 의식의 정해진 절차였음이 드러나는 비트. 발버둥조차 각본대로라는 무력감이 포크 호러 특유의 절망이다."},{"title":"제물의 완성","synopsis":"화형·생매장·결합 등으로 의식이 완성되는 클라이맥스. '미드소마'식으로 공포와 황홀이 뒤섞인 양가감정, 환한 화면 속 잔혹으로 마무리하라."}]},{"title":"에필로그 — 순환하는 계절","synopsis":"의식은 주기적으로 반복되며 공동체는 다음 외부인을 기다린다. 자연의 순환처럼 공포가 영속한다.","folder":true,"children":[{"title":"회복된 풍요","synopsis":"제물 덕에 풍년·치유·결속을 얻은 공동체의 평온한 일상 장면. 끔찍한 대가 위에 세워진 목가를 대비로 보여라."},{"title":"다음 주기의 예고","synopsis":"달력·계절·다가오는 외부인 한 컷으로 의식의 순환을 암시. 첫 장면의 환대와 운율을 맞춰 영속하는 공포를 각인시켜라."}]}]},{"id":"g7-body-horror-transformation","category":"호러·공포","name":"바디 호러·감염형 (변이하는 몸)","desc":"감염·실험·기생·돌연변이로 인물의 몸이 통제 불가하게 변형되며 자아·관계·인간성이 해체되는 구조. 크로넌버그 '더 플라이'·'비디오드롬', 카펜터 '괴물', '리바이어던', 좀비/감염 서사의 결. 외부 괴물보다 '내 몸이 적이 되는' 내부의 공포.","beats":[{"title":"1막 — 감염·접촉","synopsis":"주인공이 미지의 병원체·실험·생물과 접촉한다. 처음엔 사소하거나 심지어 긍정적 변화로 보인다.","folder":true,"children":[{"title":"최초의 접촉","synopsis":"실험 사고·물림·기생·신기술 사용 등 변이의 씨앗이 심어지는 장면. 주인공의 야심·호기심·생계가 위험을 자초하게 만들어 비극에 책임을 부여하라."},{"title":"기만적 호전","synopsis":"변이 초기에 활력·능력·매력이 오히려 향상되는 장면. 주인공이 변화를 환영하게 만들어 후반 추락의 낙차를 키워라. '더 플라이' 초반의 도취를 참고하라."},{"title":"관계의 기반 제시","synopsis":"연인·가족·동료 등 주인공이 잃게 될 인간관계를 보여주는 장면. 변이가 파괴할 정서적 닻을 미리 심어 비극의 무게를 확보하라."}]},{"title":"2막 — 변이의 가속","synopsis":"신체 변화가 통제를 벗어나 추해지고 고통스러워진다. 주인공은 숨기려 하고 주변은 멀어진다.","folder":true,"children":[{"title":"되돌릴 수 없는 징후","synopsis":"탈락하는 신체·이상 분비물·새 기관 등 명백히 병적인 변이가 나타나는 장면. 신체의 디테일을 구체적이고 즉물적으로 묘사해 생리적 혐오를 끌어내라."},{"title":"은폐와 고립","synopsis":"주인공이 변이를 숨기려 관계를 끊고 칩거하는 장면. 수치와 두려움이 자발적 고립을 부르고, 도움받을 통로가 스스로 닫히게 하라."},{"title":"자아의 침식","synopsis":"충동·식욕·인격이 변이체의 본능에 잠식되는 장면. '나는 아직 나인가'라는 정체성 공포를 행동 변화로 보여라. 사랑하는 이를 위협하는 순간을 한 번 넣어라."},{"title":"치료의 실패","synopsis":"되돌리려는 의학·과학적 시도가 무위로 끝나거나 변이를 가속하는 비트. 마지막 희망을 제거해 주인공을 막다른 선택으로 몰아라."}]},{"title":"3막 — 인간성의 종말","synopsis":"주인공이 더는 인간이 아니게 되는 임계점. 남은 인간성으로 마지막 선택을 한다.","folder":true,"children":[{"title":"완전한 변이","synopsis":"주인공이 괴물로 완성되거나 자아가 거의 소멸하는 클라이맥스. 신체의 그로테스크가 정점에 이르고, 원래의 인간은 흔적으로만 남게 하라."},{"title":"마지막 인간성의 발현","synopsis":"변이체 속에 남은 일말의 자아가 사랑하는 이를 알아보거나 보호하려는 장면. 괴물 안의 인간을 비추어 비극의 정서를 절정으로 끌어올려라."},{"title":"자기파괴적 구원","synopsis":"주인공이 자신의 죽음·격리·박멸을 스스로 청하는 결말. '더 플라이'식으로 사랑하는 이에게 자신을 끝내달라 하는 비극적 자비를 노려라."}]},{"title":"에필로그 — 퍼지는 것","synopsis":"한 사람의 비극이 더 큰 확산의 시작이었음을 암시. 감염은 끝나지 않는다.","folder":true,"children":[{"title":"남겨진 자의 상흔","synopsis":"주인공을 떠나보낸 이의 트라우마와 죄책감을 비추는 장면. 인간 쪽의 상실을 정리해 정서적 마침표를 찍어라."},{"title":"확산의 씨앗","synopsis":"또 다른 감염자·잔존 검체·전이된 자손 한 컷으로 위협의 존속을 암시. 개인의 변이가 세계적 위협의 서막이었음을 열어두라."}]}]},{"id":"g8-court-power-intrigue","category":"역사·사극","name":"궁중 권력 암투극","desc":"왕좌를 둘러싼 파벌·외척·환관·중전·후궁의 음모가 겹겹이 쌓이는 정치 스릴러형 사극. 칼이 아니라 상소·밀지·독약·인사이동으로 사람이 죽는다. 대장금·뿌리깊은나무·한중록·옹정황제류의 결로, 권력의 사다리를 오르내리는 인물의 줄타기가 핵심이다.","beats":[{"title":"1부 - 입궐과 판세 읽기","synopsis":"주인공이 궁(혹은 권부)에 발을 들이고 보이지 않는 파벌 지형을 파악하는 단계.","folder":true,"children":[{"title":"낯선 권부에 던져지다","synopsis":"신참 궁녀·하급 관리·새 후궁 등 약자 위치의 주인공이 처음 궁에 들어선 날의 위압감을 그린다. 화려한 겉모습 뒤 숨막히는 위계와 감시, 사소한 실수가 목숨이 되는 규칙을 한 장면으로 각인시킨다."},{"title":"보이지 않는 파벌 지형도","synopsis":"누가 누구의 사람인지, 중전 측과 후궁 측, 외척과 신권 등 대립 구도를 주인공의 관찰을 통해 독자에게 자연스럽게 학습시킨다. 겉으로 웃으며 속으로 칼을 가는 인물 한둘을 클로즈업한다."},{"title":"첫 줄을 서는 선택","synopsis":"중립으로 남을 수 없는 상황이 닥쳐 주인공이 어느 편에 미세하게 기우는 첫 선택을 한다. 이 선택이 훗날 발목을 잡거나 버팀목이 될 복선임을 암시한다."}]},{"title":"2부 - 첫 음모와 누명","synopsis":"주인공이 권력 게임의 말로 쓰이거나 표적이 되어 위기에 빠지는 단계.","folder":true,"children":[{"title":"독·밀서·인장 - 첫 사건","synopsis":"독살 미수, 위조 밀서, 사라진 옥새 등 궁중 특유의 사건이 터진다. 직접적 폭력 대신 정황과 증거 조작으로 사람이 옭아매이는 방식을 구체적으로 그린다."},{"title":"누명과 친국","synopsis":"주인공 혹은 그 비호 세력이 사건의 범인으로 지목된다. 형신·국문 장면에서 자백을 강요당하는 압박, 침묵으로 지켜야 할 비밀을 대비시킨다."},{"title":"은인과 배신자의 분별","synopsis":"위기 속에서 누가 손을 내밀고 누가 등을 돌리는지 드러난다. 의외의 조력자와 믿었던 자의 배신을 교차시켜 다음 막의 동맹 재편을 준비한다."}]},{"title":"3부 - 반격의 포석","synopsis":"수세에서 공세로 전환하며 정보·인맥·약점을 모아 역공을 설계하는 단계.","folder":true,"children":[{"title":"적의 약점 수집","synopsis":"주인공이 정적의 비리·치부·과거 죄를 캐낸다. 장부, 옛 증인, 비밀 서찰 등 증거 사슬을 하나씩 확보하는 과정을 추리물처럼 짠다."},{"title":"동맹의 재구성","synopsis":"어제의 적과 손잡고 어제의 우군을 버리는 권력의 비정함을 보여준다. 거래 조건과 서로의 속셈을 깔아 긴장을 유지한다."},{"title":"결정적 한 수의 함정 설계","synopsis":"정적을 한 번에 무너뜨릴 덫(거짓 정보 흘리기, 어전 폭로 타이밍 등)을 치밀하게 설계한다. 독자에게는 일부만 보여주고 핵심은 숨겨 반전의 여지를 남긴다."}]},{"title":"4부 - 어전 결판과 권력의 대가","synopsis":"공개된 자리에서 진실과 음모가 충돌하고 승패가 갈리는 절정과 그 여운.","folder":true,"children":[{"title":"어전 폭로전","synopsis":"왕 앞 조정 회의나 친국 자리에서 증거와 논리로 정적을 무너뜨린다. 반전 카드와 역전된 반전을 연쇄적으로 배치해 끝까지 결말을 알 수 없게 한다."},{"title":"승자의 빈자리","synopsis":"이겼지만 잃은 것을 비추는 장면. 권력을 위해 희생한 인연, 변해버린 자기 자신을 직시하게 한다. 사극 특유의 무상함을 담는다."},{"title":"다음 판의 그림자","synopsis":"권력 게임은 끝나지 않음을 암시한다. 새 위협의 등장이나 주인공이 이제 누군가의 표적이 된 입장 역전을 깔아 연재 동력을 만든다."}]}]},{"id":"g8-rise-of-founder","category":"역사·사극","name":"난세 영웅·창업 군주기","desc":"혼란기에 미천하거나 몰락한 인물이 세력을 키워 천하를 도모하는 대하 영웅 서사. 삼국지·초한지·정도전·태조 왕건·킹덤(만화)류로, 인재 규합과 결정적 전투, 명분 싸움이 축이다. 개인의 성장과 시대의 격변이 맞물린다.","beats":[{"title":"1부 - 난세와 각성","synopsis":"주인공이 시대의 혼란 속에서 야망 혹은 사명을 자각하는 발단.","folder":true,"children":[{"title":"무너지는 천하","synopsis":"기근·반란·폭정·외침 등 시대의 붕괴를 강렬한 장면으로 연다. 백성의 참상과 기존 질서의 무능을 보여 영웅이 등장할 무대를 만든다."},{"title":"바닥에서의 굴욕","synopsis":"주인공이 미천한 신분·몰락·억울한 패배를 겪는다. 끓어오르는 분노와 살아남겠다는 의지가 첫 동력이 되는 결정적 순간을 그린다."},{"title":"첫 동지와 큰 뜻","synopsis":"운명적 의형제·책사·은인을 만나 작은 무리를 이룬다. 단순 생존을 넘어 '큰 뜻'을 품게 되는 도원결의식 약속 장면을 배치한다."}]},{"title":"2부 - 세력 규합과 첫 승리","synopsis":"인재를 모으고 작은 전투에서 이기며 세력 기반을 닦는 단계.","folder":true,"children":[{"title":"삼고초려 - 인재 영입","synopsis":"핵심 책사·맹장을 어렵게 얻는다. 인물의 됨됨이를 시험하는 일화와 영입 협상을 통해 주인공의 그릇을 보여준다."},{"title":"약자의 기책","synopsis":"병력 열세를 지략으로 뒤집는 첫 대승(매복·화공·이간계 등)을 그린다. 정공법이 아닌 기지로 이기는 전투 묘사로 카타르시스를 준다."},{"title":"근거지 확보와 민심","synopsis":"성·고을을 얻고 백성을 다스리며 명분을 쌓는다. 무력만이 아닌 통치 비전을 보여 다른 군웅과 차별화한다."}]},{"title":"3부 - 대적과 시련","synopsis":"압도적 강적과 충돌하고 동지의 죽음·배신으로 좌절하는 위기.","folder":true,"children":[{"title":"거대한 적의 등장","synopsis":"주인공을 압도하는 패권 세력 혹은 숙적이 전면에 나선다. 힘의 격차를 명확히 보여 다윗과 골리앗 구도를 만든다."},{"title":"동지의 죽음과 배신","synopsis":"아끼던 장수·책사를 잃거나 측근의 배신을 겪는다. 영웅 서사의 무게를 더하는 상실의 장면을 깊게 다룬다."},{"title":"최악의 패배와 도주","synopsis":"세력이 와해될 위기의 대패를 당한다. 모든 것을 잃고 재기조차 불투명한 바닥에서 다시 일어설 불씨를 남긴다."}]},{"title":"4부 - 천하를 건 결전","synopsis":"운명을 가르는 대회전에서 승부를 보는 절정.","folder":true,"children":[{"title":"건곤일척의 전략","synopsis":"모든 역량을 건 최후의 결전을 설계한다. 동맹·지형·시기·민심을 총동원하는 대전략을 펼쳐 보인다."},{"title":"결전의 대회전","synopsis":"적벽·해하 같은 대규모 전투를 박진감 있게 그린다. 개인의 무용과 전체 전황을 교차하며 승부의 결정적 순간을 만든다."},{"title":"승리, 그러나 더 무거운 짐","synopsis":"천하를 얻었으나 통치와 토사구팽의 정치가 시작됨을 암시한다. 영웅이 군주가 되며 짊어질 새 고뇌를 예고한다."}]}]},{"id":"g8-faction-reform-tragedy","category":"역사·사극","name":"사림·개혁가 비극","desc":"이상을 품은 신진 사대부·개혁가가 기득권과 충돌하다 끝내 좌절·숙청당하는 비극형 정통 사극. 조광조·정약용·갑신정변·전봉준류로, 명분과 현실의 괴리, 시대를 앞선 자의 고독이 정조다. 승리가 아닌 의미 있는 패배가 미학이다.","beats":[{"title":"1부 - 이상의 점화","synopsis":"개혁가가 부조리를 목격하고 세상을 바꾸겠다는 신념을 세우는 단계.","folder":true,"children":[{"title":"썩은 질서의 목격","synopsis":"탐관오리의 수탈, 신분제의 모순, 부패한 조정을 주인공이 직접 목격한다. 분노와 사명감이 싹트는 구체적 사건을 제시한다."},{"title":"동지들과의 결의","synopsis":"뜻을 같이하는 동학·문우들과 개혁의 청사진을 그린다. 밤을 새워 토론하는 이상주의의 뜨거움과 순수함을 담는다."},{"title":"권좌로의 진출","synopsis":"왕의 신임을 얻거나 요직에 올라 개혁을 실행할 발판을 마련한다. 짧은 봄날 같은 희망의 절정을 보여 후일의 추락을 대비시킨다."}]},{"title":"2부 - 개혁의 추진과 균열","synopsis":"급진적 개혁이 성과를 내지만 기득권의 반발과 내부 분열이 시작되는 단계.","folder":true,"children":[{"title":"거침없는 개혁 드라이브","synopsis":"토지·과거·신분 제도 등에 칼을 댄다. 정의롭지만 너무 빠르고 타협 없는 추진이 적을 양산하는 양면성을 그린다."},{"title":"기득권의 결집","synopsis":"위협을 느낀 훈구·외척·지방 세력이 연합 전선을 형성한다. 적의 입장에서도 나름의 논리가 있음을 보여 단순한 선악 구도를 피한다."},{"title":"내부의 균열과 과속","synopsis":"동지 간 노선 차이, 현실론과 이상론의 충돌이 불거진다. 주인공의 독선이나 조급함이 화근이 되는 비극의 씨앗을 심는다."}]},{"title":"3부 - 반동과 함정","synopsis":"왕의 변심과 정적의 모함으로 개혁가가 역모로 몰리는 단계.","folder":true,"children":[{"title":"왕의 두려움과 변심","synopsis":"신권의 비대화를 경계한 왕이 등을 돌린다. 개혁의 가장 큰 후원자가 가장 큰 위협이 되는 권력의 역설을 그린다."},{"title":"조작된 역모","synopsis":"주초위왕 같은 술수로 개혁가가 모반죄로 옭아매인다. 누명의 정교함과 빠져나갈 수 없는 정치적 함정을 구체적으로 보여준다."},{"title":"버려짐과 체포","synopsis":"동지들이 흩어지고 주인공이 끝내 체포된다. 도망칠 수 있었으나 신념 때문에 도망치지 않는 선택으로 비극의 격을 높인다."}]},{"title":"4부 - 좌절, 그러나 남은 불씨","synopsis":"개혁가의 죽음·유배와 그가 남긴 미래의 씨앗을 그리는 결말.","folder":true,"children":[{"title":"사약 혹은 형장","synopsis":"주인공이 죽음 앞에서도 신념을 꺾지 않는다. 마지막 절명시·유언을 통해 패배 속의 존엄을 각인시킨다."},{"title":"남겨진 자들","synopsis":"살아남은 동지·제자·가족이 뜻을 기억하고 이어간다. 당대엔 졌으나 사상이 후대에 전해지는 씨앗을 보여준다."},{"title":"후대의 재평가","synopsis":"세월이 흐른 뒤 그가 옳았음이 증명되거나 복권되는 에필로그. 시대를 앞선 자의 고독이 역사 속에서 의미를 획득함을 마무리한다."}]}]},{"id":"g8-faction-romance-saga","category":"역사·사극","name":"신분 격차 로맨스 사극","desc":"엄격한 신분제 사회에서 넘을 수 없는 벽을 사이에 둔 두 남녀의 사랑을 시대의 격랑과 엮은 멜로 사극. 황진이·동이·해를품은달·구르미그린달빛류로, 금지된 사랑·정략혼·신분 상승·이별과 재회가 축이다. 시대적 제약이 곧 로맨스의 동력이다.","beats":[{"title":"1부 - 운명적 만남","synopsis":"신분이 다른 두 사람이 시대 배경 속에서 얽히는 발단.","folder":true,"children":[{"title":"신분을 가린 첫 조우","synopsis":"정체를 숨긴 채(미복잠행·변복 등) 두 사람이 만나 서로에게 끌린다. 신분의 가림막이 있기에 가능한 순수한 첫 인상을 그린다."},{"title":"다시 마주친 진짜 신분","synopsis":"각자의 진짜 위치(왕과 궁녀, 양반과 기생·노비 등)가 드러나며 거리감이 생긴다. 끌림과 신분 자각 사이의 흔들림을 포착한다."},{"title":"거리를 두려는 마음","synopsis":"이뤄질 수 없음을 알기에 서로 밀어내려 한다. 그럴수록 짙어지는 마음의 아이러니로 긴장을 만든다."}]},{"title":"2부 - 금지된 사랑의 심화","synopsis":"주변의 시선과 제약을 피해 사랑이 깊어지는 단계.","folder":true,"children":[{"title":"은밀한 교감","synopsis":"남몰래 만나고 마음을 확인하는 달콤한 장면들. 시·서찰·꽃 등 시대적 매개를 활용한 절제된 애틋함을 그린다."},{"title":"정략의 그림자","synopsis":"정략혼·간택·진상 등 신분 사회의 제도가 둘 사이를 위협한다. 개인의 마음과 가문·국가의 논리가 충돌하기 시작한다."},{"title":"연적과 조력자","synopsis":"정략혼 상대 혹은 짝사랑하는 제3자, 그리고 둘을 돕는 조력자가 등장한다. 사각 관계와 우군 구도로 갈등을 입체화한다."}]},{"title":"3부 - 이별과 시련","synopsis":"정치적 격변과 신분의 벽으로 두 사람이 헤어지는 단계.","folder":true,"children":[{"title":"발각과 처벌","synopsis":"관계가 드러나 한쪽이 유배·하옥·축출되는 위기를 맞는다. 신분을 넘은 사랑에 대한 사회의 가혹한 처벌을 보여준다."},{"title":"생이별","synopsis":"지키기 위해 떠나보내거나 강제로 떨어진다. 이별 장면의 절절함과 다시 만나겠다는 약속을 새긴다."},{"title":"각자의 단련","synopsis":"헤어진 동안 각자 성장하고 입지를 다진다. 재회를 위한 신분 상승·복권·세력 확보의 포석을 깐다."}]},{"title":"4부 - 재회와 결실","synopsis":"성장한 두 사람이 다시 만나 사랑을 이루거나 비극으로 승화하는 절정.","folder":true,"children":[{"title":"달라진 위치에서의 재회","synopsis":"신분의 벽을 넘을 힘을 얻은 채 재회한다. 변했지만 변하지 않은 마음을 확인하는 감격의 장면을 그린다."},{"title":"마지막 장벽 돌파","synopsis":"남은 정적·제도·가문의 반대를 함께 무너뜨린다. 두 사람의 연대가 시대의 벽을 넘는 카타르시스를 만든다."},{"title":"이루어진 사랑 혹은 영원한 이별","synopsis":"혼인으로 결실을 맺거나, 끝내 닿지 못하고 비극으로 승화한다. 어느 쪽이든 시대를 관통한 사랑의 의미를 마무리한다."}]}]},{"id":"g8-low-born-survival","category":"역사·사극","name":"민초·생활사 군상극","desc":"왕후장상이 아닌 상인·의원·장인·기생·아전 등 시정 사람들의 생존과 출세를 그리는 생활사·직업 사극. 상도·허준·대장금·미스터선샤인류로, 한 분야의 입신양명과 시대의 풍속·경제가 축이다. 미시사적 디테일과 직업적 성취가 동력이다.","beats":[{"title":"1부 - 밑바닥 입문","synopsis":"주인공이 한 직업·생업의 세계에 발을 들이는 발단.","folder":true,"children":[{"title":"생계의 벼랑","synopsis":"몰락·빚·고아·천출 등으로 절박한 처지에 놓인다. 살아남기 위해 어떤 일이든 해야 하는 절실함을 그린다."},{"title":"스승과 바닥 일","synopsis":"장사·의술·요리 등의 세계에 입문해 허드렛일부터 시작한다. 그 분야의 디테일(상거래 관행, 약재, 식재료 등)을 실감나게 깐다."},{"title":"타고난 재능의 발현","synopsis":"남다른 감각이나 집념으로 첫 두각을 나타낸다. 동시에 그것을 시기하는 텃세와 경쟁자를 등장시킨다."}]},{"title":"2부 - 성장과 첫 시험대","synopsis":"실력을 쌓고 직업적 위기를 정면 돌파하며 인정받는 단계.","folder":true,"children":[{"title":"기술의 연마","synopsis":"각고의 노력으로 한 단계 위의 실력을 갖춘다. 직업 특유의 수련 과정과 비결 습득을 구체적으로 묘사한다."},{"title":"직업적 난제의 해결","synopsis":"역병·거상의 농간·불가능한 주문 등 그 직업의 큰 난제를 마주한다. 기지와 신념으로 풀어내며 명성을 얻는 장면을 만든다."},{"title":"신의 vs 이익의 갈림길","synopsis":"돈·출세와 사람의 도리 사이에서 선택을 강요받는다. 주인공의 직업 철학(상도·의도 등)을 정립하는 결정적 분기를 둔다."}]},{"title":"3부 - 음모와 추락","synopsis":"경쟁자의 모함과 시대의 격변으로 모든 것을 잃는 위기.","folder":true,"children":[{"title":"거대 세력의 견제","synopsis":"권력과 결탁한 거상·세도가가 주인공을 짓밟으려 한다. 개인이 맞서기엔 너무 큰 벽의 압박을 보여준다."},{"title":"누명과 파산","synopsis":"조작된 사건으로 가게·면허·명성을 한꺼번에 잃는다. 정점에서 바닥으로의 추락을 극적으로 그린다."},{"title":"신념을 지킨 대가","synopsis":"타협하면 살 수 있었으나 직업적 양심을 택해 더 큰 손해를 본다. 그 선택이 훗날 재기의 명분이 됨을 복선으로 깐다."}]},{"title":"4부 - 재기와 입신","synopsis":"쌓아온 신의와 실력으로 재기해 한 분야의 정점에 서는 절정.","folder":true,"children":[{"title":"도와주는 사람들","synopsis":"그동안 베푼 신의가 돌아와 옛 인연들이 손을 내민다. 사람을 남긴 것이 가장 큰 자산이었음을 증명한다."},{"title":"결정적 역전의 승부","synopsis":"거상과의 상전·궁중 진료·임금의 수라 등 운명을 건 직업적 승부에서 이긴다. 실력과 신의의 총결산을 보여준다."},{"title":"정점에서의 베풂","synopsis":"최고의 자리에 올라 부와 명예를 사회에 환원한다. 입신양명을 넘어선 직업의 도(道)로 이야기를 마무리한다."}]}]},{"id":"g8-secret-record-mystery","category":"역사·사극","name":"역사 미스터리·실록 추적극","desc":"역사 기록의 공백·금기·암호에 숨겨진 진실을 파헤치는 추리형 사극. 영원한제국·바람의화원·다빈치코드의 사극판·정조 독살설류로, 과거 사건의 진상 규명과 현재(극중 시점)의 음모가 이중으로 얽힌다. 사료의 행간을 단서로 삼는 지적 추적이 핵심이다.","beats":[{"title":"1부 - 균열의 발견","synopsis":"공식 기록과 어긋나는 이상한 단서를 우연히 발견하는 발단.","folder":true,"children":[{"title":"수상한 죽음·기록","synopsis":"급사한 인물, 지워진 실록 한 줄, 봉인된 문서 등 이상 징후를 마주한다. 표면적 설명에 어긋나는 미세한 균열을 포착하게 한다."},{"title":"휘말리는 추적자","synopsis":"사관·화원·금부도사·서리 등 기록·수사에 접근 가능한 주인공이 사건에 얽힌다. 단순 호기심이 위험한 진실 추적으로 바뀌는 계기를 만든다."},{"title":"첫 경고","synopsis":"캐지 말라는 협박·미행·동료의 변사가 발생한다. 진실 뒤에 거대한 세력이 있음을 암시하며 긴장을 끌어올린다."}]},{"title":"2부 - 단서의 사슬","synopsis":"사료·암호·증언을 하나씩 풀어 사건의 윤곽을 잡아가는 단계.","folder":true,"children":[{"title":"사료의 행간 읽기","synopsis":"실록·일기·서찰의 어긋남에서 단서를 추론한다. 기록학·고증을 활용한 지적 추리 과정을 독자가 따라오게 설계한다."},{"title":"숨은 증인","synopsis":"사건을 목격한 생존자·관련자를 어렵게 찾아낸다. 두려움에 입을 닫은 증인을 설득하는 과정과 부분적 진실의 노출을 그린다."},{"title":"조작된 진실의 정황","synopsis":"공식 기록 자체가 누군가에 의해 조작됐음을 깨닫는다. 사건의 규모가 개인을 넘어 국가적 음모임이 드러나는 전환점을 둔다."}]},{"title":"3부 - 역공과 반전","synopsis":"배후 세력의 정체에 다가서며 가짜 진실과 진짜 진실이 뒤집히는 단계.","folder":true,"children":[{"title":"유력한 배후 지목","synopsis":"정황상 가장 의심스러운 인물을 범인으로 좁힌다. 독자도 확신하게 만든 뒤 뒤집을 반전의 토대를 깐다."},{"title":"믿었던 자의 진실","synopsis":"조력자가 적이거나 적이 피해자였다는 반전을 터뜨린다. 표면의 선악이 뒤집히며 사건의 진짜 동기를 재구성하게 한다."},{"title":"막다른 위기","synopsis":"진실에 가장 근접한 순간 주인공이 가장 큰 위험(체포·암살 시도)에 빠진다. 모은 증거가 소실될 위기로 절정 직전 긴장을 최대화한다."}]},{"title":"4부 - 진실의 공개와 대가","synopsis":"은폐된 진상이 밝혀지고 그 진실이 불러올 파장을 감당하는 절정.","folder":true,"children":[{"title":"감춰진 진상의 전모","synopsis":"사건의 전체 진실(독살·찬탈·은폐된 혈통 등)이 마침내 드러난다. 흩어진 단서가 하나로 꿰어지는 추리물의 쾌감을 완성한다."},{"title":"진실을 둘러싼 마지막 결단","synopsis":"진실을 폭로할 것인가 묻을 것인가를 두고 고뇌한다. 진실이 가져올 혼란과 정의 사이에서 주인공의 가치관을 시험한다."},{"title":"기록되지 못한 진실","synopsis":"밝혀진 진실이 공식 역사엔 끝내 남지 못하거나 다른 형태로 봉인됨을 보여준다. 역사 기록의 본질에 대한 여운을 남기며 마무리한다."}]}]},{"id":"g9-revenge-payback","category":"액션·전쟁","name":"복수형 액션 (페이백 구조)","desc":"주인공이 소중한 것을 빼앗긴 뒤, 일선에서 물러났던 실력을 다시 꺼내 적의 조직을 위에서 아래로(혹은 아래에서 위로) 한 단계씩 격파해 올라가는 구조. '존 윅', '테이큰', '아저씨' 계열. 독자는 무력감 → 각성 → 통쾌한 응징의 카타르시스를 기대한다.","beats":[{"title":"1막 — 평온과 강탈","synopsis":"은퇴/은둔한 강자의 일상과, 그것을 무너뜨리는 사건.","folder":true,"children":[{"title":"지켜야 할 것","synopsis":"주인공이 과거의 폭력에서 벗어나 지키고 있는 '평범한 행복'(딸, 반려, 작은 가게, 약속)을 보여라. 그가 얼마나 강했는지는 암시만 하고 직접 보여주지 마라 — 나중의 반전 효과를 위해."},{"title":"선을 넘는 자들","synopsis":"적이 주인공의 정체를 모른 채(혹은 알면서도 얕보고) 그 행복을 짓밟는다. 납치/살해/강탈. 적의 오만함과 잔혹함을 구체적으로 그려 독자의 분노를 적립하라."},{"title":"봉인 해제","synopsis":"주인공이 무릎 꿇었다 일어서는 전환점. 옛 도구를 꺼내거나 옛 동료에게 전화하거나, 적에게 '돌이킬 기회'를 한 번 주고 거절당하는 장면. 여기서 처음으로 그의 진짜 얼굴을 슬쩍 보여라."}]},{"title":"2막 — 사슬을 거슬러 오르기","synopsis":"말단부터 우두머리까지, 적의 위계를 한 칸씩 격파.","folder":true,"children":[{"title":"첫 표적 — 실력 증명","synopsis":"최하위 졸개/연락책을 압도적으로 제압하는 첫 액션. 독자에게 '아, 이 사람 진짜였구나'를 확실히 각인. 동시에 다음 단계로 가는 정보(이름/장소)를 얻는다."},{"title":"조직의 반격과 정체 누설","synopsis":"적 보스가 주인공의 정체(전직 요원/전설의 킬러/특수부대)를 알게 되며 공포에 빠지는 장면. 현상금/추격대를 붙여 난도를 올려라."},{"title":"중간 보스전과 대가","synopsis":"실력 있는 중간 간부와의 정면 격돌. 처음으로 주인공도 부상·손실을 입어 '무적이 아님'을 보여라. 작은 조력자(정보상, 옛 동료)의 희생을 끼워 긴장을 높인다."},{"title":"진실의 양파 껍질","synopsis":"복수의 진짜 배후가 예상보다 가깝거나(내부 배신) 더 거대한 조직임이 드러난다. 단순 응징이 더 큰 음모로 확장되는 미드포인트 반전."}]},{"title":"3막 — 최후의 응징","synopsis":"우두머리와의 결착과, 폭력 이후 주인공의 자리.","folder":true,"children":[{"title":"함정과 최저점","synopsis":"보스가 마지막 카드(인질, 배신, 압도적 화력)로 주인공을 궁지에 몬다. 모든 것을 잃기 직전의 절망 — 복수가 그를 집어삼킬 위험까지 보여라."},{"title":"최종 결착","synopsis":"우두머리와의 1대1(혹은 본거지 돌입). 앞서 적립한 분노를 한 번에 터뜨리는 카타르시스. 죽이느냐 / 살려두고 더 큰 형벌을 주느냐로 주인공의 인간성을 정의하라."},{"title":"재가 된 자리","synopsis":"복수는 끝났지만 빼앗긴 것은 돌아오지 않는다. 다시 어둠으로 사라지거나, 새 일상으로 돌아가려는 모습으로 여운. 속편 떡밥(다음 위협)을 한 줄 심어도 좋다."}]}]},{"id":"g9-squad-mission","category":"액션·전쟁","name":"전쟁 분대·작전 수행 구조","desc":"한 팀(분대/특공대)이 위험한 단일 작전을 부여받아 침투-수행-탈출하는 군사 액션 구조. '라이언 일병 구하기', '블랙 호크 다운', '13시간' 계열. 독자는 동료애, 작전의 디테일, 한 명씩 쓰러지는 비극, 그리고 '집으로'의 절박함을 기대한다.","beats":[{"title":"1막 — 임무와 인원","synopsis":"작전 하달과 팀원 소개, 출발.","folder":true,"children":[{"title":"불가능한 명령","synopsis":"상부가 비현실적이거나 정치적으로 더러운 임무를 던진다(요인 구출/거점 사수/요인 암살). 성공 확률이 낮음을 브리핑 장면에서 명확히 제시해 긴장 적립."},{"title":"분대 캐릭터 군상","synopsis":"각 팀원에게 식별 가능한 특징(고향 자랑, 곧 제대, 신참, 냉소가, 군의관)을 한 장면씩 부여. 누가 죽어도 독자가 아프도록 '이름과 사연'을 미리 심어라."},{"title":"전선으로","synopsis":"이동·투입 과정. 적지의 분위기, 정보와 현실의 괴리(브리핑과 다른 지형/적 규모)를 보여 첫 불안을 깐다."}]},{"title":"2막 — 작전의 붕괴","synopsis":"계획대로 되지 않으며 사상자가 발생한다.","folder":true,"children":[{"title":"첫 접촉","synopsis":"예상보다 강한 저항과의 첫 교전. 무기/전술 디테일을 사실감 있게. 작은 부상이나 보급 문제로 '계획에 금이 가기' 시작한다."},{"title":"첫 전사","synopsis":"팀에서 첫 희생자가 나온다. 가급적 호감 가던 인물로. 시신/유품/마지막 말을 통해 전쟁의 무게를 독자에게 각인하라."},{"title":"고립","synopsis":"통신 두절, 보급 차단, 퇴로 봉쇄 중 하나로 분대가 고립된다. 미드포인트: 임무 목표가 '작전 완수'에서 '생존·귀환'으로 변질되는 순간."},{"title":"내부 균열","synopsis":"공포·피로 속에서 명령 불복, 지휘권 다툼, 윤리적 갈등(포로/민간인 처리)이 터진다. 외부의 적만큼 내부도 위협임을 보여라."}]},{"title":"3막 — 최후의 사수와 귀환","synopsis":"절체절명의 방어전과 구조.","folder":true,"children":[{"title":"최후의 진지","synopsis":"남은 인원이 마지막 거점/엄폐물에서 압도적 적을 상대로 버틴다. 탄약 소진, 백병전 직전의 절박함. 가장 큰 액션 클라이맥스를 여기에 배치."},{"title":"구원 혹은 대가","synopsis":"지원/구조가 도착하거나, 누군가의 희생으로 활로가 열린다. 살아남기 위해 치른 대가(전사자 명단)를 분명히 하라."},{"title":"돌아온 자들","synopsis":"생존자가 귀환한다. 임무는 성공/실패했지만 무엇을 위한 희생이었나를 묻는 여운. 전사자의 이름·가족·묘비로 마무리하라."}]}]},{"id":"g9-underdog-rise","category":"액션·전쟁","name":"약자 각성·일점돌파 무패 구조","desc":"밑바닥/약체였던 주인공이 사건을 계기로 잠재력·기연·수련을 통해 강해지며, 점점 강한 적을 차례로 꺾고 정점에 오르는 상승형 액션. 격투/배틀/무협/현대판타지 액션 계열. 독자는 성장의 쾌감, 명확한 강함의 위계, 강적과의 승부수를 기대한다.","beats":[{"title":"1막 — 바닥과 계기","synopsis":"약자의 현실과 변화를 부르는 사건.","folder":true,"children":[{"title":"밟히는 자","synopsis":"주인공이 무시·핍박당하는 처지를 보여라(약하지만 근성/신념은 있음). 독자가 이입할 억울함과, 결코 포기 않는 핵심 동기를 심어라."},{"title":"각성의 불씨","synopsis":"재능 발견/스승과의 만남/기연(비급, 시스템, 이능)으로 강해질 길이 열린다. '왜 강해지려 하는가'의 목표를 명확히 못박아라."},{"title":"첫 승리, 첫 자각","synopsis":"예전 같으면 졌을 상대를 이기며 변화를 체감. 동시에 '위에는 더 강한 자가 있다'는 위계를 제시해 다음 목표를 띄운다."}]},{"title":"2막 — 계단 오르기","synopsis":"수련과 연전, 점점 강해지는 적.","folder":true,"children":[{"title":"수련과 대가","synopsis":"강해지는 과정의 고통과 트레이드오프를 구체적으로(혹독한 훈련, 부작용, 시간·관계의 희생). 거저 얻는 힘이 아님을 보여라."},{"title":"라이벌의 등장","synopsis":"동급 혹은 한 수 위의 라이벌과 격돌. 1차전은 패배 혹은 무승부로 두어 '벽'을 제시하고 재대결 욕구를 만든다."},{"title":"한계 돌파","synopsis":"패배·위기 직후 새로운 경지/기술/각성으로 한 단계 도약(미드포인트). 강함의 인플레이션을 독자가 납득하도록 '깨달음의 계기'를 분명히."},{"title":"강적 연파","synopsis":"토너먼트/항쟁/단계별 도전으로 강적들을 차례로 격파. 각 상대마다 다른 전술·결을 부여해 단조로움을 피하라."}]},{"title":"3막 — 정점의 대결","synopsis":"최강자와의 결착과 새 위상.","folder":true,"children":[{"title":"압도적 최종 보스","synopsis":"지금까지의 모든 적을 능가하는 절대강자(혹은 라이벌의 완성형)와 대치. 정면으로는 못 이긴다는 절망을 한 번 깔아라."},{"title":"모든 것을 건 승부","synopsis":"쌓아온 모든 경험·동료의 도움·필살기를 총동원한 클라이맥스 결투. 단순 파워가 아니라 '신념의 차이'로 승부를 가르면 더 강렬하다."},{"title":"정점에서 본 풍경","synopsis":"승리 후 주인공의 새 위상과 변화한 관계. 더 넓은 세계/새 적의 암시로 다음 상승의 여지를 남겨라."}]}]},{"id":"g9-siege-defense","category":"액션·전쟁","name":"농성·사수 방어전 구조","desc":"수적으로 열세인 소수가 한정된 공간(요새/건물/마을)에서 밀려오는 다수의 적을 정해진 시간/조건까지 버텨내는 방어전 구조. '300', '다이하드', '알라모', '7인의 사무라이' 계열. 독자는 공간의 전략적 활용, 파상공세의 점증, 자원 고갈의 긴장을 기대한다.","beats":[{"title":"1막 — 닥쳐오는 위협","synopsis":"적의 도래와 방어 결의, 준비.","folder":true,"children":[{"title":"압도적 적의 예고","synopsis":"곧 들이닥칠 적의 규모·잔혹성을 제시(척후 보고, 약탈당한 이웃 마을, 최후통첩). 도망이 불가능하거나 도망치지 않을 이유를 명확히."},{"title":"버틸 것인가","synopsis":"지킬 것이냐 떠날 것이냐의 선택. 남기로 한 자들의 면면과 동기를 보여 '왜 이 자리를 사수하는가'를 못박아라."},{"title":"요새화","synopsis":"한정 자원으로 함정·바리케이드·역할 분담을 준비하는 과정. 공간의 구조(병목, 사각, 탈출로)를 독자에게 각인 — 나중 액션의 무대가 된다."}]},{"title":"2막 — 파상공세","synopsis":"거듭되는 공격과 점증하는 손실.","folder":true,"children":[{"title":"첫 번째 물결","synopsis":"준비한 함정·전술이 통하는 통쾌한 첫 격퇴. 그러나 적이 약점을 학습함을 암시해 다음의 불안을 깐다."},{"title":"소모전","synopsis":"탄약·식수·인원이 줄어드는 자원 고갈의 긴장. 부상자 처치, 다음 공격 전 잠깐의 휴식에서 인간 드라마를 넣어라."},{"title":"방어선 돌파","synopsis":"미드포인트: 적이 약점을 파고들거나 내부 배신/실수로 한 구역이 뚫린다. 후퇴해 더 좁은 최종 방어선으로 물러나며 절박함을 끌어올려라."},{"title":"결정적 희생","synopsis":"핵심 인물이 시간을 벌기 위해 자신을 던진다. 이 희생의 의미가 클라이맥스의 동력이 되도록 감정선을 깔아라."}]},{"title":"3막 — 최후의 보루","synopsis":"마지막 공세와 그 결말.","folder":true,"children":[{"title":"총공격","synopsis":"적의 전력 총동원에 맞선 최종 방어전. 남은 모든 수단·함정·필사의 백병전. 공간을 최대한 활용한 클라이맥스 액션."},{"title":"구원 혹은 산화","synopsis":"정해진 시간이 다 되어 지원군이 도착하거나, 끝내 함락되되 적에게 막대한 대가를 치르게 한다. 어느 쪽이든 '버틴 의미'를 증명하라."},{"title":"남은 자리","synopsis":"폐허가 된 전장과 생존자(혹은 전설로 남은 자들). 그들이 지킨 것이 무엇이었는지로 여운을 남겨라."}]}]},{"id":"g9-infiltration-heist","category":"액션·전쟁","name":"잠입·탈취 작전 구조","desc":"치밀한 계획으로 삼엄한 시설/적진에 잠입해 목표(인물 구출/물건 탈취/암살/정보)를 빼내 빠져나오는 작전형 액션. 스파이 액션, 군사 첩보, 케이퍼 액션 계열. 독자는 계획의 정교함, 들킬 듯 말 듯한 서스펜스, 계획이 틀어졌을 때의 즉흥 대응을 기대한다.","beats":[{"title":"1막 — 계획 수립","synopsis":"목표 부여와 팀 구성, 작전 설계.","folder":true,"children":[{"title":"표적과 판돈","synopsis":"무엇을, 왜 빼내야 하는지와 실패 시의 끔찍한 대가를 제시. 목표 시설의 '난공불락' 명성을 강조해 난도를 띄워라."},{"title":"스페셜리스트 소집","synopsis":"각기 다른 전문 기술(해커, 침투, 위장, 폭파, 저격)을 가진 팀을 모은다. 각자의 특기를 한 장면씩 보여 나중 작전에서 회수할 복선을 깔아라."},{"title":"정찰과 청사진","synopsis":"표적 시설의 경비·동선·약점을 정찰하고 작전 계획을 세운다. 독자에게 '계획'을 보여줘라 — 곧 이 계획이 어떻게 어긋나는지가 재미가 된다."}]},{"title":"2막 — 침투와 균열","synopsis":"잠입 실행과 예상 밖 변수.","folder":true,"children":[{"title":"내부 침투","synopsis":"위장·은밀 행동으로 내부에 들어가는 서스펜스. 사소한 디테일(출입증, 암호, 타이밍) 하나가 들통을 가르는 조마조마함을 연출하라."},{"title":"계획대로… 까진","synopsis":"초반은 계획이 멋지게 맞아떨어진다. 그러나 예측 못한 변수(경비 교대 변경, 내부 배신자, 표적 이동)가 등장해 작전이 흔들리기 시작."},{"title":"발각과 즉흥","synopsis":"미드포인트: 결국 들킨다. 은밀 작전이 총격·추격의 정면 액션으로 전환. 계획이 무너진 자리에서 팀의 임기응변과 진짜 실력이 빛난다."},{"title":"배신의 카드","synopsis":"팀 내 배신, 의뢰인의 이중성, 표적의 정체 반전 중 하나로 판이 뒤집힌다. '진짜 목표는 따로 있었다'식 반전이 효과적."}]},{"title":"3막 — 탈출","synopsis":"목표 확보 후의 탈출과 결착.","folder":true,"children":[{"title":"확보, 그리고 추격","synopsis":"목표물을 손에 넣지만 곧바로 시설 전체·추격대가 따라붙는다. 시간제한(자폭 타이머, 봉쇄 임박)을 걸어 탈출의 긴박감을 극대화."},{"title":"마지막 관문","synopsis":"탈출 직전의 최대 장애물(최종 보스, 닫히는 출구, 희생을 요구하는 선택). 앞서 깐 특기·복선을 회수해 돌파하라."},{"title":"성과와 청구서","synopsis":"탈출 성공과 그 대가(잃은 동료, 드러난 진실, 다음 위협). 작전의 진짜 의미를 정산하며 여운 혹은 후속 떡밥을 남겨라."}]}]},{"id":"g10-tutorial-tower-climb","category":"게임판타지·LitRPG","name":"튜토리얼 탑 등반형 (스테이지 클리어)","desc":"강제 게임화된 세계나 무한 탑/던전에 갇힌 주인공이 한 층(스테이지)씩 돌파하며 성장하는, '솔로 레벨링'·'전지적 독자 시점'·'나혼자만 레벨업'류의 가장 전형적인 LitRPG 골격. 각 층의 규칙 해독 → 공략 → 보상 획득의 사이클을 반복하며, 층이 올라갈수록 규칙이 잔혹·기괴해지는 에스컬레이션이 핵심. 시스템 메시지의 단호함과 죽음의 실시간성이 긴장을 만든다.","beats":[{"title":"1막 — 균열: 일상이 게임이 되다","synopsis":"평범한 일상이 시스템 강림으로 붕괴하고, 주인공이 첫 죽음의 위협 앞에서 각성하는 도입부.","folder":true,"children":[{"title":"강림 — 시스템 메시지의 첫 출현","synopsis":"갑작스러운 푸른 창/공지로 세계 규칙이 바뀐다. '튜토리얼이 시작됩니다' 같은 비정한 알림과 카운트다운을 묘사. 주변 사람들의 패닉, 첫 사망자, 시스템의 무자비함(설명 없음)을 통해 독자에게 '이 세계는 봐주지 않는다'를 각인시킨다."},{"title":"최초의 죽을 고비 — 1층의 함정","synopsis":"튜토리얼/1층의 첫 과제를 제시. 주인공이 남들과 달리 상태창·규칙의 빈틈을 읽어내며 가까스로 생존하는 장면. 이때 '왜 나만 이게 보이는가/되는가'라는 특이점(고유 스킬·전생 기억·관전자 능력 등)의 떡밥을 심는다."},{"title":"각성 — 남다른 한 수","synopsis":"남들은 모르는 메타지식·히든 옵션·페널티 회피법을 처음으로 적극 활용해 압도적 결과를 낸다. 첫 레벨업/첫 스킬 획득의 카타르시스를 상태창으로 직접 보여주고, 주인공의 차별점(약자 시작·정보 우위·성장 가속)을 확립한다."}]},{"title":"2막 — 등반: 층의 규칙을 깨다","synopsis":"층마다 다른 게임 규칙을 해독·공략하며 동료와 적, 길드 정치가 얽히는 본편의 반복 사이클.","folder":true,"children":[{"title":"규칙 해독 — 이 층의 게임은 무엇인가","synopsis":"새 층 진입 시 독특한 룰(예: 거짓말 금지, 술래잡기, 경매, 배신 유도)을 제시. 표면 규칙 뒤의 '진짜 승리 조건'을 주인공이 추리해 내는 과정을 보여준다. 정직한 공략과 꼼수의 차이로 주인공의 영리함을 부각."},{"title":"파티·라이벌 — 인간이 더 위험하다","synopsis":"동료를 영입하거나 다른 공략자/길드와 충돌. 한정 보상을 둘러싼 PvP, 배신, 동맹의 딜레마를 배치해 '몬스터보다 사람이 무섭다'는 게임판타지 특유의 긴장을 살린다."},{"title":"보스전 — 패턴 파훼와 스탯 체크","synopsis":"층의 보스를 정면 묘사. 보스의 페이즈/패턴을 관찰→파훼하는 과정을 게임적 디테일(쿨타임, 약점 속성, 도트 데미지)로 구체화. 빠듯한 자원 관리와 마지막 한 방의 역전을 보여준다."},{"title":"보상과 성장 — 새 빌드의 완성","synopsis":"클리어 보상(스킬북·아이템·칭호·히든 클래스)을 획득하고 빌드를 재설계. 다음 층을 위한 준비와 함께, 보상이 불러올 새로운 문제(주목·견제·부작용)의 씨앗을 심는다."}]},{"title":"3막 — 정점: 탑의 진실과 최후의 층","synopsis":"탑/시스템의 기원과 운영자의 정체가 드러나고, 주인공이 규칙 자체를 거스르며 최종 돌파에 도전하는 결말.","folder":true,"children":[{"title":"관리자 조우 — 게임을 만든 자","synopsis":"탑 상층/관리자와의 접촉으로 시스템의 목적(외계 침공 선별, 차원 전쟁 징병, 신들의 유희 등)이 폭로된다. 지금까지의 고난이 누군가의 의도였음을 밝혀 분노와 동기를 증폭."},{"title":"규칙 깨기 — 시스템을 역이용","synopsis":"주인공이 그동안 모은 메타지식·금단의 빌드로 시스템의 전제 자체를 부순다(버그 악용, 룰 해킹, 운영자 권한 탈취). 정해진 공략이 아닌 '판을 뒤집는 수'로 클라이맥스를 만든다."},{"title":"최종 돌파 — 마지막 층과 대가","synopsis":"최상층/최종 보스를 격파하고 세계를 원래대로 되돌리거나 새 질서를 세운다. 희생·페널티 정산·동료의 운명을 결산하고, 게임이 끝난 뒤 남은 능력·후일담으로 여운을 남긴다."}]}]},{"id":"g10-isekai-second-life","category":"게임판타지·LitRPG","name":"이세계 전생·정착형 (느긋한 두 번째 인생)","desc":"현대인이 게임적 규칙(스탯·스킬·길드·퀘스트)이 작동하는 이세계로 전생/소환되어 새 삶에 정착하는 구조. '던전 디펜스'의 음모형이 아닌, 오히려 '치트 능력으로 슬로우 라이프'·내정·상단 경영 계열의 결을 대표. 압도적 스타트 → 정착·관계 형성 → 영지/조직 경영 → 외부 위협 격퇴로 이어지며, 전투보다 '구축과 운영의 쾌감'과 일상 힐링이 동력이다.","beats":[{"title":"1막 — 전생: 새 몸, 새 규칙","synopsis":"전생/소환과 동시에 얻은 치트 능력으로 이세계의 게임적 룰을 빠르게 파악하고 생존 기반을 마련하는 도입.","folder":true,"children":[{"title":"전이의 순간 — 죽음과 환생","synopsis":"트럭/과로사/소환진 등으로 현생을 마감하고 이세계에서 눈뜬다. 새 신분(영아·노예·평민·이방인)과 함께 부여된 상태창·고유 스킬을 확인. 전생 지식과 이세계 룰의 격차를 첫 장면에서 대비시킨다."},{"title":"치트 확인 — 이건 사기다","synopsis":"감정 스킬·무한 인벤토리·전직 자유 같은 능력을 시험해 보며 이 세계 기준으로 얼마나 비정상인지 자각. 평범한 행동(요리·연금·감정)이 현지인에겐 기적임을 보여주어 격차의 쾌감을 설계한다."},{"title":"첫 거점 — 생존에서 정착으로","synopsis":"길드 등록, 첫 의뢰, 첫 수입으로 생활 기반을 마련. 현지 화폐·등급제·길드 시스템을 자연스럽게 설명하고, 앞으로 키울 거점(가게·집·동료)의 단초를 잡는다."}]},{"title":"2막 — 정착: 사람과 일상을 모으다","synopsis":"동료·가족 같은 관계망을 만들고 기술·상업·내정으로 거점을 키우며 평온한 일상 속 작은 사건을 해결하는 본편.","folder":true,"children":[{"title":"동료 영입 — 운명적 만남","synopsis":"노예 해방·구출·고용을 통해 핵심 동료(짐승인·전직 기사·정령 등)를 합류. 각자의 사연과 충성의 계기를 만들고, 파티/가족 구성으로 작품의 정서적 중심을 세운다."},{"title":"기술 무쌍 — 전생 지식의 상용화","synopsis":"현대 지식(위생·요리·제조·금융)을 이세계에 도입해 상품·서비스로 발전시키는 과정. 매출·평판 상승을 게임적 수치(상단 레벨, 명성치)로 가시화해 경영의 재미를 살린다."},{"title":"소소한 위기 — 일상의 가시","synopsis":"사기꾼, 텃세 부리는 토착 세력, 폭주 마물 같은 중간 규모 갈등을 등장시켜 긴장을 환기. 주인공이 무력이 아닌 지혜·인맥·약간의 치트로 해결하며 정착의 깊이를 더한다."},{"title":"거점 성장 — 마을이 도시가 되다","synopsis":"영지·상단·길드가 확장되는 몽타주. 인프라(농업·길·방어)와 인구가 늘고, 주인공의 영향력이 지역으로 퍼진다. 번영의 이면에 외부의 시선과 야심을 끌어들이는 복선을 깐다."}]},{"title":"3막 — 수호: 평온을 지키는 대가","synopsis":"쌓아 올린 일상과 거점을 노리는 거대 위협이 닥치고, 그동안 키운 동료·기술·세력을 총동원해 막아내며 새 균형에 안착하는 결말.","folder":true,"children":[{"title":"위협의 도래 — 평화의 끝","synopsis":"왕국의 탐욕, 마왕군 침공, 타국 침략 등 거점 전체를 위협하는 사건 발발. 그간 모은 모든 것이 인질이 되며, 더는 느긋할 수 없는 결전의 명분을 부여한다."},{"title":"총력전 — 모든 빌드의 결산","synopsis":"동료들의 성장, 도입한 기술, 영지 방어 시스템이 톱니바퀴처럼 맞물려 적을 격퇴하는 대규모 전투/공성. 주인공의 치트가 결정타가 되지만, 승리의 진짜 열쇠는 '함께 키운 공동체'임을 보여준다."},{"title":"새로운 일상 — 더 큰 평온","synopsis":"위협을 물리치고 더 넓고 안전한 보금자리를 확립. 동료·가족과의 후일담, 다음 모험의 여지를 남기며 '두 번째 인생은 행복하다'는 장르 약속을 충족한다."}]}]},{"id":"g10-full-dive-vrmmo","category":"게임판타지·LitRPG","name":"풀다이브 VRMMO형 (현실과 게임의 이중생활)","desc":"'소드 아트 온라인'·'달빛조각사'·'오버로드'류로 대표되는, 가상현실 게임에 '접속'해 플레이하는 구조. 핵심은 게임 안 활약과 게임 밖 현실(랭킹·길드 정치·현질·생계·접속 종료)의 이중 레이어. 현실의 동기(가난·명예·우정)가 게임 내 행동을 추동하고, 게임 내 성취가 현실을 바꾸는 상호작용이 동력. 데스게임화 변주(로그아웃 불가)도 이 골격의 하위 변종이다.","beats":[{"title":"1막 — 접속: 가상세계에 발을 딛다","synopsis":"현실의 결핍을 안은 주인공이 VR게임에 입문해 독자적 플레이 스타일과 첫 성취를 만드는 도입.","folder":true,"children":[{"title":"현실의 무게 — 접속하는 이유","synopsis":"주인공의 현실 상황(생계, 콤플렉스, 상실, 동경)을 제시해 게임에 몰입하는 동기를 부여. 단순 재미가 아니라 '여기서만은 다르고 싶다/벌어야 한다'는 절박함이나 갈망을 깔아 이중생활의 축을 세운다."},{"title":"캐릭터 생성 — 남들이 안 가는 길","synopsis":"직업·종족·스탯을 결정하는 장면에서 비주류 빌드(생산직, 기피 클래스, 페널티 종족, 히든 직업)를 택한다. 통념을 거스르는 선택의 위험과 잠재력을 보여주어 차별화의 출발점을 만든다."},{"title":"초반 두각 — 발상의 승리","synopsis":"정석을 벗어난 운용·시스템 악용·집요한 노가다로 초반부터 주목받는 결과를 낸다. 첫 랭킹 진입·첫 유니크 보상·영상 화제성 등으로 '이 플레이어는 다르다'는 평판을 게임 안팎에 형성한다."}]},{"title":"2막 — 명성: 길드, 랭킹, 그리고 현실","synopsis":"게임 내 세력 다툼과 대규모 콘텐츠를 헤쳐가는 동시에, 현실의 정체·인간관계가 게임과 충돌하며 이중생활의 긴장이 고조되는 본편.","folder":true,"children":[{"title":"길드 정치 — 거대 세력의 등장","synopsis":"대형 길드·랭커 연합·기업 팀과의 동맹/대립. 영토 점령전, 자원 독점, 정보전 같은 정치적 갈등을 통해 게임을 '사회'로 묘사한다. 주인공이 약소 세력으로 거대 권력에 맞서는 구도를 잡는다."},{"title":"레이드·공략 — 미답 콘텐츠 돌파","synopsis":"월드 퍼스트 보스, 미공략 던전, 대규모 레이드를 도전. 공략 정보의 비대칭, 파티 조합, 페이즈 파훼를 게임적 디테일로 묘사하고, 주인공 팀의 창의적 전략으로 최초 클리어의 쾌감을 만든다."},{"title":"현실 교차 — 가면이 벗겨지다","synopsis":"게임 속 인물과 현실에서 마주치거나(동급생·동료·라이벌), 주인공의 정체가 노출되는 사건. 오프라인 만남, 대회 출전, 기업 스카우트 등으로 두 세계를 충돌시켜 드라마를 강화한다."},{"title":"위기 — 밴·해킹·접속 위협","synopsis":"계정 정지, 핵 유저, 운영진의 음모, 혹은 로그아웃 불가 사태 등 '게임 시스템 차원의 위기'를 도입. 단순 PvP를 넘어 플레이어의 존립 자체를 흔드는 위협으로 판을 키운다."}]},{"title":"3막 — 결전: 두 세계의 정점","synopsis":"게임 내 최강자/최종 콘텐츠와 현실의 적대 세력을 동시에 제압하며, 게임에서 얻은 것이 현실의 삶을 바꾸는 결말.","folder":true,"children":[{"title":"정점의 대결 — 최강 랭커전","synopsis":"라이벌 랭커·정점 길드·게임의 숨은 보스와의 최종 승부. 그간 갈고닦은 빌드와 전략, 팀워크의 총결산을 대규모 PvP/레이드로 묘사해 게임 내 서사의 절정을 찍는다."},{"title":"현실의 청산 — 막후를 끝내다","synopsis":"게임을 악용하던 현실의 세력(부정 기업, 협박범, 음모 운영진)을 게임 내 성과를 지렛대 삼아 무너뜨린다. 두 세계의 갈등을 한 줄기로 모아 동시에 해소한다."},{"title":"로그아웃 — 바뀐 현실","synopsis":"게임에서의 성취가 현실의 부·관계·자아를 실제로 변화시키며 마무리. 데스게임 변주라면 귀환의 대가와 후유증을, 일반형이라면 다음 시즌/확장팩의 여지를 남긴다."}]}]},{"id":"g10-regression-meta-mastery","category":"게임판타지·LitRPG","name":"회귀 메타지식 무쌍형 (다 아는 자의 두 번째 회차)","desc":"한국 웹소설 황금기를 정의한 '회귀형' LitRPG. 멸망·실패를 경험한 주인공이 과거로 돌아가(혹은 게임을 재시작해) 미래 정보를 가지고 최적 루트를 선점하는 구조. '전지적 독자 시점'·'데못죽'류의 핵심. 쾌감의 원천은 정보 비대칭(주인공만 미래·히든을 안다)과 효율 극대화. 단, 회귀로 '나비효과'가 일어나 알던 미래가 어긋나는 변수가 후반 긴장을 만든다.","beats":[{"title":"1막 — 회귀: 실패를 되감다","synopsis":"비참한 결말을 맞은 주인공이 과거로 돌아와, 미래 지식을 무기로 남보다 먼저 출발선을 끊는 도입.","folder":true,"children":[{"title":"멸망의 기억 — 첫 회차의 끝","synopsis":"세계 멸망·동료의 죽음·자신의 무력함 등 첫 회차의 파국을 강렬히 제시. 이 한이 회귀의 동기이자 독자에게 '무엇을 막아야 하는가'라는 목표를 각인시킨다. 죽음/리셋의 순간을 클리프행어로."},{"title":"회귀 자각 — 기회는 다시 왔다","synopsis":"과거 시점에서 눈뜬 주인공이 자신이 미래를 안다는 사실을 검증한다. 곧 일어날 사건을 정확히 예언/회피해 보이며 '이번엔 다르다'는 확신과 독자 신뢰를 동시에 구축한다."},{"title":"선점 — 남보다 빠른 한 수","synopsis":"아직 아무도 모르는 히든 클래스·노다지 던전·미래의 핵심 아이템을 가장 먼저 확보. 초반부터 격차를 벌리며, 첫 회차에서 죽었던 인연을 살리는 등 '바로잡기'를 시작한다."}]},{"title":"2막 — 최적화: 아는 미래를 수확하다","synopsis":"미래 정보로 인재·자원·사건을 효율적으로 수확하며 세력을 키우되, 회귀로 인한 변화가 조금씩 미래를 비틀기 시작하는 본편.","folder":true,"children":[{"title":"인재 회수 — 묻혀 있던 보석들","synopsis":"첫 회차에선 적이거나 무명이었던 강자·천재를 미리 포섭. 그들의 숨은 가치와 미래의 활약을 주인공만 알기에, 영입 과정의 정보 우위와 의외성을 살린다."},{"title":"사건 선취 — 재앙을 기회로","synopsis":"다가올 대형 사건(던전 브레이크, 배신, 경매, 전쟁)을 미리 알고 판을 짜둔다. 남들이 당황할 때 주인공은 이미 대비를 끝내 압도하는, 회귀물 특유의 '예정된 무쌍'을 연출한다."},{"title":"나비효과 — 미래가 어긋나다","synopsis":"주인공의 개입으로 알던 미래가 변질되기 시작한다. 살렸어야 할 사람, 죽었어야 할 적, 예상과 다른 전개가 등장해 '정보 우위'가 흔들리는 첫 균열을 만든다. 긴장의 전환점."},{"title":"추격자 — 또 다른 회귀자/변수","synopsis":"주인공 외에도 미래를 아는 존재(또 다른 회귀자, 예언자, 시스템 관리자)나 주인공을 경계하는 세력이 등장. 정보 독점이 깨지며 두뇌 싸움과 견제가 본격화된다."}]},{"title":"3막 — 개변: 정해진 멸망을 부수다","synopsis":"어긋난 미래 속에서 첫 회차의 파국을 막기 위한 최종 결전을 벌이고, 회귀의 진짜 비밀과 대가를 정산하는 결말.","folder":true,"children":[{"title":"예정된 파국 — 그날이 온다","synopsis":"첫 회차에서 모든 걸 무너뜨린 그 사건/적이 다시 닥쳐온다. 그러나 주인공의 개입으로 형태가 바뀌어, 단순한 미래 지식만으로는 이길 수 없는 미지의 변수가 더해진다."},{"title":"회귀의 비밀 — 왜 돌아왔는가","synopsis":"회귀의 근원(시스템의 의도, 신의 시험, 시간 역행의 대가)이 밝혀진다. 회귀가 공짜가 아니었음, 혹은 반복되는 루프의 진실이 드러나며 최종 동기와 희생의 무게를 부여한다."},{"title":"최후의 개변 — 새 미래를 쓰다","synopsis":"쌓아온 세력·인연·미래 지식의 잔여분을 총동원해 정해진 멸망을 부수고 새로운 결말을 쟁취. 첫 회차에서 잃었던 모든 것을 되찾거나, 더 큰 대가로 세계를 구하며 회귀 서사를 완결한다."}]}]},{"id":"g10-system-villain-rise","category":"게임판타지·LitRPG","name":"악역·다크 시스템형 (시스템을 쥔 정복자)","desc":"'던전 디펜스'·'데몬 군주'·악역 빙의류로 대표되는, 선역 영웅이 아닌 마왕·던전 마스터·악역에 빙의/각성하는 안티히어로 구조. 시스템(던전 관리, 소환, 패널티)을 음모와 효율로 운용하며 세력을 키운다. 핵심 결은 도덕적 회색지대·냉혹한 계략·하이리스크 거래. 영웅물의 '구원'이 아니라 '지배와 생존', 그리고 비정함 속 인간성의 줄타기가 매력이다.","beats":[{"title":"1막 — 빙의: 파멸이 예정된 자리","synopsis":"죽거나 멸망할 운명의 악역·마왕에 빙의/각성한 주인공이 시스템을 무기로 생존을 도모하는 도입.","folder":true,"children":[{"title":"최악의 시작 — 사형대 위의 배역","synopsis":"주인공이 곧 죽거나 토벌당할 악역(망국의 마왕, 처형 직전 영애, 버려진 던전 마스터)에 빙의함을 자각. 원작/현 상황이 얼마나 절망적인지 제시해 '평범한 성장으론 못 산다'는 절박함을 세운다."},{"title":"다크 시스템 — 손에 쥔 칼","synopsis":"선역의 깔끔한 시스템과 달리, 대가가 따르는 어두운 시스템(영혼 거래, 마물 소환, 희생 제물, 공포 수치)을 확인. 강력하지만 비윤리적인 능력의 룰을 보여주어 도덕적 줄타기의 토대를 만든다."},{"title":"첫 계략 — 약자의 독수","synopsis":"정면 승부로는 이길 수 없기에 정보·기만·자원 활용으로 첫 위기를 모면. 잔혹하지만 영리한 한 수로 '이 주인공은 손을 더럽힐 줄 안다'는 톤을 확립하고 작은 첫 세력을 확보한다."}]},{"title":"2막 — 확장: 세력을 빚어내다","synopsis":"던전·부하·동맹을 음모와 거래로 키우며 영웅 진영·경쟁 마왕과 대립하고, 비정함과 인간성 사이에서 흔들리는 본편.","folder":true,"children":[{"title":"전력 양성 — 충성인가 공포인가","synopsis":"마물 군단·휘하 부하·세뇌/계약 동료를 늘린다. 두려움으로 부리는 자와 진심으로 따르는 자를 대비시켜, 주인공의 통치 방식과 안티히어로로서의 색을 규정한다."},{"title":"영웅과의 충돌 — 정의의 칼끝","synopsis":"주인공을 '악'으로 규정하고 토벌하러 오는 용사·기사단·교단과 대결. 도덕적으로 우월하다 믿는 적의 위선·허점을 드러내며, 독자가 악역 주인공을 응원하게 만드는 명분을 구축한다."},{"title":"악마의 거래 — 대가의 무게","synopsis":"급성장을 위해 위험한 거래(상위 악마와의 계약, 금기의 의식, 도시 하나의 희생)를 감행. 얻는 힘과 치러야 할 대가를 저울질하는 장면으로 하이리스크의 긴장과 죄책을 부여한다."},{"title":"흔들림 — 남은 인간성","synopsis":"냉혹한 길 위에서 주인공이 차마 넘지 못하는 선, 지키고 싶은 존재가 드러난다. 완전한 악도 위선적 선도 아닌 회색의 인물상을 심화해 캐릭터에 깊이를 더한다."}]},{"title":"3막 — 군림: 정점에 서는 대가","synopsis":"최강 세력 또는 시스템의 진짜 주인과 충돌하며, 지배자로 군림하거나 자신이 치른 대가를 정산하는 결말.","folder":true,"children":[{"title":"최강과의 대결 — 진짜 마왕/신","synopsis":"주인공보다 압도적인 상위 존재(원작 최종보스, 천계, 시스템의 창조자)와 격돌. 그동안 쌓은 비정한 전력과 계략, 위험한 거래의 결실을 모두 쏟아붓는 클라이맥스를 만든다."},{"title":"대가의 청산 — 빚을 갚을 시간","synopsis":"지금껏 미뤄둔 거래의 청구서(영혼, 부하의 배신, 자기 소멸의 위기)가 돌아온다. 주인공이 비정함의 대가를 직면하고, 그것을 받아들이거나 마지막 술수로 비트는 결정을 내린다."},{"title":"지배자의 결말 — 옥좌의 무게","synopsis":"세계를 정복/장악하거나, 모든 걸 건 도박 끝에 새 질서를 세운다. 영웅적 해피엔딩이 아닌 안티히어로다운 결말(고독한 옥좌, 인간성의 회복, 혹은 더 큰 악의 청산)로 마무리한다."}]}]},{"id":"g10-hidden-class-underdog","category":"게임판타지·LitRPG","name":"히든 클래스 약자반전형 (쓰레기 직업의 역설)","desc":"최약체·꽝 직업·말단 NPC로 시작한 주인공이 남들이 버린 시스템의 빈틈을 파고들어 최강 빌드를 완성하는 구조. '쓰레기 스킬'·생산직 무쌍·페널티 역이용·노가다 성장류를 대표. 핵심 쾌감은 '저평가된 것의 재발견'과 빌드 설계의 지적 만족. 단순 치트가 아니라 노력·연구·발상의 전환으로 격차를 뒤집는, 게임 메커니즘 자체가 주인공인 결이다.","beats":[{"title":"1막 — 바닥: 모두가 비웃는 출발","synopsis":"최악의 직업·스킬·환경을 배정받아 조롱당하던 주인공이 남들이 못 본 가능성을 발견하는 도입.","folder":true,"children":[{"title":"꽝 뽑기 — 쓰레기 판정","synopsis":"전직/뽑기/각성에서 최하위 직업·무쓸모 스킬·쓰레기 아이템을 얻어 주변의 비웃음과 절망을 산다. 시스템 설명상 명백히 '약한' 능력임을 보여주어 반전의 낙차를 최대로 키운다."},{"title":"숨은 결 — 모두가 놓친 한 줄","synopsis":"스킬 설명의 사소한 조건, 무시된 옵션, 페널티의 뒷면에서 주인공만이 활용 가능성을 포착한다. '이거 사실 사기 아냐?'라는 첫 단서를 영리한 관찰로 발견하는 결정적 장면."},{"title":"검증 — 가설을 시험하다","synopsis":"발견한 가능성을 작은 실험으로 검증해 첫 성과를 낸다. 미미하지만 분명한 차이를 만들어 독자에게 '이 빌드는 된다'는 확신을 주고, 본격 연구의 동기를 부여한다."}]},{"title":"2막 — 연마: 버려진 길을 갈고닦다","synopsis":"꼼수가 아닌 깊은 연구와 노가다로 약점을 강점으로 바꾸며, 주변의 평가가 조롱에서 경악으로 뒤집히는 본편.","folder":true,"children":[{"title":"빌드 설계 — 시너지의 발견","synopsis":"쓰레기로 평가된 능력에 다른 스킬·아이템·직업 조합을 더해 폭발적 시너지를 만든다. 메커니즘을 파고드는 계산과 조합의 묘를 보여주어 지적 쾌감을 극대화한다."},{"title":"노가다 — 한계를 가는 노력","synopsis":"치트가 아닌 반복·숙련·집요한 파밍으로 능력을 한계까지 끌어올린다. 남들이 비효율이라 외면한 길을 끝까지 파서 임계점을 돌파하는, 노력형 성장의 카타르시스를 연출한다."},{"title":"재평가 — 비웃음이 경악으로","synopsis":"공개 시험·던전·대회에서 완성된 빌드를 처음 선보여 주변을 뒤집는다. 무시하던 자들의 충격, 스카우트 제의, 화제성 폭발로 '약자가 강자가 되는 순간'의 쾌감을 터뜨린다."},{"title":"견제 — 튀어나온 못","synopsis":"두각을 드러낸 주인공을 기득권·라이벌·길드가 견제·방해·모방하려 든다. 빌드의 비밀을 지키거나 한 단계 더 진화시켜 따돌리는 두뇌전으로 갈등을 고조시킨다."}]},{"title":"3막 — 정점: 약점이 곧 최강이 되다","synopsis":"쓰레기 직업의 잠재력이 한계까지 개화해, 정석 강자들조차 못 푸는 난관을 주인공만의 방식으로 돌파하는 결말.","folder":true,"children":[{"title":"전직의 진실 — 히든의 정체","synopsis":"주인공의 직업이 사실은 봉인된 전설/숨겨진 상위 클래스의 입구였음이 밝혀진다. 왜 이게 '쓰레기'로 위장되어 있었는지, 그 비밀과 진정한 잠재력을 폭로한다."},{"title":"불가능 공략 — 나만의 해법","synopsis":"정석 최강 빌드로도 못 깬 난제(공략 불가 보스, 미답 던전, 시스템 버그)를 주인공만의 비대칭 빌드로 돌파한다. '약점이라 불린 것'이 유일한 정답이 되는 통쾌한 역설을 구현한다."},{"title":"정상 — 버려진 자의 왕좌","synopsis":"한때 꽝이라 비웃음 받던 주인공이 최강자/유일무이한 존재로 인정받으며 마무리. 빌드의 완성과 후일담, 그리고 '저평가된 것의 가치'라는 주제를 마지막까지 관철한다."}]}]},{"id":"g11-revenge-corporate-rise","category":"현대판타지·회귀","name":"회귀 복수·재벌 재건형","desc":"배신당하고 몰락(혹은 사망)한 주인공이 인생의 특정 시점으로 회귀해, 미래 지식을 무기로 자신을 짓밟은 가문·기업·세력에 차근차근 복수하며 정점에 오르는 구조. '재벌집 막내아들', '내 남편과 결혼해줘' 류의 복수 사이다 라인을 대표한다. 핵심 쾌감은 '아는 미래'의 정보 비대칭과 단계적 응징.","beats":[{"title":"1부 — 배신과 회귀의 각인","synopsis":"주인공이 무엇을 잃었고 누구에게 당했는지, 그리고 회귀가 무엇을 가능케 하는지 독자에게 각인시키는 도입부.","folder":true,"children":[{"title":"최후의 순간","synopsis":"현재(회귀 전) 시점의 몰락한 주인공을 보여준다. 토사구팽당한 직후의 죽음 직전 장면, 또는 모든 것을 빼앗긴 바닥. 누가 배신했는지(가문 형제, 회장, 동업자)와 빼앗긴 것(상속, 회사, 연인)을 구체적 대사·물증으로 못 박는다."},{"title":"눈을 뜨니 과거","synopsis":"특정 과거 시점(20년 전, 입사 첫날, 사고 직전)에서 깨어남. 거울·날짜·낯선 젊은 몸으로 회귀를 자각하는 클리셰 활용. 단, 회귀 자각을 '믿기 힘듦→증명' 순으로 빠르게 처리해 독자 답답함을 막는다."},{"title":"미래 지식의 첫 검증","synopsis":"곧 일어날 사건(주가 폭등 종목, 사고, 누군가의 죽음)을 하나 맞혀 회귀가 진짜임을 주인공과 독자 모두에게 확정. 작은 첫 베팅으로 종잣돈·신뢰·정보 우위를 동시에 확보하는 출발점을 만든다."},{"title":"복수 대상 재배치","synopsis":"회귀 전과 달리, 지금은 적들이 아직 약하거나 주인공을 우습게 본다는 점을 부각. 적의 미래 약점·비리·실수 타임라인을 주인공 머릿속 '공략집'으로 정리해 장기 빌드업을 예고한다."}]},{"title":"2부 — 기반 축적과 첫 응징","synopsis":"돈·인맥·정보라는 세 자원을 미래 지식으로 압축 성장시키고, 만만한 적부터 단계적으로 무너뜨린다.","folder":true,"children":[{"title":"종잣돈에서 자본으로","synopsis":"투자·사업 아이템 선점(IT 붐, 부동산, 신기술 특허)으로 자본을 기하급수적으로 불린다. 숫자가 커지는 쾌감과 함께, 미래를 안다는 이유만으로 모든 게 쉬워 보이지 않도록 실행력·인복의 디테일을 넣는다."},{"title":"조력자 영입","synopsis":"회귀 전 능력은 있었으나 빛 못 본 인재, 혹은 미래에 거물이 될 무명을 미리 포섭. 주인공의 '사람 보는 눈'을 보여주며 적진보다 빠른 세력화를 만든다."},{"title":"1차 표적 격파","synopsis":"복수 라인의 말단(중간 보스급 배신자, 하청 악역, 약혼 파탄의 주범)을 합법적·치밀하게 몰락시킨다. 폭력이 아닌 정보·자본·법으로 무너뜨리는 사이다를 연출한다."},{"title":"본진의 경계 시작","synopsis":"주인공의 급부상에 최종 빌런(회장, 종가, 거대 자본)이 처음으로 그를 변수로 인식. 그러나 아직 정체·의도를 모른다는 정보 비대칭을 유지한다."}]},{"title":"3부 — 본격 권력 다툼","synopsis":"주인공이 적의 본진과 동급 체급으로 충돌하기 시작하고, 미래 지식이 어긋나는 '나비효과'로 긴장이 상승한다.","folder":true,"children":[{"title":"나비효과의 역습","synopsis":"주인공의 개입으로 미래가 바뀌어, 알던 사건이 빗나가거나 적이 다른 수를 둔다. 회귀 치트의 한계를 드러내 '아는 미래'에만 의존하지 못하게 하고 실력 증명 구간을 만든다."},{"title":"내부의 적·이중 배신","synopsis":"포섭했던 인물의 흔들림, 혹은 회귀 전과 다른 인물의 변심. 복수극의 신뢰 테마를 비틀어, 주인공이 사람을 다루는 방식을 시험받는다."},{"title":"정면 승부 선언","synopsis":"경영권 분쟁·인수합병·여론전 등 큰 판에서 적과 정면 충돌. 그동안 쌓은 자본·인맥·정보를 총동원하는 중간 클라이맥스를 배치한다."}]},{"title":"4부 — 최종 복수와 즉위","synopsis":"최종 빌런을 무너뜨리고, 빼앗겼던 모든 것을 회수하며 주인공이 새 질서의 정점에 서는 결말.","folder":true,"children":[{"title":"약점 일제 회수","synopsis":"그동안 모아온 적의 비리·치부·과거(회귀 전 지식 + 현재 수집)를 한 번에 터뜨려 최종 빌런을 합법적으로 파멸시킨다. 복수의 카타르시스를 정점에서 폭발시킨다."},{"title":"원점 회수","synopsis":"회귀 전 빼앗겼던 바로 그것(상속, 회사, 자리, 명예)을 상징적으로 되찾는 장면. 1부 도입의 굴욕 장면과 수미상관으로 대비시킨다."},{"title":"새 질서의 정점","synopsis":"주인공이 권력·부의 최상단에 서고, 회귀 전과 달리 자기 사람들과 함께 한다는 점을 보여준다. 복수의 끝이 공허하지 않도록 '무엇을 위해 복수했나'를 정산한다."}]}]},{"id":"g11-awakening-hunter-growth","category":"현대판타지·회귀","name":"회귀 각성·헌터 성장형","desc":"게이트·던전·몬스터가 출현한 현대를 배경으로, 약했거나 죽었던 헌터가 종말 직전의 미래 기억을 안고 회귀해 최강으로 성장하는 구조. '나 혼자만 레벨업', 'SSS급 죽어야 사는 헌터', '템빨' 류 헌터물 회귀의 정석. 핵심 쾌감은 미래에 올 재앙·레이드·아이템 위치를 미리 알고 선점·역공하는 것.","beats":[{"title":"1막 — 종말의 기억과 재시작","synopsis":"세계가 어떻게 멸망했는지, 주인공이 왜 그 끝을 막아야 하는지를 보여주고 회귀로 두 번째 기회를 부여한다.","folder":true,"children":[{"title":"최종 보스 앞의 죽음","synopsis":"종말의 마지막 전장(인류 멸망 직전, 마왕·차원침공·세계수 붕괴)에서 주인공이 죽는다. 동료의 희생, 막지 못한 재앙의 스케일을 보여줘 '다시 하면 막을 수 있다'는 동기를 심는다."},{"title":"각성 직전으로 회귀","synopsis":"최초의 게이트 출현 직전, 혹은 자신이 최약체 E급으로 각성하던 그날로 돌아온다. 회귀 전엔 몰랐던 '시스템'의 진짜 사용법을 처음부터 안다는 우위를 설정한다."},{"title":"히든 클래스·시스템 선점","synopsis":"남들은 모르는 히든 직업, 숨겨진 스킬 트리, 시스템의 버그성 메커니즘을 회귀 지식으로 즉시 확보. 출발선부터 다르다는 성장 치트를 깐다. 단, 대가·페널티를 함께 설계해 무적이 되지 않게 한다."}]},{"title":"2막 — 미래 지식 기반 폭풍 성장","synopsis":"아직 아무도 모르는 던전·재료·이벤트를 선점하며 회귀 전보다 압도적으로 빠르게 강해진다.","folder":true,"children":[{"title":"노다지 던전 선점","synopsis":"미래에 '발견될' 노른자 던전·필드 보스·성장형 아이템을 남보다 먼저 공략. 적정 레벨을 무시한 무리수를 회귀 지식과 컨트롤로 돌파하는 사이다 던전 런을 연출한다."},{"title":"미래의 강자 영입·구원","synopsis":"회귀 전 비참하게 죽었거나 타락한 미래의 거물을 미리 구하거나 동료로 삼는다. 그들의 죽음을 막는 '운명 바꾸기' 서사로 감정선을 보강한다."},{"title":"랭킹·길드 무대 등장","synopsis":"정체를 숨긴 채(혹은 충격적으로 드러내며) 헌터 랭킹·각성자 협회·대형 길드 무대에 등장. 기성 강자들의 코를 납작하게 만드는 첫 공개 무력 시위를 배치한다."},{"title":"고정관념 깨기","synopsis":"세상이 '불가능'이라 믿는 것(혼자 레이드, 즉사 보스 솔킬, 등급 무시 성장)을 깨뜨려 주인공의 특이성을 각인. 회귀 헌터물의 '나만 다른 룰' 쾌감을 강화한다."}]},{"title":"3막 — 바뀐 미래·예정된 대재앙","synopsis":"주인공의 개입으로 타임라인이 변하면서, 알던 재앙이 더 빨리·다르게 오고 새 위협이 출현한다.","folder":true,"children":[{"title":"앞당겨진 재앙","synopsis":"미래에 일어날 대규모 게이트 브레이크·차원 침공이 회귀 전과 다른 시점·양상으로 발생. 회귀 지식의 유통기한을 보여주며 진짜 실력으로 막게 한다."},{"title":"회귀의 비밀 단서","synopsis":"주인공이 왜 회귀했는지, 자신만 회귀자가 아닐 수도 있다는 떡밥을 깐다. 또 다른 회귀자·예언자·관리자 같은 메타 존재를 암시해 후반 떡밥을 심는다."},{"title":"한계 돌파 각성","synopsis":"기존 성장 곡선으로는 못 이기는 벽 앞에서 2차 각성·각성 진화·전직을 통해 격을 한 단계 끌어올린다. 위기→각성→역전의 헌터물 황금 패턴을 정점에서 사용한다."}]},{"title":"4막 — 종말 저지와 새 세계","synopsis":"회귀의 목적이었던 종말을 막고, 회귀 전과 전혀 다른 결말로 세계와 자신을 구원한다.","folder":true,"children":[{"title":"최종 결전 재림","synopsis":"1막에서 자신을 죽였던 그 최종 위협과 다시 맞선다. 이번엔 동료들이 살아있고 자신이 준비됐다는 대비로 수미상관을 완성한다."},{"title":"운명을 바꾼 한 수","synopsis":"회귀 전 패배의 결정적 원인을 이번엔 알고 차단한다. '왜 그때 졌는가'의 퍼즐을 해소하며 승리의 논리를 명확히 한다."},{"title":"지킨 세계","synopsis":"멸망하지 않은 세계, 살아남은 동료들과의 일상으로 마무리. 회귀의 무게(혼자만 기억하는 또 다른 미래)를 짧게 정산하며 여운을 남긴다."}]}]},{"id":"g11-pro-redo-mastery","category":"현대판타지·회귀","name":"회귀 전문직 재능형","desc":"정점에 올랐다 추락(혹은 은퇴·사망)한 전문가가 신인 시절로 회귀해, 한 분야의 미래 트렌드·노하우·인맥을 알고 다시 최고가 되는 구조. 연예/아이돌('데뷔 못 하면 죽는 병'), 스포츠, 의사, 셰프, PD·작가, 트레이더 등 직업물 회귀의 대표 결. 핵심 쾌감은 '경험치+미래 트렌드'로 신인이 베테랑을 압도하는 갭모에.","beats":[{"title":"1단계 — 정점에서의 추락과 귀환","synopsis":"주인공이 한때 정점이었으나 무너진 이유를 보여주고, 가장 푸르렀던 시작점으로 되돌린다.","folder":true,"children":[{"title":"전성기와 몰락","synopsis":"회귀 전 주인공의 전문성(최고의 실력)과 동시에 그를 무너뜨린 것(부상, 누명, 번아웃, 매장)을 압축해 보여준다. '실력은 있는데 운·타이밍이 없었다'는 회한을 심는다."},{"title":"데뷔 직전으로","synopsis":"신인·지망생·연습생 시절로 회귀. 가진 건 미숙한 몸과 무명이지만 머릿속엔 수십 년 노하우가 있다는 갭을 설정한다."},{"title":"재능의 재발견","synopsis":"예전엔 늦게 깨달은 자신의 진짜 강점·포지션을 처음부터 정조준한다. 회귀 전 시행착오를 건너뛰고 곧장 최적 루트를 타는 효율의 쾌감을 깐다."}]},{"title":"2단계 — 신인의 가면, 베테랑의 실력","synopsis":"무명 신인이 주변의 무시를 받지만 베테랑급 결과물로 판을 뒤집기 시작한다.","folder":true,"children":[{"title":"첫 무대·첫 결과","synopsis":"오디션, 데뷔전, 첫 수술, 첫 거래 등 첫 시험대에서 신인답지 않은 완성도로 좌중을 압도한다. '재능충'을 알아보는 조력자(스승·대표·감독)의 반응으로 임팩트를 키운다."},{"title":"미래 트렌드 선점","synopsis":"곧 유행할 콘셉트·전술·기술·시장을 남보다 먼저 도입. 단순 회귀 정보가 아니라 '왜 그게 통할지'를 주인공이 이해하고 적용하게 해 설득력을 준다."},{"title":"라이벌 등장","synopsis":"회귀 전 자신을 이겼거나 동급이었던 천재 라이벌을, 이번엔 신인 대 신인으로 마주친다. 장기 라이벌 구도와 선의의 경쟁 동기를 세팅한다."},{"title":"업계 정치의 벽","synopsis":"실력만으론 못 넘는 업계 구조(낙하산, 파벌, 갑질 기획사·구단·병원)를 마주한다. 회귀 전 당했던 부조리를 이번엔 미리 알고 회피·역이용하는 영리함을 보여준다."}]},{"title":"3단계 — 정상권 진입과 위기","synopsis":"주인공이 빠르게 정상권에 오르지만, 과거의 트라우마·예정된 사건이 재현되려 한다.","folder":true,"children":[{"title":"스타덤·정상권","synopsis":"데뷔작 대박, 우승, 명의 등극 등 가시적 성공으로 업계 정상권에 안착. 회귀 전보다 훨씬 이른 성공의 쾌감을 정점에 둔다."},{"title":"재현되는 비극의 그림자","synopsis":"회귀 전 몰락의 원인(부상 위기, 사고, 음모)이 다시 다가온다. 알기에 막을 수 있을지 긴장을 건다. 단, 나비효과로 양상이 미묘하게 달라지게 한다."},{"title":"진짜 동료·진짜 의미","synopsis":"성공만 좇던 회귀 전과 달리, 함께 갈 사람·진짜 하고 싶은 일을 발견한다. 직업물의 '왜 이 일을 하는가' 주제를 환기한다."}]},{"title":"4단계 — 전설의 완성","synopsis":"회귀 전엔 닿지 못한 최고의 자리에, 이번엔 후회 없이 도달한다.","folder":true,"children":[{"title":"운명의 사건 극복","synopsis":"3단계에서 다가온 비극을 미래 지식과 그동안의 성장으로 막아낸다. '이번엔 다르다'를 행동으로 증명한다."},{"title":"최고의 무대","synopsis":"월드 무대·세계대회·전설적 작품 등 회귀 전엔 상상도 못 한 정점의 결과물을 낸다. 그동안 쌓인 모든 떡밥과 성장을 한 무대에 수렴시킨다."},{"title":"후회 없는 정상","synopsis":"두 번째 인생에서 실력과 행복을 모두 거머쥔 주인공을 보여준다. 회귀 전 외로웠던 정점과 대비해, 함께하는 정점의 의미를 정산한다."}]}]},{"id":"g11-apocalypse-loop-survival","category":"현대판타지·회귀","name":"회귀 종말 생존·루프형","desc":"재난·아포칼립스가 닥친 세계에서 주인공이 죽을 때마다(혹은 한 번의 회귀로) 과거로 돌아와 생존 루트를 갱신하는 구조. '데드 머니'식 무한 루프, '재난 회귀', '서울역 좀비' 류 재난·생존 회귀물의 결. 핵심 쾌감은 죽음→정보 획득→다음 회차 최적화라는 로그라이크적 공략과, 정해진 파국 속 인간 군상극.","beats":[{"title":"1막 — 첫 종말과 첫 회귀","synopsis":"재난이 어떻게 시작되는지, 주인공이 어떻게 죽고 돌아오는지 루프 규칙을 독자에게 학습시킨다.","folder":true,"children":[{"title":"재난의 발발","synopsis":"평범한 일상이 한순간에 붕괴하는 D-day. 좀비·괴수·메시지 시스템·천재지변 등 재난의 룰을 인상적인 첫 장면으로 각인한다. 주인공이 무력하게 휩쓸리는 모습으로 시작한다."},{"title":"무력한 죽음","synopsis":"정보도 힘도 없던 주인공이 1회차에서 비참하게 죽는다. 누구를 못 지켰고 무엇을 몰라 죽었는지를 명확히 해 다음 회차의 목표를 만든다."},{"title":"그날 아침으로","synopsis":"재난 발발 직전(혹은 며칠 전)으로 회귀. 죽음으로 얻은 정보(재난 시각, 안전지대, 위협의 정체)를 유일한 자산으로 들고 돌아온다는 루프 규칙을 확정한다."}]},{"title":"2막 — 죽음으로 배우는 공략","synopsis":"여러 회차(혹은 한 번의 회귀를 알뜰히 활용)를 통해 생존 변수를 하나씩 파악하고 최적 루트를 만든다.","folder":true,"children":[{"title":"사전 준비·선점","synopsis":"재난 전 골든타임에 물자·무기·거점·탈출로를 선점한다. 남들은 평화로운데 혼자 종말을 대비하는 아이러니와 긴박함을 동시에 연출한다."},{"title":"변수의 발견","synopsis":"회귀 지식으로도 예측 못 한 변수(다른 생존자, 돌연변이, 시스템의 함정)를 만난다. 정보만으론 부족하고 판단·운이 개입함을 보여줘 긴장을 유지한다."},{"title":"또 한 번의 죽음(또는 위기)","synopsis":"준비가 완벽해 보여도 실패하는 회차를 배치해 '이 종말은 만만치 않다'를 각인. 실패로 새 정보를 얻어 다음 시도를 정교화하는 로그라이크 쾌감을 만든다."},{"title":"사람 모으기","synopsis":"혼자 못 넘는 구간을 위해 신뢰할 동료를 선별·포섭. 회귀 지식으로 누가 배신자이고 누가 진국인지 알아 인간 군상극의 토대를 깐다."}]},{"title":"3막 — 진실에 다가가다","synopsis":"재난의 근원과 회귀의 메커니즘이 연결되어 있음을 알아채고, 단순 생존에서 종식으로 목표가 확장된다.","folder":true,"children":[{"title":"재난의 근원 추적","synopsis":"재난이 자연재해가 아니라 누군가/무언가에 의해 설계됐음을 시사하는 단서를 모은다. 생존 게임을 풀어야 할 미스터리로 격상한다."},{"title":"회귀의 대가","synopsis":"루프·회귀에 대가(기억 마모, 정신 붕괴, 회귀 횟수 제한, 다른 누군가의 희생)가 있음을 드러낸다. '무한히 다시 할 수 없다'는 제약으로 한 수 한 수의 무게를 키운다."},{"title":"마지막 회차 결심","synopsis":"더는 죽을 수 없는(혹은 죽고 싶지 않은) 상황에서 '이번이 마지막'이라는 각오로 진엔딩 루트에 진입한다."}]},{"title":"4막 — 파국의 종식","synopsis":"재난의 근원을 끊거나 운명을 바꿔, 반복되던 종말의 고리를 끝낸다.","folder":true,"children":[{"title":"최적 루트 실행","synopsis":"그동안 모은 모든 정보·동료·자원을 한 번의 시도에 쏟아붓는다. 앞선 모든 실패가 이 한 수의 복선이었음을 회수한다."},{"title":"근원과의 대면","synopsis":"재난의 설계자·근원(시스템 관리자, 변종 모체, 차원의 균열)과 정면 대결. 단순 무력이 아니라 회귀로 쌓은 통찰로 약점을 찌른다."},{"title":"끝난 반복","synopsis":"루프가 멈추고 일상이 돌아온다. 혼자만 기억하는 무수한 죽음과 회차들의 무게를 짧게 정산하며, 살아남은 자들과의 평범한 내일로 마무리한다."}]}]},{"id":"g11-system-secret-conspiracy","category":"현대판타지·회귀","name":"회귀 비밀결사·각성 음모형","desc":"초능력·이능·각성자가 음지에서 활동하는 현대를 배경으로, 거대 조직(헌터 협회, 비밀결사, 정부 기관, 길드 연합)의 음모에 희생됐던 주인공이 회귀해 조직 내부에서 판을 뒤집는 구조. 도시 어반판타지의 음모론·조직 정치 결. 핵심 쾌감은 정보전·세력전·정체 숨기기와, 미래에 적이 될 자들을 미리 솎아내는 첩보적 긴장.","beats":[{"title":"1부 — 토사구팽과 귀환","synopsis":"주인공이 조직에 이용당하고 버려진 진실을 보여주고, 그 조직에 막 발을 들이던 시점으로 되돌린다.","folder":true,"children":[{"title":"버림받은 말","synopsis":"회귀 전 주인공이 조직의 비밀 작전에서 소모품으로 쓰이고 제거당하는 장면. 자신이 알던 '정의로운 조직'이 거대한 거짓이었음을 깨닫는 순간을 강렬히 그린다."},{"title":"입문 시점으로","synopsis":"각성 직후, 혹은 조직에 처음 스카우트되던 시점으로 회귀. 이번엔 조직의 진짜 얼굴과 미래의 배신자들을 모두 알고 들어간다는 정보 우위를 설정한다."},{"title":"정체 은닉 결심","synopsis":"회귀자임을, 그리고 진짜 실력·의도를 숨긴 채 조직 내부에 잠입하기로 결심. 적의 적에게 둘러싸인 첩보극의 긴장 톤을 깐다."}]},{"title":"2부 — 잠입과 세력 구축","synopsis":"조직 안에서 신뢰를 얻고 자기 사람을 심으며, 미래의 적과 아군을 분류해 나간다.","folder":true,"children":[{"title":"실력의 위장 공개","synopsis":"너무 강하면 견제받고 너무 약하면 버려진다. 적당히 유능한 '쓸만한 신인'을 연기하며 윗선의 신임을 얻는 줄타기를 보여준다."},{"title":"내부 정보망 구축","synopsis":"조직의 비밀 자료, 파벌 구도, 미래의 배신 타임라인을 회귀 지식과 잠입으로 교차 확인. 누가 흑막의 끄나풀인지 색출해 나간다."},{"title":"아군 포섭","synopsis":"회귀 전 함께 희생됐거나 끝까지 신의를 지킨 동료를 미리 자기 편으로 만든다. 그들의 미래 죽음을 막으며 충성을 얻는 감정선을 깐다."},{"title":"첫 음모 차단","synopsis":"조직(또는 흑막)이 꾸미는 첫 사건을 미리 알고 무산시키거나 가로챈다. 단, 자신이 한 일임을 들키지 않게 처리하는 첩보적 쾌감을 연출한다."}]},{"title":"3부 — 흑막의 윤곽","synopsis":"단일 조직이 아니라 더 깊은 흑막·상위 세력이 있음을 알게 되고, 정보전이 세력전으로 확대된다.","folder":true,"children":[{"title":"더 큰 그림자","synopsis":"주인공을 버린 조직조차 더 큰 흑막의 일부였음을 드러낸다. 초국가적 결사, 이세계 세력, 신적 존재 등 적의 스케일을 한 단계 키운다."},{"title":"정체의 위기","synopsis":"주인공이 회귀자·내통자임이 들킬 뻔하는 위기. 미래 지식이 오히려 의심의 단서가 되는 역설로 긴장을 최고조로 끌어올린다."},{"title":"세력전 점화","synopsis":"음지의 정보전이 조직 대 조직, 파벌 대 파벌의 공개 충돌로 비화. 주인공이 키운 세력이 처음으로 전면에 나선다."}]},{"title":"4부 — 판의 전복","synopsis":"흑막을 무너뜨리고 부패한 질서를 갈아엎어, 회귀 전과 다른 세계의 균형을 만든다.","folder":true,"children":[{"title":"내부 붕괴 유도","synopsis":"그동안 심어둔 정보·아군·증거를 동시에 터뜨려 조직과 흑막을 내부에서 무너뜨린다. 첩보극답게 무력보다 한 수 앞선 설계로 승부한다."},{"title":"흑막과의 결착","synopsis":"최종 흑막과 정면으로 마주한다. 주인공이 왜 회귀했는지, 흑막이 무엇을 노렸는지의 전모를 밝히며 핵심 떡밥을 회수한다."},{"title":"새로운 균형","synopsis":"부패한 옛 질서가 무너지고, 주인공이 만든 새 질서(개혁된 조직, 새 연합)가 자리잡는다. 또 다른 회귀자·잔존 세력의 떡밥을 살짝 남겨 여운을 준다."}]}]}]
